// cicilan.js — logika form Cicilan pada txModal (Tambah/Edit Transaksi Keuangan).
// Dipindah ke modules/finance/cicilan.js (Sesi 16 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// Dipisah dari transaksi.js (2026-07-11, lihat CLAUDE.md catatan kerja "split
// transaksi.js") murni sebagai pengelompokan ulang file, BUKAN perubahan
// perilaku. Semua fungsi di sini tetap global (bukan module/namespace, sama
// seperti sebelumnya di transaksi.js) karena dipanggil langsung dari HTML lewat
// atribut `data-action`/`onchange`/`oninput` di modals.js (mis. txCicilanNama
// pakai oninput="syncCicilanPreview()"), dan juga dipanggil dari transaksi.js
// sendiri (setPayMethod, openTxModal, editTx, _saveTxInner). Variabel state
// cicilanLastInput/cicilanSharedLastInput/cicilanDateLinked tetap dideklarasikan
// di features-helpers-global-security.js (dimuat sebelum file ini di build.js),
// TIDAK dipindah, supaya file lain yang sudah menulis ke variabel itu
// (transaksi.js, worthit.js) tidak perlu diubah.
function validateCicilanFields(){
const totalEl=document.getElementById('txCicilanTotal');
const tenorEl=document.getElementById('txCicilanTenor');
const bungaEl=document.getElementById('txCicilanBunga');
const total=parseFloat(totalEl.value);
const tenor=parseInt(tenorEl.value);
const bungaRaw=bungaEl.value.trim();
const bunga=bungaRaw===''?0:parseFloat(bungaRaw);
if(!totalEl.value.trim()||isNaN(total)||total<=0){toast('⚠️ Total harga cicilan harus lebih dari 0');totalEl.focus();return false;}
if(isNaN(tenor)||tenor<=0){toast('⚠️ Tenor cicilan tidak valid');return false;}
if(isNaN(bunga)||bunga<0){toast('⚠️ Bunga/biaya cicilan tidak boleh negatif');bungaEl.focus();return false;}
return true;
}
// Logika hitung murni (tanpa sentuh DOM) -- dipakai oleh syncCicilanPreview() di bawah
// DAN oleh self-test (lihat features-sheets-pwa-selftest.js), supaya self-test cukup panggil fungsi
// ini langsung tanpa perlu buka txModal asli / mengganggu form yang sedang diisi user.
function calcCicilanPerBulanFromTotal(hargaPokok,tenor,bungaPct){
const totalBayar=hargaPokok*(1+bungaPct/100);
return{perBulan:Math.ceil(totalBayar/tenor),totalBayar};
}
function calcCicilanTotalFromPerBulan(perBulan,tenor,bungaPct){
const totalBayar=perBulan*tenor;
return{hargaPokok:Math.round(totalBayar/(1+bungaPct/100)),totalBayar};
}
function syncCicilanPreview(src){
if(src==='total'||src==='perbulan') cicilanLastInput=src;
if(src==='sharedPct'||src==='sharedNominal') cicilanSharedLastInput=src==='sharedPct'?'pct':'nominal';
const totalEl=document.getElementById('txCicilanTotal');
const perBulanEl=document.getElementById('txCicilanPerBulan');
const tenor=parseInt(document.getElementById('txCicilanTenor').value)||6;
const bunga=parseFloat(document.getElementById('txCicilanBunga').value)||0;
const prev=document.getElementById('txCicilanPreview');
let totalBayar, perBulan, hargaPokok;
if(cicilanLastInput==='perbulan'){
perBulan=parseFloat(perBulanEl.value)||0;
if(!perBulan||perBulan<=0){prev.style.display='none';document.getElementById('txAmt').value='';totalEl.value='';return;}
({hargaPokok,totalBayar}=calcCicilanTotalFromPerBulan(perBulan,tenor,bunga));
totalEl.value=hargaPokok;
} else {
hargaPokok=parseFloat(totalEl.value)||0;
if(!hargaPokok||hargaPokok<=0){prev.style.display='none';document.getElementById('txAmt').value='';perBulanEl.value='';return;}
({perBulan,totalBayar}=calcCicilanPerBulanFromTotal(hargaPokok,tenor,bunga));
perBulanEl.value=perBulan;
}
const sisaTenor=tenor-1;
document.getElementById('prevPerBulan').textContent=fmtFull(perBulan);
document.getElementById('prevTotal').textContent=fmtFull(totalBayar);
document.getElementById('prevSisa').textContent=sisaTenor>0?`${sisaTenor}x lagi (${fmtFull(perBulan*sisaTenor)})`: 'Lunas setelah ini';
prev.style.display='block';
const mineWrap=document.getElementById('prevMineRow');
const sharedPrevEl=document.getElementById('txCicilanSharedPreview');
const sh=getCicilanSharedMine(perBulan);
let perBulanMine=perBulan;
if(sh.shared){
perBulanMine=sh.mine;
if(cicilanSharedLastInput==='nominal'){document.getElementById('txCicilanSharedPct').value=sh.pct;}
else{document.getElementById('txCicilanSharedNominal').value=sh.mine;}
document.getElementById('prevPerBulanMine').textContent=fmtFull(perBulanMine);
mineWrap.style.display='block';
if(sharedPrevEl)sharedPrevEl.textContent=`👫 Porsi kamu: ${fmt(perBulanMine)}/bulan (${sh.pct}%) dari total ${fmt(perBulan)}/bulan (sisanya ${fmt(perBulan-perBulanMine)} ditanggung pihak lain)`;
} else {
mineWrap.style.display='none';
if(sharedPrevEl)sharedPrevEl.textContent='';
}
document.getElementById('txAmt').value=perBulanMine;
}
function getCicilanSharedMine(perBulanFull){
const chk=document.getElementById('txCicilanShared');
const shared=chk&&chk.checked;
if(!shared)return{shared:false,pct:null,mine:perBulanFull};
let pct,mine;
if(cicilanSharedLastInput==='nominal'){
mine=parseFloat(document.getElementById('txCicilanSharedNominal').value)||0;
mine=Math.min(Math.max(mine,0),perBulanFull);
pct=perBulanFull>0?Math.min(99,Math.max(1,Math.round((mine/perBulanFull*100)*10)/10)):50;
} else {
pct=Math.min(99,Math.max(1,parseFloat(document.getElementById('txCicilanSharedPct').value)||50));
mine=Math.round(perBulanFull*pct/100);
}
return{shared:true,pct,mine};
}
function toggleCicilanSharedFields(){
const shared=document.getElementById('txCicilanShared').checked;
document.getElementById('txCicilanSharedWrap').style.display=shared?'block':'none';
if(shared) cicilanSharedLastInput='pct';
syncCicilanPreview();
}
function syncCicilanDate(src){
if(curPayMethod!=='cicilan'||cicilanDateLinked)return;
const dateEl=document.getElementById('txDate');
const dueEl=document.getElementById('txCicilanDue');
if(!dateEl.value&&!dueEl.value)return;
if(src==='date') dueEl.value=dateEl.value;
else dateEl.value=dueEl.value;
}
function openCicilanHistoryFromTx(){
if(!txEditLinkedBillId)return;
closeModal('txModal');
openBillHistory(txEditLinkedBillId);
}

// tx-bbm.js — logika panel "Sinkron ke Catatan Mobil (BBM)" pada txModal
// Dipindah ke modules/finance/tx-bbm.js (Sesi 16 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// (Tambah/Edit Transaksi Keuangan). Dipisah dari transaksi.js (2026-07-11,
// lihat CLAUDE.md catatan kerja "split transaksi.js" bagian ke-6) murni
// sebagai pengelompokan ulang file, BUKAN perubahan perilaku. Semua fungsi di
// sini tetap global (bukan module/namespace) karena dipanggil dari:
//  - transaksi.js sendiri (updateTxVehiclePanels, editTx, openTxModal, _saveTxInner)
//  - HTML lewat atribut oninput/onchange di modals.js (mis. txBbmLiter pakai
//    oninput="syncTxBbmAmt()")
//  - file lain lintas-bundle: recordBbmLog dipanggil dari BBM._saveInner di
//    car-notes.js (GROUP_A) -- ini AMAN
//    walau tx-bbm.js ada di GROUP_B (dimuat setelah GROUP_A), karena
//    pemanggilannya baru terjadi saat user berinteraksi (lazy), bukan saat
//    file GROUP_A pertama kali di-parse/load.
function populateTxBbmVehicleSelect(){
const sel=document.getElementById('txBbmVehicle');
if(!sel||!D.vehicles)return;
const cur=sel.value;
sel.innerHTML=D.vehicles.map(v=>`<option value="${v.id}">${v.emoji} ${escapeHtml(v.name)}</option>`).join('');
const fallback=(typeof curVehicleId!=='undefined'&&D.vehicles.find(v=>v.id===curVehicleId))?curVehicleId:(D.vehicles[0]&&D.vehicles[0].id);
sel.value=cur&&D.vehicles.find(v=>v.id===cur)?cur:fallback;
}
function toggleTxBbmFields(){
const chk=document.getElementById('txSyncBbm');
const fields=document.getElementById('txBbmFields');
if(!chk||!fields)return;
fields.style.display=chk.checked?'block':'none';
if(chk.checked)populateTxBbmVehicleSelect();
}
function syncTxBbmAmt(){
const liter=parseFloat(document.getElementById('txBbmLiter').value);
const harga=parseFloat(document.getElementById('txBbmHargaL').value);
if(liter&&harga){
document.getElementById('txAmt').value=Math.round(liter*harga);
}else{
syncTxAmtToLiterForce();
}
}
function syncTxAmtToLiter(){
const chk=document.getElementById('txSyncBbm');
if(!chk||!chk.checked)return;
syncTxAmtToLiterForce();
}
function syncTxAmtToLiterForce(){
const hargaEl=document.getElementById('txBbmHargaL');
const literEl=document.getElementById('txBbmLiter');
const harga=parseFloat(hargaEl.value);
const amt=parseFloat(document.getElementById('txAmt').value);
if(harga>0&&amt>0){
literEl.value=(amt/harga).toFixed(2);
}
}
// Fungsi murni (tidak baca/tulis DOM) -- dipakai baik dari applyTxBbmFromTx di
// bawah (sinkron dari form Transaksi umum) maupun dari BBM._saveInner (modal
// "Catat Isi BBM" khusus Car Notes, di file lain).
function recordBbmLog(opts){
let harga=opts.harga;
if(!harga&&opts.liter)harga=Math.round(opts.cost/opts.liter);
if(!D.bbmLogs)D.bbmLogs=[];
if(opts.existingBbmId){
const b=D.bbmLogs.find(x=>x.id===opts.existingBbmId);
if(b){
Object.assign(b,{date:opts.date,km:opts.km,liter:opts.liter,harga,cost:opts.cost,spbu:opts.spbu,fullTank:opts.fullTank,note:opts.note,accountId:opts.accountId,vehicleId:opts.vehicleId||b.vehicleId});
return{bbmId:b.id,isNew:false,harga};
}
}
const bbmId=uid();
D.bbmLogs.push({id:bbmId,vehicleId:opts.vehicleId,date:opts.date,km:opts.km,liter:opts.liter,harga,cost:opts.cost,spbu:opts.spbu,fullTank:opts.fullTank,note:opts.note,accountId:opts.accountId,txLinkId:opts.txId});
return{bbmId,isNew:true,harga};
}
function applyTxBbmFromTx(txId,amt,date,accId,note,existingTx){
const chk=document.getElementById('txSyncBbm');
if(!chk||!chk.checked)return;
const panel=document.getElementById('txBbmPanel');
if(!panel||panel.style.display==='none')return;
const km=parseFloat(document.getElementById('txBbmKm').value);
const liter=parseFloat(document.getElementById('txBbmLiter').value);
const harga=parseFloat(document.getElementById('txBbmHargaL').value);
if(!km||!liter){toast('⚠️ Isi KM & Liter BBM dulu, atau hilangkan centang sinkron BBM');return;}
const spbu=document.getElementById('txBbmSpbu').value.trim();
const fullTank=document.getElementById('txBbmFull').checked;
const vehSel=document.getElementById('txBbmVehicle');
const vehicleId=vehSel&&vehSel.value?vehSel.value:((typeof curVehicleId!=='undefined'&&curVehicleId)||(D.vehicles[0]&&D.vehicles[0].id));
const result=recordBbmLog({
vehicleId,date,km,liter,harga,cost:amt,spbu,fullTank,note,accountId:accId,
txId,existingBbmId:(existingTx&&existingTx.bbmLinkId)?existingTx.bbmLinkId:null
});
if(!existingTx||!existingTx.bbmLinkId){
const tx=existingTx||D.transactions.find(t=>t.id===txId);
if(tx)tx.bbmLinkId=result.bbmId;
}
toast('⛽ Catatan BBM tersinkron ke Catatan Mobil');
}

// tx-stok-sparepart.js — logika panel "Tambah ke Stok Sparepart juga?" pada
// Dipindah ke modules/finance/tx-stok-sparepart.js (Sesi 16 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// txModal (Tambah/Edit Transaksi Keuangan). Dipisah dari transaksi.js
// (2026-07-11, lihat CLAUDE.md catatan kerja "split transaksi.js" bagian
// ke-7) murni sebagai pengelompokan ulang file, BUKAN perubahan perilaku.
// Semua fungsi di sini tetap global karena dipanggil dari:
//  - transaksi.js sendiri (updateTxVehiclePanels, _saveTxInner)
//  - HTML lewat atribut onchange di modals.js (mis. txStockItem pakai
//    onchange="onTxStockItemChange()")
//  - scan-ocr.js (auto-centang & isi panel stok saat hasil scan struk
//    terdeteksi sparepart)
// revertStockPurchase(partId,qty) — Tahap 8B: kebalikan applyStockPurchase(),
// dipakai saat transaksi Keuangan yang menambah stok Inventaris DIEDIT
// (checkbox dimatikan/qty diganti) atau DIHAPUS -> qty yg pernah ditambahkan
// dikurangi lagi (single source of truth = D.partsStock, TIDAK menyentuh
// harga/priceHistory yg sudah tercatat, sesuai pola revertStockUsage() di
// car-notes.js utk arah sebaliknya/pemakaian servis).
function revertStockPurchase(partId,qty){
if(!partId||!qty)return;
const p=D.partsStock.find(x=>x.id===partId);
if(p)p.qty=Math.max(0,(p.qty||0)-qty);
}
// applyStockPurchase(p,qty,unitPrice,purchaseDate,txId) — Tahap 8A: satu titik
// tunggal utk update field pembelian di item D.partsStock (dipanggil dari
// applyTxStockFromTx di bawah, integrasi Keuangan -> Inventaris/Vehicle
// Catalog/Car Notes). TIDAK mengubah cara qty ditambah (masih p.qty+=qty,
// perilaku lama persis), cuma MENAMBAH field baru: lastPrice (harga satuan
// pembelian terakhir), avgPrice (rata-rata tertimbang lintas semua pembelian
// — dipakai juga sbg p.price utk perhitungan "Nilai Persediaan" yg sudah ada
// di Dashboard Sparepart 7E-5), lastPurchaseDate, priceHistory[] (riwayat
// harga per transaksi), txRefs[]/lastTxId (referensi transaksi Keuangan).
// unitPrice<=0 (mis. transaksi tanpa jumlah valid) -> qty tetap nambah tapi
// field harga TIDAK disentuh (menghindari harga 0 mengotori rata-rata).
function applyStockPurchase(p,qty,unitPrice,purchaseDate,txId){
const prevQty=p.qty||0;
p.qty=prevQty+qty;
if(unitPrice>0){
p.lastPrice=unitPrice;
const prevAvg=(typeof p.avgPrice==='number'&&p.avgPrice>0)?p.avgPrice:((p.price>0)?p.price:unitPrice);
const totalQtyForAvg=prevQty+qty;
p.avgPrice=totalQtyForAvg>0?(((prevAvg*prevQty)+(unitPrice*qty))/totalQtyForAvg):unitPrice;
p.price=p.avgPrice;
}
p.lastPurchaseDate=purchaseDate;
if(!Array.isArray(p.priceHistory))p.priceHistory=[];
p.priceHistory.push({date:purchaseDate,qty,price:unitPrice||0,txId:txId||null});
if(txId){
if(!Array.isArray(p.txRefs))p.txRefs=[];
if(!p.txRefs.includes(txId))p.txRefs.push(txId);
p.lastTxId=txId;
}
}
// syncPartsStockFromCatalog(catalogItem) — Tahap 9 (Jembatan Vehicle
// Catalog <-> Stok Sparepart Keuangan): cari-atau-buat 1 baris D.partsStock
// yang TERHUBUNG (field `catalogId`) ke 1 part di VehicleCatalog (katalog
// suku cadang, IDBStore terpisah — lihat modules/vehicle/vehicle-catalog.js).
// Pola bridge ini SAMA PERSIS `catalogPartLinkedStockId` yang sudah dipakai
// alur Servis di car-notes.js (VehicleCatalog TETAP identitas/OEM/barcode,
// D.partsStock TETAP satu-satunya pemilik qty/harga/riwayat pembelian —
// konsisten aturan ACR-001 "VehicleCatalog tidak pernah menyentuh D").
// Fungsi MURNI terhadap D (baca/tulis D.partsStock & D.sparepartCats saja,
// TIDAK memanggil save() -- pemanggil yang sudah punya 1 titik save() per
// alur, sama seperti applyTxStockFromTx() di bawah).
function syncPartsStockFromCatalog(catalogItem){
if(!catalogItem||!catalogItem.id)return null;
const existing=D.partsStock.find(p=>p.catalogId===catalogItem.id);
if(existing){
if(catalogItem.partName&&existing.name!==catalogItem.partName)existing.name=catalogItem.partName;
return existing;
}
const catName=(catalogItem.category||'Umum').trim()||'Umum';
let cat=D.sparepartCats.find(c=>c.name.toLowerCase()===catName.toLowerCase());
if(!cat){
// Sesi 295 (bugfix, permintaan eksplisit user): kategori auto dari scan
// Katalog Suku Cadang ini TUJUANNYA cuma pengelompokan stok (biar
// D.partsStock punya catId) -- BUKAN jadwal servis, makanya intervalKm
// sengaja 0. Dulu tidak ada showInReminder, jadi kategori "sampah" spt
// "E-2 Cylinder Head Cover" (nama kategori part dari katalog/torsi) ikut
// numpuk di 🔔 Pengingat Servis dgn "Interval 0 km" & selalu "Lewat".
// showInReminder:false = default disembunyikan dari Pengingat sampai user
// SENGAJA mengaktifkannya (isi interval + toggle di 🔧 Kelola Kategori
// Sparepart & Interval Servis) -- lihat filter di Servis.renderReminder()
// (car-notes.js) & renderDashboardServisReminder() (modules-render.js).
cat={id:'sp_'+Date.now(),name:catName,code:codeFromName(catName),intervalKm:0,showInReminder:false};
D.sparepartCats.push(cat);
}
const prefix=cat.code||codeFromName(catName);
const seq=D.partsStock.filter(p=>p.code&&p.code.startsWith(prefix+'-')).length+1;
const code=(catalogItem.barcode||catalogItem.oemCode||(prefix+'-'+String(seq).padStart(3,'0')));
const np={id:'st_'+Date.now(),name:catalogItem.partName||'Part dari Katalog',catId:cat.id,code,qty:0,unit:'pcs',minStock:1,price:catalogItem.price||0,note:'Terhubung dari Katalog Suku Cadang (scan)',catalogId:catalogItem.id};
D.partsStock.push(np);
return np;
}
// txStockScanPartVia(adapterName) — inti bersama tombol "📷 Scan Kode Part"
// (adapter 'camera') & "🖼️ Scan dari Galeri" (adapter 'gallery') di
// txStockPanel (modal Tambah/Edit Transaksi Keuangan). Reuse 100%
// SparepartScanner.scan(adapterName) -- 'camera' & 'gallery' SUDAH ADA sbg
// adapter terdaftar di sparepart-scanner.js (Tahap 7B-1/7B-2), TIDAK ada
// adapter/logic scan baru di sini -- lalu VehicleCatalog.handleScan()
// (sudah ada) utk cari/bikin draft part, lalu syncPartsStockFromCatalog()
// di atas utk hubungkan ke baris stok yg dipilih di dropdown txStockItem
// yg SUDAH ADA -- TIDAK ada UI/dropdown baru. Ditarik jadi 1 fungsi supaya
// txStockScanPart()/txStockScanPartGallery() TIDAK duplikasi alur
// draft->resolveDraft->syncPartsStockFromCatalog->populate dropdown,
// bedanya cuma nama adapter & ikon toast sukses (📷 vs 🖼️).
async function txStockScanPartVia(adapterName){
if(typeof SparepartScanner==='undefined'||!SparepartScanner){toast('⚠️ Fitur scan belum tersedia');return;}
const result=await SparepartScanner.scan(adapterName);
if(!result)return;
let item=result.item;
if(result.draft&&item){
const name=await showPromptModal({title:'Nama Part Baru',message:'Kode "'+(item.barcode||item.oemCode||'')+'" belum ada di Katalog Suku Cadang. Isi nama part-nya dulu:',icon:'📦'});
if(!name)return;
const res=await VehicleCatalog.resolveDraft(item.id,{partName:name,category:'Umum'});
if(!res||!res.success){toast('⚠️ '+((res&&res.errors&&res.errors[0])||'Gagal menyimpan part ke katalog'));return;}
item=res.item;
}
if(!item){toast('⚠️ Part tidak ditemukan/gagal dibuat');return;}
const p=syncPartsStockFromCatalog(item);
if(!p){toast('⚠️ Gagal menghubungkan part ke stok');return;}
const chk=document.getElementById('txAddStock');
if(chk){chk.checked=true;toggleTxStockFields();}
populateTxStockSelect();
const sel=document.getElementById('txStockItem');
if(sel){sel.value=p.id;onTxStockItemChange();}
toast((adapterName==='gallery'?'🖼️':'📷')+' Part "'+p.name+'" siap ditambah ke stok');
}
// txStockScanPart() — tombol "📷 Scan Kode Part" (adapter kamera, perilaku
// TIDAK berubah dari sebelumnya, cuma diteruskan ke txStockScanPartVia()).
async function txStockScanPart(){
return txStockScanPartVia('camera');
}
// txStockScanPartGallery() — tombol baru "🖼️ Scan dari Galeri" di
// txStockPanel, pola SAMA PERSIS SparepartScannerUI.scanGallery() (dipakai
// tombol serupa di catalogModal) tapi diarahkan ke alur stok Keuangan lewat
// txStockScanPartVia() di atas, bukan VehicleCatalogUI.openForm().
async function txStockScanPartGallery(){
return txStockScanPartVia('gallery');
}
// syncUnlinkedCatalogPartsToStock() — Tahap 10 (lanjutan Tahap 9): setiap
// kali panel stok dibuka, part yang SUDAH ADA di Vehicle Catalog (dari
// 📦 Katalog Suku Cadang, mis. ditambah manual/scan/import di sana) tapi
// BELUM punya baris D.partsStock terhubung (catalogId) otomatis dibikinkan
// baris stoknya (qty:0, reuse syncPartsStockFromCatalog() 100% apa adanya)
// supaya part itu ikut muncul di dropdown "Pilih Sparepart" form transaksi
// Keuangan -- sebelumnya HANYA part yang sudah ada di D.partsStock (baik
// manual maupun dari alur Keuangan) yang tampil di sana, part yang baru
// ditambah lewat Katalog saja tidak pernah muncul sampai di-scan ulang.
// Sync SATU ARAH (Katalog -> D.partsStock, TIDAK sebaliknya) & tidak
// pernah menimpa qty/harga yang sudah ada (existing branch di
// syncPartsStockFromCatalog cuma sinkronkan nama). VehicleCatalog diakses
// async (IDBStore) jadi fungsi ini juga async -- pemanggil (populateTxStockSelect)
// TIDAK menunggu hasilnya (fire-and-forget), render ulang cuma dipanggil
// kalau memang ada part baru yang berhasil ditautkan, biar tidak flicker
// dropdown pas tidak ada perubahan.
async function syncUnlinkedCatalogPartsToStock(){
if(typeof VehicleCatalog==='undefined'||!VehicleCatalog||typeof VehicleCatalog.ensureLoaded!=='function')return false;
try{
await VehicleCatalog.ensureLoaded();
const store=(typeof VehicleCatalog.getStore==='function')?VehicleCatalog.getStore():null;
const items=(store&&Array.isArray(store.items))?store.items:[];
let added=false;
items.filter(it=>it&&!it.isDraft).forEach(it=>{
const already=D.partsStock.some(p=>p.catalogId===it.id);
if(!already){syncPartsStockFromCatalog(it);added=true;}
});
if(added&&typeof save==='function')save();
return added;
}catch(e){return false;}
}
function populateTxStockSelect(){
const sel=document.getElementById('txStockItem');
if(!sel)return;
const cur=sel.value;
// Bugfix (laporan user, in/out transaksi sparepart harus sesuai kendaraan):
// dulu tampil SEMUA D.partsStock tanpa pandang kendaraan aktif -- reuse
// Sparepart.isPartForVehicle() (sama dipakai Stok Sparepart & dropdown
// servis), di-scope ke curVehicleId (kendaraan aktif Car Notes saat ini).
const vid=typeof curVehicleId!=='undefined'?curVehicleId:null;
const list=D.partsStock.filter(p=>p.id===cur||Sparepart.isPartForVehicle(p,vid));
sel.innerHTML='<option value="__new__">➕ Sparepart Baru</option>'+list.map(p=>`<option value="${p.id}">${escapeHtml(p.name)} (stok ${p.qty}${p.unit?' '+p.unit:''})</option>`).join('');
sel.value=cur&&list.find(p=>p.id===cur)?cur:'__new__';
onTxStockItemChange();
// Best-effort: kalau ada part di Katalog Suku Cadang yang belum tertaut
// ke D.partsStock, tautkan dulu lalu render ulang dropdown supaya
// langsung kelihatan (tidak perlu tunggu scan kode part dulu).
syncUnlinkedCatalogPartsToStock().then(added=>{
if(!added)return;
const sel2=document.getElementById('txStockItem');
if(!sel2)return; // modal sudah ditutup / elemen sudah tidak ada
const cur2=sel2.value;
const list2=D.partsStock.filter(p=>p.id===cur2||Sparepart.isPartForVehicle(p,vid));
sel2.innerHTML='<option value="__new__">➕ Sparepart Baru</option>'+list2.map(p=>`<option value="${p.id}">${escapeHtml(p.name)} (stok ${p.qty}${p.unit?' '+p.unit:''})</option>`).join('');
sel2.value=cur2&&list2.find(p=>p.id===cur2)?cur2:cur2;
onTxStockItemChange();
});
}
function onTxStockItemChange(){
const sel=document.getElementById('txStockItem');
const wrap=document.getElementById('txStockNewWrap');
if(!sel||!wrap)return;
const isNew=sel.value==='__new__';
wrap.style.display=isNew?'block':'none';
if(isNew){
const noteVal=document.getElementById('txNote').value.trim();
const nameEl=document.getElementById('txStockNewName');
if(nameEl&&!nameEl.value) nameEl.value=noteVal;
}
}
function toggleTxStockFields(){
const chk=document.getElementById('txAddStock');
const fields=document.getElementById('txStockFields');
if(!chk||!fields)return;
fields.style.display=chk.checked?'block':'none';
if(chk.checked) populateTxStockSelect();
}
// applyTxStockFromTx(note,txId,date,priceBasis,existingTx) — txId/date/
// priceBasis/existingTx baru di Tahap 8A/8B (opsional, dipanggil dgn 1
// argumen saja masih tetap berfungsi spt sebelumnya). priceBasis = nilai
// Rupiah transaksi yg jadi dasar hitung harga satuan (dibagi qty).
// existingTx (Tahap 8B, pola sama applyTxShopStockFromTx) -> kalau transaksi
// yg diedit sebelumnya sudah pernah nambah stok (existingTx.partStockId),
// rollback dulu qty lama sebelum apply yg baru, supaya edit TIDAK dobel
// nambah stok (single source of truth D.partsStock tetap akurat).
function applyTxStockFromTx(note,txId,date,priceBasis,existingTx){
const chk=document.getElementById('txAddStock');
if(!chk||!chk.checked)return;
const panel=document.getElementById('txStockPanel');
if(!panel||panel.style.display==='none')return;
const itemSel=document.getElementById('txStockItem').value;
const qty=parseFloat(document.getElementById('txStockQty').value)||0;
const unit=document.getElementById('txStockUnit').value.trim()||'pcs';
if(qty<=0){toast('⚠️ Jumlah stok yang ditambah harus lebih dari 0');return;}
if(existingTx&&existingTx.partStockId){
revertStockPurchase(existingTx.partStockId,existingTx.partStockQty);
}
const unitPrice=(priceBasis>0)?(priceBasis/qty):0;
const purchaseDate=date||new Date().toISOString().split('T')[0];
let targetPart=null;
if(itemSel==='__new__'){
const name=(document.getElementById('txStockNewName').value.trim())||note||'Sparepart Baru';
let cat=D.sparepartCats.find(c=>c.name.toLowerCase()===name.toLowerCase());
if(!cat){
cat={id:'sp_'+Date.now(),name,code:codeFromName(name),intervalKm:0};
D.sparepartCats.push(cat);
}
const prefix=cat.code||codeFromName(name);
const seq=D.partsStock.filter(p=>p.code&&p.code.startsWith(prefix+'-')).length+1;
const code=prefix+'-'+String(seq).padStart(3,'0');
const existing=D.partsStock.find(p=>p.catId===cat.id&&p.name.toLowerCase()===name.toLowerCase());
if(existing){
applyStockPurchase(existing,qty,unitPrice,purchaseDate,txId);
targetPart=existing;
} else {
const np={id:'st_'+Date.now(),name,catId:cat.id,code,qty:0,unit,minStock:1,price:0,note:'Otomatis dari transaksi keuangan'};
D.partsStock.push(np);
applyStockPurchase(np,qty,unitPrice,purchaseDate,txId);
targetPart=np;
// Tahap 9: part baru yg diketik manual di Keuangan JUGA otomatis dibuatkan
// entri di Vehicle Catalog (best-effort, tidak menunggu/tidak memblokir
// alur simpan transaksi yg sync) supaya part yg sama bisa dikenali lewat
// scan barcode/OEM di sesi berikutnya. Kegagalan (mis. VehicleCatalog
// belum ada) diabaikan diam-diam -- ini pelengkap, bukan syarat simpan.
if(typeof VehicleCatalog!=='undefined'&&VehicleCatalog&&typeof VehicleCatalog.create==='function'){
VehicleCatalog.create({partName:name,category:cat.name}).then(res=>{
if(res&&res.success&&res.item){np.catalogId=res.item.id;if(typeof save==='function')save();}
}).catch(()=>{});
}
}
toast(`📦 Kategori & stok "${name}" otomatis dibuat (+${qty} ${unit})`);
} else {
const p=D.partsStock.find(x=>x.id===itemSel);
if(p){
applyStockPurchase(p,qty,unitPrice,purchaseDate,txId);
targetPart=p;
toast(`📦 Stok "${escapeHtml(p.name)}" bertambah +${qty} ${unit}`);
}
}
if(targetPart&&txId){
const tx=(existingTx&&existingTx.id===txId)?existingTx:(D.transactions||[]).find(t=>t.id===txId);
if(tx){tx.partStockId=targetPart.id;tx.partStockQty=qty;tx.partStockUnit=unit;}
}
renderStockList();
}

// tx-renov.js — logika panel "🔨 Catat juga ke Proyek Renovasi?" pada txModal
// (Tambah/Edit Transaksi Keuangan). Pola panel kondisional PERSIS SAMA dengan
// tx-stok-sparepart.js (lihat file itu utk pola aslinya "Tambah ke Stok
// Sparepart juga?") -- panel ini otomatis muncul kalau kategori transaksi
// mengandung "Renov" (lihat isRenovCatName() & updateTxVehiclePanels() di
// transaksi.js), berlaku sama persis utk input manual maupun hasil Scan Struk
// (keduanya lewat updateTxVehiclePanels()).
//
// Beda dgn panel stok (yg selalu ikut mencatat transaksi Keuangan-nya), panel
// ini punya toggle status yg menentukan APAKAH transaksi Keuangan ikut
// dicatat atau tidak:
//  - ✅ Sudah Dibeli (default): item renovasi baru dibuat & LANGSUNG ditandai
//    lunas, otomatis ter-link ke transaksi Keuangan yang barusan disimpan --
//    pola sama persis seperti fitur "🔗 Hubungkan Transaksi Lama" yang sudah
//    ada di Renov.confirmLinkTx (lihat modules/home/renovasi.js), cuma di sini
//    terjadi OTOMATIS (tanpa perlu buka linkTxModal manual). Lihat
//    applyTxRenovFromTx() di bawah, dipanggil dari _saveTxInner (transaksi.js)
//    persis di titik yang sama dengan applyTxStockFromTx dkk, SETELAH
//    transaksi Keuangan tersimpan.
//  - 🛒 Belum Dibeli: item masuk daftar belanja proyek sbg BELUM lunas
//    (estimasi harga = nominal yang diisi di form Jumlah), TAPI transaksi
//    Keuangan-nya SENGAJA TIDAK ikut dicatat (barangnya belum benar-benar
//    dibeli, cuma baru didata rincian belanjanya). Lihat
//    handleTxRenovBelumDibeli() di bawah, dipanggil di AWAL _saveTxInner
//    (transaksi.js) -- kalau return true, _saveTxInner early-return persis
//    pola cabang cicilan/langganan yg juga early-return, supaya SISA proses
//    (bikin transaksi Keuangan) tidak ikut jalan.
//
// Catatan modal Renov (modules/home/renovasi.js, Renov.renderDetail): modal
// detail proyek SUDAH punya pemisahan otomatis "🛒 Perlu Dibeli" vs "✅ Sudah
// Dibeli" berdasarkan field `it.paid` tiap item (lihat renovItemList) -- jadi
// item yang dibuat dari panel ini otomatis nongol di seksi yang sesuai tanpa
// perlu tab/UI baru sama sekali, cukup set `paid:true`/`paid:false` seperti
// biasa.
let _txRenovStatus='sudah';
function populateTxRenovSelect(){
const sel=document.getElementById('txRenovProject');
if(!sel)return;
const cur=sel.value;
if(!D.renovProjects||!D.renovProjects.length){
sel.innerHTML='<option value="">— Belum ada proyek, buat dulu di 🔨 Proyek Renovasi —</option>';
sel.disabled=true;
return;
}
sel.disabled=false;
sel.innerHTML=D.renovProjects.map(p=>`<option value="${p.id}">${escapeHtml(p.name)}</option>`).join('');
if(cur&&D.renovProjects.find(p=>p.id===cur))sel.value=cur;
}
function setTxRenovStatus(status){
_txRenovStatus=(status==='belum')?'belum':'sudah';
const btnSudah=document.getElementById('txRenovStatusSudah');
const btnBelum=document.getElementById('txRenovStatusBelum');
if(btnSudah)btnSudah.classList.toggle('active',_txRenovStatus==='sudah');
if(btnBelum)btnBelum.classList.toggle('active',_txRenovStatus==='belum');
const hint=document.getElementById('txRenovStatusHint');
if(hint)hint.textContent=_txRenovStatus==='sudah'
?'💡 Item baru langsung ditandai lunas & otomatis ter-link ke transaksi Keuangan ini.'
:'💡 Item masuk daftar belanja proyek sbg belum lunas (estimasi = nominal Jumlah di atas). Transaksi Keuangan ini TIDAK ikut dicatat, karena barangnya belum benar-benar dibeli.';
}
function toggleTxRenovFields(){
const chk=document.getElementById('txAddRenov');
const fields=document.getElementById('txRenovFields');
if(!chk||!fields)return;
fields.style.display=chk.checked?'block':'none';
if(chk.checked){
populateTxRenovSelect();
setTxRenovStatus(_txRenovStatus);
}
}
// applyTxRenovFromTx(note,txId,date,amt,cat,accId) -- dipanggil SETELAH
// transaksi Keuangan tersimpan (persis titik yg sama dgn applyTxStockFromTx
// dkk di _saveTxInner), khusus utk status "✅ Sudah Dibeli". Kalau status
// "🛒 Belum Dibeli", sudah ditangani lebih awal oleh
// handleTxRenovBelumDibeli() (yg early-return sblm transaksi dibuat sama
// sekali) -- jadi di sini cukup early-return supaya tidak dobel proses.
function applyTxRenovFromTx(note,txId,date,amt,cat,accId){
const chk=document.getElementById('txAddRenov');
if(!chk||!chk.checked)return;
const panel=document.getElementById('txRenovPanel');
if(!panel||panel.style.display==='none')return;
if(_txRenovStatus==='belum')return;
const projId=document.getElementById('txRenovProject').value;
const p=projId?D.renovProjects.find(x=>x.id===projId):null;
if(!p){toast('⚠️ Pilih dulu Proyek Renovasi-nya (item tidak dicatat ke Renovasi, transaksi Keuangan tetap tersimpan)');return;}
const itemName=(note||cat||'Item Renovasi').trim()||'Item Renovasi';
const it={id:uid(),name:itemName,ukuran:'',harga:amt,hargaTotal:null,category:cat,accountId:accId,note:'',tglBayar:date,calcDetail:null,paid:true,txId:txId,paidDate:date};
p.items.push(it);
const t=D.transactions.find(x=>x.id===txId);
if(t){t.renovProjectLinkId=p.id;t.renovItemLinkId=it.id;}
save();
if(typeof Renov!=='undefined'){
Renov.render();
if(sameId(Renov.curId,p.id))Renov.renderDetail();
}
toast(`🔨 Item "${escapeHtml(itemName)}" otomatis dicatat & lunas di proyek "${escapeHtml(p.name)}"`);
}
// handleTxRenovBelumDibeli(note,cat) -- dipanggil di AWAL _saveTxInner
// (transaksi.js), SEBELUM transaksi Keuangan dibuat, khusus utk transaksi
// BARU (bukan edit) dgn status "🛒 Belum Dibeli". Return true kalau berhasil
// ditangani di sini (utk sinyal ke _saveTxInner supaya early-return & TIDAK
// lanjut mencatat transaksi Keuangan, sesuai desain: barangnya belum
// benar-benar dibeli, jadi bukan pengeluaran nyata). Return false kalau panel
// tidak aktif/status bukan "belum" -- _saveTxInner lanjut proses normal.
function handleTxRenovBelumDibeli(note,cat){
const chk=document.getElementById('txAddRenov');
const panel=document.getElementById('txRenovPanel');
if(!chk||!chk.checked||!panel||panel.style.display==='none')return false;
if(_txRenovStatus!=='belum')return false;
const projId=document.getElementById('txRenovProject').value;
const p=projId?D.renovProjects.find(x=>x.id===projId):null;
if(!p){toast('⚠️ Pilih dulu Proyek Renovasi-nya');return false;}
evalAmtExpr('txAmt');
const amt=parseFloat(document.getElementById('txAmt').value)||0;
if(amt<=0){toast('⚠️ Masukkan jumlah valid');return false;}
const date=document.getElementById('txDate').value||todayStr();
const accId=document.getElementById('txAcc').value;
const itemName=(note||cat||'Item Renovasi').trim()||'Item Renovasi';
const it={id:uid(),name:itemName,ukuran:'',harga:amt,hargaTotal:null,category:cat,accountId:accId,note:'',tglBayar:date,calcDetail:null,paid:false,txId:null,paidDate:null};
p.items.push(it);
save();closeModal('txModal');renderDashboard();
if(typeof Renov!=='undefined'){
Renov.render();
if(sameId(Renov.curId,p.id))Renov.renderDetail();
}
toast(`🛒 Item "${escapeHtml(itemName)}" masuk daftar belanja proyek "${escapeHtml(p.name)}" (belum lunas) — transaksi Keuangan TIDAK dicatat`);
return true;
}

// tx-transfer.js — logika modal "⇄ Transfer Antar Akun" (transferModal).
// Dipindah ke modules/finance/tx-transfer.js (Sesi 16 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// Dipisah dari transaksi.js (2026-07-11, lihat CLAUDE.md catatan kerja
// "split transaksi.js" bagian ke-8) murni sebagai pengelompokan ulang
// file, BUKAN perubahan perilaku. Kedua fungsi di sini tetap global
// karena dipanggil dari:
//  - HTML lewat atribut data-action di modals.js (openTransferModal
//    dipanggil dari tombol "Transfer" di halaman Keuangan, saveTransfer
//    dari tombol "Simpan Transfer" di transferModal)
// Tidak ada modul lain yang meng-assume fungsi ini ada persis di
// transaksi.js — akses selalu lewat nama fungsi global.
function openTransferModal(){
populateAccFilters();
document.getElementById('trAmt').value='';
document.getElementById('trNote').value='';
document.getElementById('trDate').value=new Date().toISOString().split('T')[0];
if(D.accounts.length>1) document.getElementById('trTo').selectedIndex=1;
openModal('transferModal');
}
function saveTransfer(){
const from=document.getElementById('trFrom').value;
const to=document.getElementById('trTo').value;
evalAmtExpr('trAmt');
const amt=parseFloat(document.getElementById('trAmt').value);
if(!amt||amt<=0){toast('⚠️ Masukkan jumlah valid');return;}
if(from===to){toast('⚠️ Akun asal dan tujuan harus berbeda');return;}
const date=document.getElementById('trDate').value;
const note=document.getElementById('trNote').value||'Transfer';
const fromAcc=D.accounts.find(a=>a.id===from), toAcc=D.accounts.find(a=>a.id===to);
D.transactions.push({id:uid(),type:'transfer_out',amount:amt,category:'Transfer',note:`${note} → ${escapeHtml(toAcc.name)}`,date,accountId:from});
D.transactions.push({id:uid(),type:'transfer_in',amount:amt,category:'Transfer',note:`${note} ← ${escapeHtml(fromAcc.name)}`,date,accountId:to});
save();closeModal('transferModal');renderDashboard();renderKeuangan();toast('✅ Transfer berhasil');
}

// tx-cobek.js — domain "Stok/Penjualan Shop (Shop)" pada form Transaksi.
// Dipindah ke modules/finance/tx-cobek.js (Sesi 16 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// Dipindah dari transaksi.js (lihat CLAUDE.md catatan kerja "split transaksi.js"
// bagian ke-9) -- tetap fungsi global, tetap dipanggil persis sama dari sini
// (updateTxVehiclePanels di transaksi.js), dari HTML (modals.js), maupun dari
// tempat lain yang butuh deteksi kategori Shop/Shop.
//
// Catatan: fungsi-fungsi panel form-nya sendiri (populateTxShopStockSelect,
// onTxShopStockItemChange, toggleTxShopStockFields, resetShopStockCart,
// applyTxShopStockFromTx, populateTxShopSaleSelect, onTxShopSaleItemChange,
// toggleTxShopSaleFields, resetTxShopSaleCart, applyTxShopSaleFromTx, dst)
// SUDAH ada di cobek.js sejak awal (bukan hasil split sesi ini) -- transaksi.js
// hanya memanggilnya. isShopStockCatName() adalah satu-satunya bagian domain
// Shop yang tersisa murni di source transaksi.js (dipakai buat mendeteksi
// kapan panel Stok/Penjualan Shop harus muncul di updateTxVehiclePanels()).
function isShopStockCatName(catName,subName){
if(/cobek|shop/i.test(catName||'')||/cobek|shop/i.test(subName||''))return true;
// Fallback robust terhadap rename kategori/subkategori: cocokkan lewat ID internal
// yang tetap 'sub_cb_cobek'/'sub_cbb_cobek' walau nama tampilannya sudah diubah user
// (mis. dari "Shop" jadi "Shop") -- ini yang bikin panel Stok/Penjualan Shop hilang
// kalau hanya mengandalkan cocokkan teks nama saja.
const allCats=[...(D.categories.income||[]),...(D.categories.expense||[])];
const cat=allCats.find(c=>c.name===catName);
if(cat){
const sub=(cat.subs||[]).find(s=>s.name===subName);
if(sub&&(sub.id==='sub_cb_cobek'||sub.id==='sub_cbb_cobek'))return true;
}
return false;
}

// tx-target.js — domain "Target Tabungan" (modal tambah target, deteksi Dana
// Dipindah ke modules/finance/tx-target.js (Sesi 16 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// Darurat, simpan, lihat transaksi akun terkait, tambah/hapus progres).
// Dipindah dari transaksi.js (lihat CLAUDE.md catatan kerja "split
// transaksi.js" bagian ke-9). Semua tetap fungsi global verbatim (tidak ada
// perubahan logika), dipanggil sama persis dari HTML (modals.js,
// data-action="openTargetModal"/"onTargetDanaDaruratToggle"/"saveTarget"/dst,
// dan modules-render.js untuk showTargetAccountTx/addTarget/delTarget),
// maupun dari file lintas-bundle lain (modules-calc.js & aset.js memanggil
// openTargetModal/onTargetDanaDaruratToggle utk jalan pintas "+ Buat
// targetnya sekarang" dari banner Dana Darurat).
function openTargetModal(){
['tName','tAmt','tSaved'].forEach(id=>document.getElementById(id).value='');
document.getElementById('tEmoji').value='🎯';
document.getElementById('tDanaDarurat').checked=false;
document.getElementById('tDanaDaruratHint').style.display='none';
populateAccFilters();
document.getElementById('tAcc').value='';
document.getElementById('tSavedWrap').style.display='block';
openModal('targetModal');
}
function onTargetAccChange(){
const linked=!!document.getElementById('tAcc').value;
document.getElementById('tSavedWrap').style.display=linked?'none':'block';
}
function onTargetDanaDaruratToggle(){
const chk=document.getElementById('tDanaDarurat');
const hint=document.getElementById('tDanaDaruratHint');
if(!chk.checked){hint.style.display='none';return;}
const avgBulanan=(typeof FI!=='undefined')?FI.annualExpense()/12:0;
const rekom=Math.round((avgBulanan||0)*6);
if(!document.getElementById('tName').value.trim())document.getElementById('tName').value='Dana Darurat';
const emojiEl=document.getElementById('tEmoji');
if(!emojiEl.value.trim()||emojiEl.value==='🎯')emojiEl.value='🚨';
if(!document.getElementById('tAmt').value&&rekom>0)document.getElementById('tAmt').value=rekom;
const already=(D.targets||[]).find(t=>t.isDanaDarurat);
let html=avgBulanan>0
?`💡 Rekomendasi umum: <b>6× rata-rata pengeluaran bulanan</b> (≈${fmtFull(avgBulanan)}) = <b>${fmtFull(rekom)}</b>. Sudah diisi otomatis di kolom Target — sesuaikan lagi kalau perlu (kalau pemasukan gak tetap, biasanya lebih aman ke arah 9–12×).`
:`💡 Rekomendasi umum dana darurat: 3–6× pengeluaran bulanan (lebih aman 6–12× kalau pemasukan gak tetap). Belum cukup data transaksi utk hitung otomatis, isi manual dulu ya.`;
if(already)html+=`<br>⚠️ Target "<b>${escapeHtml(already.name)}</b>" saat ini juga ditandai Dana Darurat — kalau disimpan, tandanya pindah ke target ini.`;
hint.innerHTML=html;
hint.style.display='block';
}
function saveTarget(){
const name=document.getElementById('tName').value;
const amt=parseFloat(document.getElementById('tAmt').value);
if(!name||!amt){toast('⚠️ Isi nama dan target');return;}
const accId=document.getElementById('tAcc').value||null;
const saved=accId?0:(parseFloat(document.getElementById('tSaved').value)||0);
const isDanaDarurat=document.getElementById('tDanaDarurat').checked;
if(isDanaDarurat)D.targets.forEach(t=>{t.isDanaDarurat=false;});
D.targets.push({id:uid(),name,amount:amt,saved,accountId:accId,emoji:document.getElementById('tEmoji').value||'🎯',isDanaDarurat});
save();closeModal('targetModal');renderSettings();
if(typeof AlokasiAset!=='undefined')AlokasiAset.renderAll();
toast(accId?'✅ Target tersimpan, tersambung ke akun (otomatis update)':'✅ Target tersimpan');
}
function showTargetAccountTx(targetId){
const t=D.targets.find(x=>sameId(x.id,targetId));if(!t||!t.accountId)return;
const acc=D.accounts.find(a=>a.id===t.accountId);if(!acc)return;
const txs=D.transactions.filter(x=>x.accountId===acc.id).sort((a,b)=>new Date(b.date)-new Date(a.date));
const bal=recalcAccBalance(acc.id);
document.getElementById('filterTxTitle').textContent=`${t.emoji} ${t.name} (${acc.emoji} ${acc.name})`;
document.getElementById('filterTxSummary').textContent=`${txs.length} transaksi · Saldo saat ini ${fmtFull(bal)} dari target ${fmtFull(t.amount)}`;
document.getElementById('filterTxList').innerHTML=txs.length?txs.slice(0,100).map(txHTML).join(''):'<div class="empty"><div class="empty-icon">💸</div><div class="empty-text">Belum ada transaksi di akun ini</div></div>';
openModal('filterTxModal');
}
async function addTarget(i){const addStr=await showPromptModal({title:'Tambah Tabungan',message:'Tambah berapa? (Rp)',icon:'🎯',inputType:'number'});if(addStr===null)return;const add=parseFloat(addStr);if(!add||isNaN(add))return;D.targets[i].saved+=add;save();renderSettings();toast('✅ Target diperbarui');}
async function delTarget(i){if(!await askConfirm('Hapus target?'))return;D.targets.splice(i,1);save();renderSettings();toast('🗑 Target dihapus');}

// tx-list-cashflow.js — domain "List Transaksi (kartu tx, hapus tx), filter
// Dipindah ke modules/finance/tx-list-cashflow.js (Sesi 16 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// periode Keuangan/Laporan, & Cashflow Forecast".
// Dipindah dari transaksi.js (lihat CLAUDE.md catatan kerja "split
// transaksi.js" bagian ke-11 -- lanjutan bagian ke-5/6/7/8/9). Semua tetap
// fungsi global verbatim (tidak ada perubahan logika sama sekali), dipanggil
// sama persis dari HTML (app_production.html/index.html: onclick
// changeMonth/setTxListPeriode/setPeriode/setKeuanganTab), dari
// modules-render.js (renderKeuangan/renderLaporan/renderCashflowForecast
// masing2 makai getTxListRange/getRange/computeCashflowForecast), dari
// backup-restore.js & cobek.js (getRange/txHTML/computeCashflowForecast utk
// ekspor & kartu shop), dan features-sheets-pwa-selftest.js (self-test
// makai setKeuanganTab).
//
// Variabel state `txListPeriode` (filter periode List Transaksi di tab
// Kelola) ikut dipindah ke sini karena cuma dipakai bareng
// setTxListPeriode/getTxListRange di bawah -- beda dari `filterPeriode`
// (filter Laporan) yang sudah dideklarasikan bareng variabel global lain di
// features-helpers-global-security.js sejak awal, jadi TIDAK ikut dipindah.
// `curMonth`/`curYear`/`txListPage` juga TIDAK dipindah -- sudah dipakai
// modul lain (features-helpers-global-security.js, filter-laporan.js)
// sebelum sesi ini, dibiarkan di tempat asalnya.
function txHTML(t){
const cats=getAllCats();
let icon='💰', bg='var(--accent-soft)';
if(t.type==='transfer_out'||t.type==='transfer_in'){icon='⇄';bg='var(--accent-soft)';}
else { const cat=cats.find(c=>c.name===t.category); if(cat){icon=cat.emoji;} bg=t.type==='income'?'var(--accent3-soft)':'var(--accent2-soft)'; }
const sign=(t.type==='income'||t.type==='transfer_in')?'+':'-';
const cls=(t.type==='income'||t.type==='transfer_in')?'green':'red';
const acc=D.accounts.find(a=>a.id===t.accountId);
const subText=t.subcategory?(' · '+t.subcategory):'';
const pmIcons={cicilan:'💳',langganan:'🔁',utang:'📕',tunai:''};
const pmBadge=(t.payMethod&&t.payMethod!=='tunai')?` <span class="acc-chip">${pmIcons[t.payMethod]||''} ${t.payMethod}</span>`:'';
return`<div class="tx-item u-pointer" data-action="editTx" data-args="${escapeHtml(JSON.stringify([t.id]))}">
    <div class="tx-icon" style="background:${bg}">${icon}</div>
    <div class="tx-info"><div class="tx-name">${escapeHtml(t.category)}${escapeHtml(subText)}</div><div class="tx-meta">${t.date}${t.note?' · '+escapeHtml(t.note):''}${acc?` <span class="acc-chip">${acc.emoji} ${escapeHtml(acc.name)}</span>`:''}${pmBadge}</div></div>
    <div class="u-flex u-aic u-gap6">
      <div class="tx-amount ${cls}">${sign}${fmt(t.amount)}</div>
      <button class="tx-del" data-stop="1" data-action="delTx" data-args="${escapeHtml(JSON.stringify([t.id]))}" aria-label="Hapus">🗑</button>
    </div>
  </div>`;
}
async function delTx(id){
// Pesan konfirmasi khusus (sesi 292, lanjutan fix s291) -- kalau transaksi ini
// pembayaran cicilan/tagihan/utang (billLinkId), user perlu tahu SEBELUM hapus
// bahwa ada efek balik ke jadwal tagihan, bukan cuma toast SETELAH terhapus.
// Teks disamakan persis dgn deleteBillHistoryTx() (tagihan-kalender.js) supaya
// konsisten -- 1 SSOT redaksi utk "hapus pembayaran bill", cuma beda pintu masuk.
const _t=D.transactions.find(x=>x.id===id);
const confirmMsg=_t&&_t.billLinkId?'Hapus transaksi ini? Kalau ini pembayaran TERAKHIR, sisa tenor/jatuh tempo tagihan (atau saldo utang) akan dikembalikan.':'Hapus transaksi ini?';
if(!await askConfirm(confirmMsg))return;
const t=D.transactions.find(x=>x.id===id);
if(t&&t.bbmLinkId&&D.bbmLogs)D.bbmLogs=D.bbmLogs.filter(b=>b.id!==t.bbmLinkId);
if(t&&t.partStockId&&typeof revertStockPurchase==='function'){
revertStockPurchase(t.partStockId,t.partStockQty);
toast(`📦 Stok sparepart dikurangi (transaksi dihapus)`,2600);
renderStockList();
}
if(t&&t.stockItems&&t.stockItems.length){
t.stockItems.forEach(si=>{
const p=D.products.find(x=>x.id===si.productId);
if(p)p.stock=Math.max(0,(p.stock||0)-(si.qty||0));
});
toast(`📦 Stok dikurangi (transaksi dihapus)`,2600);
} else if(t&&t.stockProductId){
const p=D.products.find(x=>x.id===t.stockProductId);
if(p){p.stock=Math.max(0,(p.stock||0)-(t.stockQty||0));toast(`📦 Stok "${p.name}" dikurangi ${t.stockQty} (transaksi dihapus)`,2600);}
}
if(t&&t.cobekLinkId){
const linkedShop=D.cobek.find(c=>c.id===t.cobekLinkId);
if(linkedShop&&linkedShop.items){
linkedShop.items.forEach(it=>{const p=D.products.find(x=>x.id===it.productId);if(p)p.stock=(p.stock||0)+it.qty;});
toast(`🪨 Stok dikembalikan, penjualan Shop terkait dihapus`,2600);
}
D.cobek=D.cobek.filter(c=>c.id!==t.cobekLinkId);
renderShop();renderShopRecent();
}
if(t&&t.servisLinkId&&D.servisLogs){
const linkedServis=D.servisLogs.find(s=>s.id===t.servisLinkId);
if(linkedServis){
if(linkedServis.usedPartId)revertStockUsage(linkedServis.usedPartId,linkedServis.usedPartQty);
toast(`🔧 Catatan servis terkait ikut dihapus`,2600);
}
D.servisLogs=D.servisLogs.filter(s=>s.id!==t.servisLinkId);
renderStockList();
}
if(t&&t.renovItemLinkId&&typeof Renov!=='undefined'){
Renov.onLinkedTxDeleted(t);
}
if(t&&t.wishlistLinkId){
WorthIt.onLinkedTxDeleted(t);
}
if(t&&t.sewaKiosLinkId&&typeof SewaKios!=='undefined'){
SewaKios.onLinkedTxDeleted(t);
}
if(t&&t.tukangPaymentEntryIds&&t.tukangPaymentEntryIds.length){
Tukang.unmarkPaidEntries(t.tukangPaymentEntryIds);
}
// BUGFIX (audit sesi 291, "sync 2 arah Cicilan/Tagihan vs Transaksi") -- sebelumnya
// hapus transaksi pembayaran cicilan/tagihan/utang lewat tombol 🗑 di List Transaksi
// (delTx, fungsi ini) TIDAK menyentuh D.bills/D.billsArchive/D.debts/D.piutang sama
// sekali (beda dgn hapus lewat modal 📋 Riwayat Pembayaran -- lihat deleteBillHistoryTx
// di tagihan-kalender.js yg sudah benar). Akibatnya sisaTenor/jatuh tempo jadi basi,
// tagihan yg sudah lunas & masuk arsip tidak diaktifkan lagi, saldo utang tidak
// dikembalikan, dan piutang auto "Ditanggung Bersama" jadi orphan. Reuse
// revertBillFromDeletedTx() (SSOT, sama persis dipakai deleteBillHistoryTx) -- no-op
// kalau t tidak punya billLinkId.
let billRevertMsg='';
let billLinked=false;
if(t&&t.billLinkId&&typeof revertBillFromDeletedTx==='function'){
billLinked=true;
const{linkedBill,isLatest,restoredFromArchive,removedPiutang}=revertBillFromDeletedTx(t);
if(restoredFromArchive)billRevertMsg=', tagihan diaktifkan lagi (belum lunas)';
else if(linkedBill&&isLatest&&linkedBill.kind==='cicilan')billRevertMsg=', sisa tenor dikembalikan';
else if(linkedBill&&isLatest&&linkedBill.kind==='utang')billRevertMsg=', saldo utang dikembalikan';
else if(linkedBill&&isLatest&&(linkedBill.kind==='langganan'||linkedBill.kind==='tagihan')&&linkedBill.freq)billRevertMsg=', jatuh tempo dikembalikan';
if(removedPiutang)billRevertMsg+=' (piutang otomatis terkait ikut dihapus)';
}
// BUGFIX (audit sesi 2 tagihan-kalender-sync / S335, BUG-019): render manual di bawah
// ini (khususnya renderBillHistory()) HARUS jalan SETELAH D.transactions difilter &
// save() -- sebelumnya dipanggil SEBELUM filter, jadi kalau modal Riwayat Pembayaran
// sedang terbuka untuk bill yang sama, renderBillHistory() membaca D.transactions yang
// MASIH mengandung transaksi yang baru saja "dihapus" (baris pembayaran basi tampil
// sampai ada trigger render lain).
D.transactions=D.transactions.filter(t=>t.id!==id);
save();renderDashboard();renderKeuangan();renderCnTab();renderProductList();
if(billLinked){
renderBillList();renderSettings();checkBills();renderBillHistory();renderBillArchive();renderDebtList();renderKekayaanBersih();hitungZakatMaal();
if(typeof Piutang!=='undefined')Piutang.renderList();
}
if(!t||(!t.stockProductId&&!t.cobekLinkId&&!t.servisLinkId&&!t.partStockId&&!(t.stockItems&&t.stockItems.length)))toast('🗑 Dihapus'+(t&&t.renovItemLinkId?' (status lunas di Proyek Renovasi dibatalkan)':(t&&t.wishlistLinkId?' (barang dikembalikan ke Prioritas Belanja)':(t&&t.tukangPaymentEntryIds&&t.tukangPaymentEntryIds.length?' (absensi tukang terkait dibuka kembali)':billRevertMsg))));
}
