// ---------------------------------------------------------------------------
// Smart Delivery Engine, Sesi 5/6: predictService() & maintenanceForecast()
// — fungsi prediktif domain VEHICLE (bagian servis/sparepart). Lihat
// RENCANA-SESI-RINGKAS.md untuk peta 6 sesi. fuelEfficiency() (fungsi
// prediktif VEHICLE lainnya, bagian BBM) ada di modules/vehicle/vehicle-
// core.js, di-load SEBELUM file ini.
//
// predictService() SENGAJA tidak menduplikasi perhitungan yang sudah ada di
// Servis.renderReminder() (car-notes.js) — dia memakai getEffectiveIntervalKm/
// getLastServiceKmForCat/estimateKmPerDay/estimateServiceDateISO yang PERSIS
// SAMA (fungsi yang sama, bukan reimplementasi), cuma dikeluarkan versi
// pure-data-nya (tanpa HTML/DOM) supaya bisa dipakai AIService/wiring Sesi 6
// nanti. renderReminder() DIBIARKAN seperti semula (tidak di-refactor pakai
// fungsi ini) untuk minimalkan risiko regresi UI di sesi ini.
// PURE/read-only, TIDAK PERNAH memanggil save(). Belum ada UI/tombol baru.
// ---------------------------------------------------------------------------

// predictService({vehicleId, categoryId}) — prediksi servis berikutnya.
// Tanpa categoryId: balikin array (1 baris per D.sparepartCats), urut dari
// paling mendesak (sisaKm terkecil dulu) — sama urutan dgn
// Servis.renderReminder(). Dengan categoryId: balikin 1 objek prediksi
// (bukan array) buat kategori itu saja. Balikin {ok:false} kalau kendaraan
// tidak ditemukan atau belum ada kategori sparepart terdaftar.
function predictService({vehicleId,categoryId}={}){
const veh=(D.vehicles||[]).find(v=>v.id===vehicleId);
if(!veh)return{ok:false,reason:'Kendaraan tidak ditemukan'};
const cats=categoryId
? (D.sparepartCats||[]).filter((c)=>c.id===categoryId)
: (D.sparepartCats||[]);
if(!cats.length)return{ok:false,reason:categoryId?'Kategori sparepart tidak ditemukan':'Belum ada kategori sparepart terdaftar'};
const curKm=getVehicleKm(vehicleId);
const kmPerDay=estimateKmPerDay(vehicleId);
const rows=cats.map((cat)=>{
const lastKm=getLastServiceKmForCat(vehicleId,cat);
const intervalKm=getEffectiveIntervalKm(vehicleId,cat);
const overridden=hasIntervalOverride(vehicleId,cat);
const jarakTempuh=lastKm===null?curKm:curKm-lastKm;
const sisaKm=intervalKm-jarakTempuh;
const estDateISO=estimateServiceDateISO(sisaKm,kmPerDay);
const status=sisaKm<=0?'lewat':(sisaKm<=intervalKm*0.15?'segera':'aman');
return{categoryId:cat.id,categoryName:cat.name,lastKm,intervalKm,overridden,sisaKm,estDateISO,status};
}).sort((a,b)=>a.sisaKm-b.sisaKm);
return{ok:true,vehicleId,curKm,kmPerDay,items:categoryId?undefined:rows,...(categoryId?rows[0]:{})};
}

// maintenanceForecast({vehicleId, monthsAhead}) — perkiraan item servis yang
// akan JATUH TEMPO dalam N bulan ke depan (dari estDateISO hasil
// predictService() di atas) + estimasi total biayanya, dari rata-rata biaya
// histori per kategori (D.servisLogs[].cost, kalau ada catatannya — kategori
// tanpa histori biaya dihitung biayaEstimasi:null & TIDAK ikut totalBiaya,
// supaya total tidak under-estimate secara diam-diam).
function maintenanceForecast({vehicleId,monthsAhead=3}={}){
const pred=predictService({vehicleId});
if(!pred.ok)return pred;
const now=new Date();
const batas=new Date(now.getFullYear(),now.getMonth()+monthsAhead,now.getDate());
const dueItems=pred.items.filter((r)=>r.status==='lewat'||(r.estDateISO&&new Date(r.estDateISO)<=batas));
let totalBiaya=0;
let totalBiayaLengkap=true;
const items=dueItems.map((r)=>{
const logs=(D.servisLogs||[]).filter((s)=>s.vehicleId===vehicleId&&(s.categoryId===r.categoryId||(!s.categoryId&&s.item===r.categoryName))&&s.cost>0);
const biayaEstimasi=logs.length?logs.reduce((s,l)=>s+l.cost,0)/logs.length:null;
if(biayaEstimasi==null)totalBiayaLengkap=false;else totalBiaya+=biayaEstimasi;
return Object.assign({},r,{biayaEstimasi});
});
return{ok:true,vehicleId,monthsAhead,items,totalBiaya,totalBiayaLengkap};
}

// ---------------------------------------------------------------------------
// Smart Delivery Engine, Sesi 8: rule domain VEHICLE utk AIDecision (lanjutan
// Sesi 7 — lihat RENCANA-SESI-RINGKAS.md). Rule: "ada kendaraan dgn item
// servis berstatus 'lewat' (jatuh tempo terlampaui)" — dari predictService()
// di atas, status yang SAMA PERSIS dipakai Servis.renderReminder() (jadi
// rule ini TIDAK mengarang ambang baru, cuma numpang status yang sudah ada).
// Diperiksa lintas SEMUA D.vehicles (bukan cuma kendaraan aktif) karena
// event 'vehicle.updated' (saveServis()) tidak membawa vehicleId spesifik.
// ---------------------------------------------------------------------------

// _vehicleOverdueCheck() — helper dipakai condition() & action().
function _vehicleOverdueCheck(){
if(typeof predictService!=='function')return{trigger:false};
const overdue=[];
(D.vehicles||[]).forEach((v)=>{
const pred=predictService({vehicleId:v.id});
if(pred&&pred.ok&&Array.isArray(pred.items)){
pred.items.filter((it)=>it.status==='lewat').forEach((it)=>overdue.push({vehicleName:v.name,categoryName:it.categoryName,sisaKm:it.sisaKm}));
}
});
return{trigger:overdue.length>0,overdue};
}

// ---------------------------------------------------------------------------
// Rule kedua VEHICLE (keputusan produk dikonfirmasi user):
// 'vehicle-fuel-efficiency-drop' — konsumsi BBM (km/liter) pengisian FULL
// TANK terakhir turun ≥20% dari rata-rata histori sebelumnya. SENGAJA tidak
// menduplikasi/mengubah fuelEfficiency()/estimateRpPerKm() di atas (yang
// menghitung km/liter GABUNGAN semua histori, bukan per-segmen) —
// _vehicleFuelEfficiencyDropCheck() menghitung km/liter PER PASANGAN log full
// tank berurutan sendiri, lalu membandingkan segmen TERAKHIR vs rata-rata
// segmen SEBELUMNYA. Ambang drop (default 20%) BISA DIATUR user (Sesi
// lanjutan, pola sama dgn getAIFinanceOverspendThreshold/getAIDeliveryThin-
// MarginThreshold) lewat D.profile.aiVehicleFuelDropThresholdPct, field baru
// di Pengaturan > 🤖 AI Asisten. Minimal 3 segmen historis TETAP DIHARDCODE
// (bukan ambang sensitivitas, tapi syarat data cukup secara statistik).
// ---------------------------------------------------------------------------
const AI_VEHICLE_FUEL_DROP_DEFAULT_PCT=20;

// getAIVehicleFuelDropThreshold()/setAIVehicleFuelDropThreshold(pct) —
// getter/setter D.profile.aiVehicleFuelDropThresholdPct, dipakai field
// Pengaturan (renderSettings()/autoSaveProfile()) & rule di bawah. Dijaga
// di rentang 5-90 (di bawah 5% terlalu sensitif/noise wajar, di atas 90%
// nyaris tidak pernah trigger).
function getAIVehicleFuelDropThreshold(){
const v=D.profile&&D.profile.aiVehicleFuelDropThresholdPct;
return(typeof v==='number'&&v>=5&&v<=90)?v:AI_VEHICLE_FUEL_DROP_DEFAULT_PCT;
}
function setAIVehicleFuelDropThreshold(pct){
const n=parseFloat(pct);
D.profile.aiVehicleFuelDropThresholdPct=(Number.isFinite(n)&&n>=5&&n<=90)?n:AI_VEHICLE_FUEL_DROP_DEFAULT_PCT;
return D.profile.aiVehicleFuelDropThresholdPct;
}

function _vehicleFuelEfficiencyDropCheck(){
const thresholdPct=getAIVehicleFuelDropThreshold();
const drops=[];
(D.vehicles||[]).forEach((v)=>{
const logs=(D.bbmLogs||[]).filter((b)=>b.vehicleId===v.id&&b.fullTank&&isFinite(b.km)&&b.km>0&&b.liter>0).sort((a,b)=>a.km-b.km);
if(logs.length<4)return; // butuh min. 3 segmen historis + 1 segmen terakhir yg dibandingkan
const segments=[];
for(let i=1;i<logs.length;i++){
const kmDiff=logs[i].km-logs[i-1].km;
if(kmDiff<=0)continue;
segments.push(kmDiff/logs[i].liter);
}
if(segments.length<4)return;
const last=segments[segments.length-1];
const prevSegs=segments.slice(0,-1);
const avgPrev=prevSegs.reduce((s,x)=>s+x,0)/prevSegs.length;
if(avgPrev<=0)return;
const dropPct=Math.round((1-last/avgPrev)*100);
if(dropPct>=thresholdPct)drops.push({vehicleId:v.id,vehicleName:v.name,dropPct,last,avgPrev,thresholdPct});
});
return{trigger:drops.length>0,drops,thresholdPct};
}

let _vehicleAIRulesRegistered=false;
// registerVehicleAIRules() — dipanggil sekali saat boot (self-test.js
// init()), idempotent lewat guard, return false kalau AIDecision belum ada.
function registerVehicleAIRules(){
if(_vehicleAIRulesRegistered)return false;
if(typeof AIDecision==='undefined'||!AIDecision.rules||typeof AIDecision.rules.register!=='function')return false;
AIDecision.rules.register({
id:'vehicle-service-overdue',
category:'vehicle',
severity:'warning',
weight:5,
cooldownHours:24,
description:'Ada kendaraan dengan item servis yang sudah lewat jatuh tempo (predictService status="lewat").',
condition:()=>_vehicleOverdueCheck().trigger,
action:()=>{
const c=_vehicleOverdueCheck();
const first=c.overdue[0];
const extra=c.overdue.length>1?` (+${c.overdue.length-1} item lain)`:'';
return{message:`Servis lewat jatuh tempo: ${first.vehicleName} — ${first.categoryName} (${Math.abs(first.sisaKm)} km lewat batas)${extra}.`};
},
});
AIDecision.rules.register({
id:'vehicle-fuel-efficiency-drop',
category:'vehicle',
severity:'info',
weight:3,
cooldownHours:72,
description:'Konsumsi BBM (km/liter) pengisian Full Tank terakhir turun ≥ambang % (bisa diatur user) dari rata-rata histori sebelumnya (min. 4 log Isi Full Tank berurutan).',
condition:()=>_vehicleFuelEfficiencyDropCheck().trigger,
action:()=>{
const c=_vehicleFuelEfficiencyDropCheck();
const first=c.drops[0];
const extra=c.drops.length>1?` (+${c.drops.length-1} kendaraan lain)`:'';
const message=`Konsumsi BBM ${first.vehicleName} turun ${first.dropPct}% dari biasanya (skrg ${first.last.toFixed(1)} km/L vs rata-rata ${first.avgPrev.toFixed(1)} km/L, ambang ${first.thresholdPct}%)${extra}.`;
// Sesi 12 — cross-engine: LogisticsEngine.fuelCalculator() (Tahap 3, sudah
// ADA & teruji) dipakai di sini utk hitung selisih biaya BBM per 100km
// akibat penurunan efisiensi, BUKAN rumus baru yg ditulis ulang di sini.
// Guard typeof supaya fallback ke message-only (perilaku lama) kalau
// LogisticsEngine/estimateRpPerKm belum ter-load atau histori harga BBM
// kendaraan ini belum cukup (estimateRpPerKm return null).
if(typeof LogisticsEngine==='undefined'||typeof LogisticsEngine.fuelCalculator!=='function'||typeof estimateRpPerKm!=='function'){
return{message};
}
const est=estimateRpPerKm(first.vehicleId);
if(!est||!est.avgHarga){
return{message};
}
const fmt=typeof fmtFull==='function'?fmtFull:(n=>'Rp '+Math.round(n||0).toLocaleString('id-ID'));
const sekarang=LogisticsEngine.fuelCalculator({jarak:100,konsumsiKmPerLiter:first.last,hargaBBM:est.avgHarga});
const biasanya=LogisticsEngine.fuelCalculator({jarak:100,konsumsiKmPerLiter:first.avgPrev,hargaBBM:est.avgHarga});
const selisih=sekarang.biayaBBM-biasanya.biayaBBM;
return{
message,
title:'Cek performa BBM kendaraan',
affectedModules:['vehicle','finance'],
estimatedImpact:{
biayaBBMPer100kmSekarang:fmt(sekarang.biayaBBM),
biayaBBMPer100kmBiasanya:fmt(biasanya.biayaBBM),
selisihPer100km:(selisih>=0?'+':'')+fmt(selisih),
},
actions:['Cek filter udara & tekanan ban','Jadwalkan servis bila performa terus turun'],
};
},
});
// _vehicleCapacityMissingCheck() — cek kendaraan yg dipakai operasional Shop
// (muncul di D.deliveryPlans, audit item #3) tapi capacityKg/capacityM3
// (vehicle-core.js, field yg sudah ada) masih kosong -> TripEngine.
// vehicleCapacity() tidak bisa hitung status AMAN/OVERLOAD. Murni baca D
// langsung, 0 field/index baru.
function _vehicleCapacityMissingCheck(){
if(typeof D==='undefined'||!D.vehicles||!D.deliveryPlans)return{trigger:false,missing:[]};
const usedIds=new Set(D.deliveryPlans.map(p=>p.vehicleId).filter(Boolean));
const missing=D.vehicles.filter(v=>usedIds.has(v.id)&&!v.capacityKg&&!v.capacityM3);
return{trigger:missing.length>0,missing};
}
AIDecision.rules.register({
id:'vehicle-capacity-missing',
category:'vehicle',
severity:'warning',
weight:4,
cooldownHours:72,
description:'Kendaraan dipakai di Rencana Pengiriman tapi kapasitas angkut (capacityKg/capacityM3, Kelola Kendaraan) belum diisi, jadi cek AMAN/OVERLOAD muatan tidak bisa jalan.',
condition:()=>_vehicleCapacityMissingCheck().trigger,
action:()=>{
const c=_vehicleCapacityMissingCheck();
const first=c.missing[0];
const extra=c.missing.length>1?` (+${c.missing.length-1} kendaraan lain)`:'';
// Sesi 344b — actionTargets: bawa id kendaraan yg missing supaya AIRecommendCard
// (ai-chat.js) bisa render tombol yg langsung panggil editVehicle(idx), bukan cuma
// teks 'actions' yg user harus cari sendiri ke Kelola Kendaraan.
return{message:`Kapasitas angkut "${first.name}" belum diisi, cek muatan di Rencana Pengiriman belum akurat${extra}.`,actions:['Isi Kapasitas Angkut Maks di Kelola Kendaraan'],actionTargets:[{type:'vehicle',id:first.id}]};
},
});
_vehicleAIRulesRegistered=true;
return true;
}

// modules/vehicle/shop-katalog-dinamis-api.js — Shop Katalog Sparepart
// Dinamis (per-Kendaraan) API. Batch: "ringan dulu" — cuma layer data
// (API), TIDAK ada presenter/modal baru di sesi ini (menyusul kalau API
// ini sudah aman dipakai).
//
// PRINSIP (100% REUSE, sama persis pola AssetMaintenanceAPI/
// PropertyManagementAPI):
//  - TIDAK ada field baru ditambah ke D.vehicles / D.sparepartCats /
//    D.partsCatalog / D.servisLogs.
//  - TIDAK ada rumus interval baru — intervalKm tetap dari
//    D.sparepartCats (kategori sparepart, sudah ada, lihat
//    modules/shared/data-default.js DEFAULT_SPAREPARTS).
//  - Guard berlapis (typeof X==='undefined' -> {ok:false,reason}) biar
//    file ini aman dimuat berdiri sendiri / sebelum data terkait ada.
//  - Nama koleksi part katalog per-kendaraan belum pasti seragam di
//    seluruh build (kandidat: D.partsCatalog / D.vehiclePartsCatalog).
//    _catalogList() cek KEDUANYA apa adanya, TIDAK memutuskan satu nama
//    "benar" secara sepihak — supaya tidak salah asumsi struktur data
//    yang sudah berjalan di produksi.
//  - Pencocokan part↔kendaraan & part↔kategori sparepart dilakukan
//    read-only (tidak menulis apa pun), pakai pola matching TOLERAN
//    (cek beberapa nama field kandidat) karena skema field persis milik
//    modul Vehicle Catalog (catalogModal, VehicleCatalogUI) tidak
//    tercakup di batch file ini.
const ShopKatalogDinamisAPI = {

  // MAX_KENDARAAN — batas tampil selector kendaraan di UI shop (S/K:
  // "kalau ada 5 kendaraan"). Cuma batas TAMPILAN daftar pilihan, bukan
  // batas jumlah D.vehicles yang boleh ada (lebih dari 5 tetap aman,
  // sisanya cukup discroll — lihat daftarKendaraan()).
  MAX_KENDARAAN: 5,

  // _vehicles() — satu titik akses ke D.vehicles, guard sama persis
  // AssetMaintenanceAPI._assets().
  _vehicles() {
    if (typeof D === 'undefined' || !D || !Array.isArray(D.vehicles)) return [];
    return D.vehicles;
  },

  // _catalogList() — satu titik akses ke katalog part per-kendaraan.
  // Cek 2 nama koleksi kandidat (lihat catatan PRINSIP di atas), pakai
  // yang pertama ADA & berisi array — TIDAK menggabung keduanya supaya
  // tidak dobel kalau ternyata sinonim.
  _catalogList() {
    if (typeof D === 'undefined' || !D) return [];
    if (Array.isArray(D.partsCatalog)) return D.partsCatalog;
    if (Array.isArray(D.vehiclePartsCatalog)) return D.vehiclePartsCatalog;
    return [];
  },

  // _sparepartCats() — satu titik akses ke D.sparepartCats (kategori +
  // intervalKm, SUDAH ADA — DEFAULT_SPAREPARTS).
  _sparepartCats() {
    if (typeof D === 'undefined' || !D || !Array.isArray(D.sparepartCats)) return [];
    return D.sparepartCats;
  },

  // _servisLogs() — satu titik akses ke D.servisLogs (riwayat servis,
  // SUDAH ADA — dipakai servisModal/onServisItemAutofillInterval()).
  _servisLogs() {
    if (typeof D === 'undefined' || !D || !Array.isArray(D.servisLogs)) return [];
    return D.servisLogs;
  },

  // daftarKendaraan() — field "Pilih Kendaraan" utk fitur Shop. Dipotong
  // ke MAX_KENDARAAN item TERBARU (kendaraan lain tetap ada di
  // D.vehicles, cuma tidak dimasukkan array ini — UI bisa tambah
  // "lainnya" sendiri kalau perlu, TIDAK di-handle di sini).
  daftarKendaraan() {
    const list = this._vehicles().slice(0, this.MAX_KENDARAAN).map((v) => ({
      id: v.id,
      name: v.name,
      emoji: v.emoji || (v.jenis === 'mobil' ? '🚗' : v.jenis === 'listrik' ? '🔋' : '🏍️'),
      jenis: v.jenis || 'motor',
    }));
    return { ok: true, count: list.length, totalKendaraan: this._vehicles().length, list };
  },

  // _cocokKendaraan(part, vehicleId) — TOLERAN thd 2 skema compat yang
  // mungkin dipakai: array id (part.compatVehicleIds) ATAU array objek
  // {id,...} (part.compatVehicles). Part TANPA daftar compat sama
  // sekali dianggap "berlaku umum" (cocok semua kendaraan) — konsisten
  // dgn UI catalogModal yang menandai field ini opsional.
  _cocokKendaraan(part, vehicleId) {
    const a = Array.isArray(part.compatVehicleIds) ? part.compatVehicleIds : null;
    const b = Array.isArray(part.compatVehicles) ? part.compatVehicles : null;
    if (!a && !b) return true;
    if (a && a.includes(vehicleId)) return true;
    if (b && b.some((x) => (x && x.id) === vehicleId)) return true;
    return false;
  },

  // _kategoriUntukPart(part) — cocokkan nama part ke D.sparepartCats
  // (case-insensitive substring, pola sama persis
  // onServisItemAutofillInterval()/guessSparepartFromReceiptText() yang
  // sudah ada) supaya dapat intervalKm APA ADANYA, TIDAK dikarang baru.
  _kategoriUntukPart(part) {
    const nama = (part.name || '').toLowerCase();
    const cats = this._sparepartCats();
    if (!nama || !cats.length) return null;
    return cats.find((c) => c.name && (nama.includes(c.name.toLowerCase()) || c.name.toLowerCase().includes(nama))) || null;
  },

  // _servisTerakhir(vehicleId, part) — entri D.servisLogs paling baru
  // utk kendaraan+part ini (match by vehicleId + nama item mengandung
  // nama part, TOLERAN thd penamaan bebas user di field "Jenis
  // Servis/Item"), diurutkan by tanggal desc, APA ADANYA (0 rumus baru).
  _servisTerakhir(vehicleId, part) {
    const nama = (part.name || '').toLowerCase();
    if (!nama) return null;
    const logs = this._servisLogs()
      .filter((s) => s && s.vehicleId === vehicleId && (s.item || '').toLowerCase().includes(nama));
    if (!logs.length) return null;
    logs.sort((x, y) => String(y.tanggal || '').localeCompare(String(x.tanggal || '')));
    return logs[0];
  },

  // katalogUntuk(vehicleId) — INTI fitur: "kendaraan mana -> katalog
  // part item interval mana", dinamis. Guard berlapis; kalau koleksi
  // katalog part belum ada di build ini, balikin {ok:false,reason}
  // TANPA melempar error (aman dipanggil dari presenter manapun).
  katalogUntuk(vehicleId) {
    if (!vehicleId) return { ok: false, reason: 'Kendaraan belum dipilih' };
    const veh = this._vehicles().find((v) => v.id === vehicleId);
    if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
    const catalog = this._catalogList();
    if (!catalog.length) return { ok: false, reason: 'Katalog part belum tersedia di perangkat ini' };

    const items = catalog
      .filter((p) => p && this._cocokKendaraan(p, vehicleId))
      .map((p) => {
        const kategori = this._kategoriUntukPart(p);
        const last = this._servisTerakhir(vehicleId, p);
        const lastKm = last ? (last.km || null) : null;
        const kmSekarang = (veh.kmAwal != null) ? veh.kmAwal : null; // apa adanya, 0 estimasi baru
        const kmSejakServis = (lastKm != null && kmSekarang != null) ? Math.max(0, kmSekarang - lastKm) : null;
        const intervalKm = kategori ? kategori.intervalKm : null;
        const status = (intervalKm && kmSejakServis != null)
          ? (kmSejakServis >= intervalKm ? 'perlu-ganti' : 'aman')
          : 'belum-diketahui';
        return {
          id: p.id,
          nama: p.name,
          oemCode: p.oemCode || null,
          kategori: kategori ? kategori.name : null,
          intervalKm,
          lastServisTanggal: last ? last.tanggal : null,
          lastServisKm: lastKm,
          kmSejakServis,
          status,
        };
      });

    return { ok: true, kendaraan: { id: veh.id, name: veh.name }, count: items.length, items };
  },

};

// modules/vehicle/shop-katalog-dinamis-presenter.js — Shop Katalog
// Sparepart Dinamis Presenter. 100% REUSE ShopKatalogDinamisAPI
// (modules/vehicle/shop-katalog-dinamis-api.js) — TIDAK ada
// query/hitungan baru di sini, murni render + simpan pilihan
// kendaraan terakhir (localStorage-style var, sama pola _txAccManuallySet
// dkk di codebase: variabel modul biasa, bukan D/localStorage baru).
//
// KONTRAK HTML yang diharapkan (container HARUS sudah ada di
// halaman/modal terkait — presenter ini TIDAK membuat modal baru):
//   <select id="shopKatalogVehicleSelect"></select>
//   <div id="shopKatalogList"></div>
const ShopKatalogDinamisPresenter = {

  _selectedVehicleId: null,

  // render() — titik masuk. Isi <select> pilihan kendaraan (kalau
  // belum diisi/berubah) lalu render daftar part utk kendaraan
  // terpilih (default: kendaraan pertama).
  render() {
    const sel = document.getElementById('shopKatalogVehicleSelect');
    const list = document.getElementById('shopKatalogList');
    if (!sel || !list) return; // container belum ada di halaman ini, aman diam2.

    if (typeof ShopKatalogDinamisAPI === 'undefined') {
      list.innerHTML = '<div class="empty"><div class="empty-text">Fitur katalog belum tersedia</div></div>';
      return;
    }

    const dk = ShopKatalogDinamisAPI.daftarKendaraan();
    if (!dk.ok || dk.count === 0) {
      sel.innerHTML = '<option value="">— Belum ada kendaraan —</option>';
      list.innerHTML = '<div class="empty"><div class="empty-icon">🏍️</div><div class="empty-text">Tambahkan kendaraan dulu lewat Car Notes</div></div>';
      return;
    }

    if (!this._selectedVehicleId || !dk.list.some((v) => v.id === this._selectedVehicleId)) {
      this._selectedVehicleId = dk.list[0].id;
    }

    sel.innerHTML = dk.list.map((v) => `<option value="${escapeHtml(v.id)}"${v.id === this._selectedVehicleId ? ' selected' : ''}>${v.emoji} ${escapeHtml(v.name)}</option>`).join('');
    this._renderList(list);
  },

  // onVehicleChange(selectEl) — dipanggil dari onchange <select>.
  onVehicleChange(selectEl) {
    this._selectedVehicleId = selectEl.value || null;
    const list = document.getElementById('shopKatalogList');
    if (list) this._renderList(list);
  },

  // _renderList(el) — murni tampilkan hasil
  // ShopKatalogDinamisAPI.katalogUntuk() APA ADANYA, 0 logic tambahan.
  _renderList(el) {
    if (!this._selectedVehicleId) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Pilih kendaraan dulu</div></div>';
      return;
    }
    const res = ShopKatalogDinamisAPI.katalogUntuk(this._selectedVehicleId);
    if (!res.ok) {
      el.innerHTML = `<div class="empty"><div class="empty-text">${escapeHtml(res.reason || 'Data belum tersedia')}</div></div>`;
      return;
    }
    if (res.count === 0) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Belum ada part katalog utk kendaraan ini</div></div>';
      return;
    }
    const badge = { 'perlu-ganti': ['🔴', 'Perlu Diganti'], 'aman': ['🟢', 'Aman'], 'belum-diketahui': ['⚪', 'Belum Diketahui'] };
    el.innerHTML = res.items.map((it) => {
      const [dot, label] = badge[it.status] || badge['belum-diketahui'];
      const sub = it.intervalKm ? `Interval ${it.intervalKm.toLocaleString('id-ID')} km` : 'Interval belum diatur';
      return `<div class="tx-item"><div class="tx-icon u-bgaccsoft">🔧</div><div class="tx-info"><div class="tx-name">${escapeHtml(it.nama)}</div><div class="tx-meta">${sub}${it.kategori ? ' · ' + escapeHtml(it.kategori) : ''}</div></div><div class="tx-amount" style="font-size:11px">${dot} ${label}</div></div>`;
    }).join('');
  },

};

// modules/vehicle/torsi-vehicle-api.js — Torsi Vehicle Selector API (Sesi 1).
// Basis: DESIGN_torsi-vehicle-selector_shop-import-export.md, Bagian A.
// Batch: "ringan dulu" — cuma layer data (API) + migrasi, TIDAK ada perubahan
// HTML/modal/action-wrapper di sesi ini (menyusul sesi berikutnya setelah API
// ini aman dipakai — lihat "Urutan implementasi disarankan" di dokumen desain).
//
// PRINSIP (100% REUSE, sama persis pola ShopKatalogDinamisAPI):
//  - daftarKendaraan() TIDAK diduplikasi — panggil ulang
//    ShopKatalogDinamisAPI.daftarKendaraan() apa adanya, supaya daftar
//    kendaraan di Shop & di Torsi selalu identik (1 sumber kebenaran, RULE
//    "ZIP = source of truth" & anti duplikasi). File ini HARUS dimuat SETELAH
//    modules/vehicle/shop-katalog-dinamis-api.js (lihat scripts/build.js).
//  - TIDAK ada field baru ditambah ke D.vehicles.
//  - Guard berlapis (typeof X==='undefined' -> {ok:false,reason}) biar file
//    ini aman dimuat berdiri sendiri / sebelum data terkait ada.
//
// CATATAN PENTING soal bentuk data D.torsiChecklist (beda dari asumsi awal di
// dokumen desain): di build ini `Torsi` (car-notes.js) SUDAH menyimpan
// checklist per-kendaraan, bukan flat — lihat Torsi.loadPersisted()/
// Torsi.persist(): D.torsiChecklist[vehicleId] = {checked:{}, biaya:{},
// pageMode}. API ini TIDAK mengubah struktur tsb (0 perubahan skema), cuma
// jadi 1 pintu baca/tulis tambahan yang bisa dipanggil presenter TANPA
// bergantung ke variabel global `curVehicleId` — dibutuhkan utk field "Pilih
// Kendaraan" independen di torsiModal (menyusul Sesi berikutnya, lihat A.4-A.5
// di dokumen desain).
const TorsiVehicleAPI = {

  // MAX_KENDARAAN — reuse LANGSUNG konstanta ShopKatalogDinamisAPI (bukan
  // duplikasi angka) supaya kalau batasnya berubah, cukup diubah 1 tempat.
  // Fallback ke 5 kalau (skenario tidak normal) file itu belum termuat.
  get MAX_KENDARAAN() {
    return (typeof ShopKatalogDinamisAPI !== 'undefined') ? ShopKatalogDinamisAPI.MAX_KENDARAAN : 5;
  },

  // _vehicles() — satu titik akses ke D.vehicles, guard sama persis
  // ShopKatalogDinamisAPI._vehicles().
  _vehicles() {
    if (typeof D === 'undefined' || !D || !Array.isArray(D.vehicles)) return [];
    return D.vehicles;
  },

  // _checklist() — satu titik akses ke D.torsiChecklist, self-heal kalau
  // korup/belum ada (object kosong), TIDAK menimpa data valid yang sudah ada.
  _checklist() {
    if (typeof D === 'undefined' || !D) return {};
    if (!D.torsiChecklist || typeof D.torsiChecklist !== 'object' || Array.isArray(D.torsiChecklist)) {
      D.torsiChecklist = {};
    }
    return D.torsiChecklist;
  },

  // daftarKendaraan() — REUSE LANGSUNG ShopKatalogDinamisAPI.daftarKendaraan()
  // (kontrak {ok,count,totalKendaraan,list} sudah pas, tidak perlu duplikat
  // logic). Fallback minimal kalau file itu ternyata belum termuat.
  daftarKendaraan() {
    if (typeof ShopKatalogDinamisAPI !== 'undefined') return ShopKatalogDinamisAPI.daftarKendaraan();
    const list = this._vehicles().slice(0, this.MAX_KENDARAAN).map((v) => ({
      id: v.id,
      name: v.name,
      emoji: v.emoji || (v.jenis === 'mobil' ? '🚗' : v.jenis === 'listrik' ? '🔋' : '🏍️'),
      jenis: v.jenis || 'motor',
    }));
    return { ok: true, count: list.length, totalKendaraan: this._vehicles().length, list };
  },

  // checklistUntuk(vehicleId) — baca D.torsiChecklist[vehicleId] apa adanya
  // (bentuk asli: {checked, biaya, pageMode}, lihat catatan bentuk data di
  // atas), TANPA menulis apa pun kalau belum ada record (biar tidak nyampah
  // key kendaraan yang belum pernah dicek torsinya sama sekali).
  checklistUntuk(vehicleId) {
    if (!vehicleId) return { ok: false, reason: 'Kendaraan belum dipilih' };
    const veh = this._vehicles().find((v) => v.id === vehicleId);
    if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
    const rec = this._checklist()[vehicleId];
    return {
      ok: true,
      kendaraan: { id: veh.id, name: veh.name },
      checked: (rec && rec.checked) ? rec.checked : {},
      biaya: (rec && rec.biaya) ? rec.biaya : {},
      pageMode: (rec && rec.pageMode) || 'normal',
    };
  },

  // setCheck(vehicleId, partKey, patch) — tulis ke
  // D.torsiChecklist[vehicleId].checked/biaya[partKey], buat record kalau
  // belum ada (pola sama Torsi.persist()). patch: {checked?:bool, biaya?:num}.
  setCheck(vehicleId, partKey, patch) {
    if (!vehicleId || !partKey || !patch || typeof patch !== 'object') {
      return { ok: false, reason: 'Data tidak lengkap' };
    }
    const veh = this._vehicles().find((v) => v.id === vehicleId);
    if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
    const checklist = this._checklist();
    if (!checklist[vehicleId]) checklist[vehicleId] = { checked: {}, biaya: {}, pageMode: 'normal' };
    const rec = checklist[vehicleId];
    if (!rec.checked || typeof rec.checked !== 'object') rec.checked = {};
    if (!rec.biaya || typeof rec.biaya !== 'object') rec.biaya = {};
    if (patch.checked !== undefined) rec.checked[partKey] = !!patch.checked;
    if (patch.biaya !== undefined) rec.biaya[partKey] = patch.biaya;
    if (typeof save === 'function') save();
    return { ok: true };
  },

  // _migrateFlatToPerVehicle(d) — Sesi "Revisi migrasi" (lihat DESIGN dok.,
  // Bagian A.2): JARING PENGAMAN murni kalau ada backup/JSON restore dari
  // versi lebih tua & D.torsiChecklist-nya belum per-kendaraan (key BUKAN id
  // kendaraan valid & value TIDAK berbentuk {checked:{},biaya:{}} khas record
  // per-kendaraan) — data lama TIDAK dibuang, dipindah apa adanya ke
  // kendaraan pertama sbg default (`_legacyFlat`), supaya tidak ada
  // kehilangan data. Kalau `d.vehicles` kosong, dibiarkan apa adanya (tidak
  // ada tujuan migrasi). 0 logic baru dari versi sebelumnya — cuma jadi
  // fungsi murni (terima `d` sbg parameter, bukan baca D global) supaya bisa
  // dipanggil dari DATA_MIGRATIONS (features-helpers-global-security.js),
  // yang guard idempotensinya SUDAH ditangani `runDataMigrations()` lewat
  // `d.schemaVersion` — makanya TIDAK ADA lagi flag `D._migratedTorsiVehicle`
  // di sini (dihapus, digantikan mekanisme SCHEMA_VERSION yang sudah ada).
  _migrateFlatToPerVehicle(d) {
    if (!d) return;
    const raw = d.torsiChecklist;
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return;
    const keys = Object.keys(raw);
    if (!keys.length) return;
    const vehicles = Array.isArray(d.vehicles) ? d.vehicles : [];
    const vehicleIds = new Set(vehicles.map((v) => v.id));
    const looksFlat = keys.every((k) => {
      if (vehicleIds.has(k)) return false; // key sudah id kendaraan valid -> bukan flat
      const v = raw[k];
      const isPerVehicleShape = v && typeof v === 'object' && !Array.isArray(v)
        && (v.checked === undefined || (typeof v.checked === 'object' && !Array.isArray(v.checked)));
      return !isPerVehicleShape;
    });
    if (looksFlat && vehicles.length) {
      d.torsiChecklist = { [vehicles[0].id]: { checked: {}, biaya: {}, pageMode: 'normal', _legacyFlat: raw } };
    }
  },

};

// ai-chat.js — Chat AI (RefAI): UI edit aksi chat, kirim pesan ke provider AI (sendChat/
// callAIProviderRaw), Advisor (rule-based tips) & AIWidget (widget rekomendasi AI generik dipakai
// modul lain). Dipisah dari features-aiwidget-reminder-gdrive-search.js (Sesi 4 restrukturisasi
// folder, blok 1 — lihat AUDIT-STRUKTUR-FOLDER.md) murni pengelompokan ulang file, BUKAN
// perubahan perilaku. PENTING: file ini HARUS dimuat sesuai urutan build.js (GROUP_A/GROUP_B) —
// cek scripts/build.js untuk urutan lengkap terkini.

// unifiedBriefingChatContext() — S111 (Batch 13, AI Daily Briefing Integration: Finance+Vehicle).
// Jembatan tipis MURNI BACA ke UnifiedAIBriefing.generate() (modules/cross/unified-ai-briefing.js,
// Sesi 88 — sendiri 100% reuse UnifiedSummaryAPI.summary() -> CrossAIHook.getAIHook() ->
// FinanceDashboard.getAIHook()+VehicleAIHook.fleetSummary()). TIDAK ada rumus/agregasi baru di
// sini — fungsi ini HANYA guard typeof + try/catch di sekitar generate() supaya aman dipanggil dari
// initChat()/sendChat() walau modul briefing belum dimuat di halaman tertentu (pola sama persis
// guard `typeof AIService==='undefined'` di AIDailyBriefingCard/AIStatusCard). null kalau briefing
// belum tersedia/gagal — pemanggil (initChat/systemPrompt) TETAP jalan seperti biasa, cuma tanpa
// baris briefing (silent, bukan error blocking). Scope S111 SENGAJA TIDAK termasuk asset (belum
// ada AssetAIAdvisor/Asset.getAIHook() terpadu — lihat docs/PRODUCT_DECISIONS.md).
function unifiedBriefingChatContext(){
if(typeof UnifiedAIBriefing==='undefined')return null;
try{
const b=UnifiedAIBriefing.generate();
return (b&&b.ok)?b.text:null;
}catch(e){console.warn('unifiedBriefingChatContext: gagal ambil UnifiedAIBriefing',e);return null;}
}
// recommendationPanelChatContext() — S114 (Batch 13, Unified Recommendation
// Panel Integration). Jembatan tipis MURNI BACA ke RecommendationPanel.
// getRecommendations() (modules/cross/recommendation-panel.js, sesi ini —
// sendiri 100% reuse DecisionCenterAPI.summary() -> LifeDashboardSummaryAPI/
// PriorityEngine/FinanceIntelligence.insights()+VehicleIntelligence.
// insights()). TIDAK ada rumus/filter baru di sini — hanya guard typeof +
// try/catch + format teks pakai RecommendationPanel._icon() (helper
// presentasional yang SUDAH ADA, dipakai apa adanya, BUKAN dibuat ulang),
// pola sama persis unifiedBriefingChatContext() di atas. null kalau
// RecommendationPanel belum dimuat/tidak ada rekomendasi/generate() error —
// pemanggil (initChat()/_sendChatInner()) TETAP jalan seperti biasa, cuma
// tanpa baris rekomendasi (silent, bukan error blocking). Scope S114
// SENGAJA TIDAK termasuk asset (sama seperti S111 — belum ada
// AssetAIAdvisor/Asset.getAIHook() terpadu).
function recommendationPanelChatContext(){
if(typeof RecommendationPanel==='undefined'||typeof RecommendationPanel.getRecommendations!=='function')return null;
try{
const{ok,recommendations}=RecommendationPanel.getRecommendations();
if(!ok||!Array.isArray(recommendations)||!recommendations.length)return null;
return recommendations.map(r=>`${RecommendationPanel._icon(r.type)} ${r.message}`).join('\n');
}catch(e){console.warn('recommendationPanelChatContext: gagal ambil RecommendationPanel',e);return null;}
}
// actionQueueChatContext() — S115 (ActionQueue Public API Integration).
// Jembatan tipis MURNI BACA ke ActionQueue.getQueue() (modules/cross/
// action-queue.js — sendiri 100% reuse DecisionCenterAPI.summary() ->
// LifeDashboardSummaryAPI/PriorityEngine). TIDAK ada rumus/filter/sorting
// baru di sini — hanya guard typeof + try/catch + format teks pakai
// ActionQueue._label()/_vehicleIcon() (helper presentasional yang SUDAH
// ADA, dipakai apa adanya, BUKAN dibuat ulang — sama persis format yang
// dipakai ActionQueue.render() sendiri utk tiap baris), pola sama persis
// recommendationPanelChatContext() di atas. null kalau ActionQueue belum
// dimuat/tidak ada item di queue/getQueue() error — pemanggil
// (initChat()/_sendChatInner()) TETAP jalan seperti biasa, cuma tanpa
// baris action queue (silent, bukan error blocking).
function actionQueueChatContext(){
if(typeof ActionQueue==='undefined'||typeof ActionQueue.getQueue!=='function')return null;
try{
const{ok,priorityItems}=ActionQueue.getQueue();
if(!ok||!Array.isArray(priorityItems)||!priorityItems.length)return null;
return priorityItems.map((item,idx)=>{
const icon=item.kind==='finance'?'💰':ActionQueue._vehicleIcon(item.vehicleType);
return `${idx+1}. ${icon} ${ActionQueue._label(item)}`;
}).join('\n');
}catch(e){console.warn('actionQueueChatContext: gagal ambil ActionQueue',e);return null;}
}
function chatActionEditFormHTML(actionId,type,data){
const fields=CHAT_ACTION_EDIT_FIELDS[type]||[];
const rows=fields.map(f=>{
const val=data[f.key]!=null?data[f.key]:'';
const id=`chatActionEdit_${actionId}_${f.key}`;
if(f.type==='select'){
const opts=typeof f.options==='function'?f.options():f.options;
return `<div class="fg u-mb6"><label class="fl u-fs11">${escapeHtml(f.label)}</label><select class="fi" id="${id}">${opts.map(([v,l])=>`<option value="${escapeHtml(String(v))}" ${sameId(v,val)?'selected':''}>${escapeHtml(l)}</option>`).join('')}</select></div>`;
}
return `<div class="fg u-mb6"><label class="fl u-fs11">${escapeHtml(f.label)}</label><input class="fi" id="${id}" type="${f.type}" value="${escapeHtml(String(val))}"></div>`;
}).join('');
return `<div class="u-fw700 u-mb6">✏️ Edit ${CHAT_ACTION_LABELS[type]||''}</div>
    ${rows}
    <div class="u-flex u-gap8 u-mt4">
      <button class="btn btn-primary btn-sm" data-action="saveChatActionEdit" data-args="${escapeHtml(JSON.stringify([actionId]))}">💾 Simpan Perubahan</button>
      <button class="btn btn-ghost btn-sm" data-action="cancelChatActionEdit" data-args="${escapeHtml(JSON.stringify([actionId]))}">↩️ Batal Edit</button>
    </div>`;
}
function editChatAction(actionId){
const pending=_pendingChatActions[actionId];
const el=document.getElementById('chatAction_'+actionId);
if(!pending||!el)return;
el.innerHTML=chatActionEditFormHTML(actionId,pending.type,pending.data);
}
function saveChatActionEdit(actionId){
const pending=_pendingChatActions[actionId];
const el=document.getElementById('chatAction_'+actionId);
if(!pending||!el)return;
const fields=CHAT_ACTION_EDIT_FIELDS[pending.type]||[];
const newData={...pending.data};
fields.forEach(f=>{
const inputEl=document.getElementById(`chatActionEdit_${actionId}_${f.key}`);
if(!inputEl)return;
let v=inputEl.value;
if(f.type==='number')v=(v===''?undefined:Number(v));
newData[f.key]=v;
});
pending.data=newData;
el.innerHTML=chatActionInnerHTML(actionId,pending.type,newData);
}
function cancelChatActionEdit(actionId){
const pending=_pendingChatActions[actionId];
const el=document.getElementById('chatAction_'+actionId);
if(!pending||!el)return;
el.innerHTML=chatActionInnerHTML(actionId,pending.type,pending.data);
}
function confirmChatAction(actionId){
const pending=_pendingChatActions[actionId];
const el=document.getElementById('chatAction_'+actionId);
if(!pending||!el)return;
try{
const msg=CHAT_ACTION_HANDLERS[pending.type](pending.data);
el.innerHTML=`<div class="u-fw700">✅ Tersimpan</div><div class="u-fs13 u-t2">${escapeHtml(msg)}</div>`;
toast('✅ Tersimpan dari chat AI');
}catch(e){
el.innerHTML=`<div class="u-fw700" style="color:#ff5050">⚠️ Gagal: ${escapeHtml(e.message||'Terjadi kesalahan')}</div>`;
}
delete _pendingChatActions[actionId];
}
function cancelChatAction(actionId){
const el=document.getElementById('chatAction_'+actionId);
if(el)el.innerHTML='<div class="u-t2">❌ Dibatalkan</div>';
delete _pendingChatActions[actionId];
}
function initChat(){
if(chatInited)return;chatInited=true;
let html='<div class="chat-bubble ai">Halo W! 👋 Saya AI asisten pribadi Anda. Saya sudah baca semua data: keuangan, perkembangan anak, kendaraan (KM, BBM, servis), absensi/gaji, dan bisnis shop. Tanya apa saja!</div>';
try{
const reminders=getProactiveReminders();
if(reminders.length){
const list=reminders.map(r=>`• ${escapeHtml(r)}`).join('<br>');
html+=`<div class="chat-bubble ai">📋 <b>Sebelum lanjut, ada yang perlu diperhatikan nih:</b><br>${list}</div>`;
}
}catch(e){console.error('Gagal cek reminder proaktif:',e);}
try{
const briefingText=unifiedBriefingChatContext();
if(briefingText){
html+=`<div class="chat-bubble ai">📋 <b>Ringkasan Harian Finance & Vehicle:</b><br>${escapeHtml(briefingText)}</div>`;
}
}catch(e){console.error('Gagal ambil Unified AI Briefing:',e);}
try{
const recoText=recommendationPanelChatContext();
if(recoText){
html+=`<div class="chat-bubble ai">💡 <b>Rekomendasi utk Anda:</b><br>${escapeHtml(recoText).replace(/\n/g,'<br>')}</div>`;
}
}catch(e){console.error('Gagal ambil Recommendation Panel:',e);}
try{
const queueText=actionQueueChatContext();
if(queueText){
html+=`<div class="chat-bubble ai">🗂️ <b>Antrean Tindakan:</b><br>${escapeHtml(queueText).replace(/\n/g,'<br>')}</div>`;
}
}catch(e){console.error('Gagal ambil Action Queue:',e);}
document.getElementById('chatBox').innerHTML=html;
}
function aiQ(q){document.getElementById('chatInput').value=q;sendChat();}
async function sendChat(){
if(_saveGuards['chat'])return;
const btn=document.getElementById('chatSendBtn');
_saveGuards['chat']=true;
if(btn){btn.disabled=true;btn.style.opacity='0.5';}
try{
await _sendChatInner();
} finally {
_saveGuards['chat']=false;
if(btn){btn.disabled=false;btn.style.opacity='';}
}
}
