_selfTestAssert(getPTKP('TK1')===58500000,'PTKP TK/1 harus 58.500.000, dapat '+getPTKP('TK1'));
_selfTestAssert(getPTKP('K0')===58500000,'PTKP K/0 harus 58.500.000, dapat '+getPTKP('K0'));
