//   service -> Kendaraan > tab Servis > servisList (SAMA PERSIS target
//     'cn-servis' di dashboard-hub-registry.js)
const VEHICLE_ANALYTICS_NAV_TARGETS = Object.freeze({
  total: { page: 'carnotes', tab: 'insight', subtab: 'rekomendasi', goTo: 'vehAnalyticsWrap' },
  fuel: { page: 'carnotes', tab: 'bbm', subtab: 'ringkasan', goTo: 'bbmList' },
  service: { page: 'carnotes', tab: 'servis', goTo: 'servisList' },
  trend: { page: 'carnotes', tab: 'insight', subtab: 'rekomendasi', goTo: 'vehAnalyticsWrap' },
});

const VehicleAnalyticsPresenter = {

  render() {
    const el = document.getElementById('vehanalyticsGrid');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    if (typeof VehicleCostSummary === 'undefined') {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data vehicle cost summary belum tersedia</div></div>';
      return;
    }
    const summary = VehicleCostSummary.summary();
    if (!summary.ok) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data vehicle cost summary belum tersedia</div></div>';
      return;
    }
    const hasVehicles = (typeof VehicleIntelligence !== 'undefined')
      && VehicleIntelligence.fleetSummary().totalVehicles > 0;
    if (!hasVehicles) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Belum ada data kendaraan</div></div>';
      return;
    }

    const cards = [
      this._totalCard(summary),
      this._fuelCard(summary),
      this._serviceCard(summary),
      this._trendCard(summary),
    ];

    // S253 (Batch Vehicle Navigation Consistency): SELURUH kartu clickable
    // lewat mekanisme SAMA PERSIS FinanceDashboard.render()/
    // VehicleDashboard.render() — tiap kartu carry field onClick:{action,
    // args} sendiri (ditempel di masing2 _xxxCard() di bawah), template di
    // sini CUMA mengecek `c.onClick` (0 logic navigasi baru, 0 percabangan
    // per-index, JANGAN openCard(index)).
    el.innerHTML = cards.map((c) => `
      <div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // _money(n) — reuse fmt() (format-tema.js, SUDAH ADA & dipakai
  // FinanceDashboard/VehicleDashboard) apa adanya, dgn fallback yang sama
  // persis polanya kalau fmt belum dimuat (guard typeof, pola sama persis
  // FinanceDashboard._netWorthCard()).
  _money(n) {
    return (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
  },

  // _totalCard(s) — s = VehicleCostSummary.summary() apa adanya (total
  // biaya BBM+servis gabungan N bulan terakhir — 0 recompute di sini).
  _totalCard(s) {
    return {
      icon: '💰',
      label: `Total Biaya Kendaraan (${s.months} Bulan)`,
      value: this._money(s.total),
      cls: '',
      sub: `Rata-rata ${this._money(s.avgPerMonth)}/bulan`,
      onClick: { action: 'dashHubNavigateToFeature', args: [VEHICLE_ANALYTICS_NAV_TARGETS.total] },
    };
  },

  // _fuelCard(s) — s.totalFuel dari VehicleCostSummary.summary() apa
  // adanya (breakdown SUM D.bbmLogs[].cost via VehicleTrendAPI — 0
  // recompute di sini).
  _fuelCard(s) {
    return {
      icon: '⛽',
      label: 'Total Biaya BBM',
      value: this._money(s.totalFuel),
      cls: '',
      onClick: { action: 'dashHubNavigateToFeature', args: [VEHICLE_ANALYTICS_NAV_TARGETS.fuel] },
    };
  },

  // _serviceCard(s) — s.totalService dari VehicleCostSummary.summary()
  // apa adanya (breakdown SUM D.servisLogs[].cost via VehicleTrendAPI —
  // 0 recompute di sini).
  _serviceCard(s) {
    return {
      icon: '🔧',
      label: 'Total Biaya Servis',
      value: this._money(s.totalService),
      cls: '',
      onClick: { action: 'dashHubNavigateToFeature', args: [VEHICLE_ANALYTICS_NAV_TARGETS.service] },
    };
  },

  // _trendCard(s) — s.direction/lastMonth/prevMonth dari VehicleCostSummary
  // .summary() apa adanya (perbandingan 2 bulan terakhir yang sudah
  // dihitung di sana — 0 recompute di sini).
  _trendCard(s) {
    const label = s.direction === 'up' ? 'Naik' : s.direction === 'down' ? 'Turun' : 'Tetap';
    const icon = s.direction === 'up' ? '📈' : s.direction === 'down' ? '📉' : '➖';
    const cls = s.direction === 'up' ? 'red' : s.direction === 'down' ? 'green' : '';
    const sub = (s.lastMonth && s.prevMonth)
      ? `${s.lastMonth.label}: ${this._money(s.lastMonth.total)} vs ${s.prevMonth.label}: ${this._money(s.prevMonth.total)}`
      : undefined;
    return {
      icon,
      label: 'Tren Biaya Bulan Terakhir',
      value: label,
      cls,
      sub,
      onClick: { action: 'dashHubNavigateToFeature', args: [VEHICLE_ANALYTICS_NAV_TARGETS.trend] },
    };
  },

};

// fuel-storage.js — Fuel Storage (TASK-141, Fuel Intelligence Card).
//
// PRINSIP: 100% REUSE D.bbmLogs (data mentah yang SUDAH ADA, diisi
// tx-bbm.js/car-notes.js BBM._saveInner/recordBbmLog) — TIDAK ada field
// baru ditambahkan ke D, TIDAK ada penyimpanan/state baru. Satu-satunya
// hal baru di sini adalah lapisan AKSES (query helper: filter per
// kendaraan, urut terbaru, ambil N terakhir) supaya FuelIntelligenceEngine/
// FuelHistory tidak menulis ulang `D.bbmLogs.filter(...)` masing-masing
// (pola sama seperti *-api.js lain di project ini yang jadi lapisan data
// tipis di atas D). PURE (read-only) — tidak pernah memanggil save() atau
// menulis ke D/localStorage.
const FuelStorage = {

// logs(vehicleId?) — semua log BBM (D.bbmLogs apa adanya), difilter ke 1
// kendaraan kalau vehicleId diberikan. Array kosong kalau D/D.bbmLogs
// belum ada (guard typeof, pola sama persis _vehicles() di VehicleIntelligence/
// VehicleReminder/VehicleTrendAPI).
logs(vehicleId) {
  const all = (typeof D !== 'undefined' && D.bbmLogs) ? D.bbmLogs : [];
  return vehicleId ? all.filter((b) => b.vehicleId === vehicleId) : all.slice();
},

// sortedByDate(vehicleId?) — logs() diurutkan tanggal terbaru dulu (desc).
// Tidak mengubah array asli (slice sebelum sort).
sortedByDate(vehicleId) {
  return this.logs(vehicleId).slice().sort((a, b) => (a.date < b.date ? 1 : (a.date > b.date ? -1 : 0)));
},

// latest(vehicleId?) — 1 log BBM terbaru (atau null kalau belum ada).
latest(vehicleId) {
  const rows = this.sortedByDate(vehicleId);
  return rows.length ? rows[0] : null;
},

// recent(vehicleId?, n=10) — N log BBM terbaru, urut terbaru dulu.
recent(vehicleId, n = 10) {
  return this.sortedByDate(vehicleId).slice(0, n);
},

// count(vehicleId?) — jumlah log BBM.
count(vehicleId) {
  return this.logs(vehicleId).length;
},

};

// fuel-tank-profile.js — Fuel Tank Profile (TASK-142).
//
// PRINSIP: field baru & OPSIONAL di D.vehicles[i].fuelTankProfile (ADDITIVE
// — kendaraan lama tanpa field ini tetap jalan normal, get() balikin
// DEFAULTS penuh). TIDAK ada storage baru di luar D.vehicles (pola sama
// persis `intervalOverrides` di vehicle-core.js — object config kecil
// nempel di record kendaraan yang sudah ada, BUKAN koleksi terpisah).
// TIDAK menyentuh vehicle-core.js (CRUD kendaraan/saveVehicle() apa
// adanya, 0 baris diubah) — modul ini murni domain fuel, baca/tulis 1
// field baru lewat API sendiri (get/validate/save), dipanggil dari
// UI fuel-* (mis. form pengaturan tangki di FuelModal, sesi mendatang)
// bukan dari form kendaraan umum. PURE kecuali save() (satu-satunya
// method yang menulis ke D & panggil save() global, sama seperti
// saveVehicle()/recordBbmLog() di file lain project ini).
const FuelTankProfile = {

// DEFAULTS — dipakai get() buat isi field yang belum pernah diisi user
// (kendaraan lama / kendaraan baru yang belum diatur profil tangkinya).
DEFAULTS: {
  tankCapacityLiter: null,
  fuelBarCount: 8,
  reserveLiter: 0,
  tankShape: 'linear',
  calibrationCurve: [],
  defaultFuelType: null,
},

VALID_TANK_SHAPES: ['linear', 'nonLinear'],

// _vehicles() — baca D.vehicles apa adanya, pola sama persis _vehicles()
// di VehicleIntelligence/VehicleReminder/FuelIntelligenceEngine.
_vehicles() {
  return (typeof D !== 'undefined' && D.vehicles) ? D.vehicles : [];
},

// get(vehicleId) — profil tangki 1 kendaraan, DEFAULTS digabung dgn
// field yang sudah diisi user (Object.assign dangkal — field individual
// yang belum diisi tetap dapat default, bukan seluruh objek jadi default
// kalau ADA field lain yang sudah diisi). null kalau kendaraan tidak
// ditemukan (bukan {} — biar caller bisa bedakan "tidak ada kendaraan"
// dari "kendaraan ada, profil masih default").
get(vehicleId) {
  const veh = this._vehicles().find((v) => v.id === vehicleId);
  if (!veh) return null;
  return Object.assign({}, this.DEFAULTS, veh.fuelTankProfile || {});
},

// validate(profile) — validasi PARTIAL (tiap field opsional & independen,
// biar mendukung update sebagian field lewat save() tanpa harus kirim
// semua field tiap kali) — {valid, errors[]}. errors dalam Bahasa
// Indonesia (pola sama persis pesan toast/error lain di project ini).
validate(profile) {
  const errors = [];
  if (!profile || typeof profile !== 'object' || Array.isArray(profile)) {
    return { valid: false, errors: ['Data profil tangki tidak valid'] };
  }
  if (profile.tankCapacityLiter !== undefined && profile.tankCapacityLiter !== null) {
    if (typeof profile.tankCapacityLiter !== 'number' || !isFinite(profile.tankCapacityLiter) || profile.tankCapacityLiter <= 0) {
      errors.push('Kapasitas tangki (liter) harus angka lebih besar dari 0');
    }
  }
  if (profile.fuelBarCount !== undefined && profile.fuelBarCount !== null) {
    if (!Number.isInteger(profile.fuelBarCount) || profile.fuelBarCount < 1) {
      errors.push('Jumlah bar indikator BBM harus bilangan bulat minimal 1');
    }
  }
  if (profile.reserveLiter !== undefined && profile.reserveLiter !== null) {
    if (typeof profile.reserveLiter !== 'number' || !isFinite(profile.reserveLiter) || profile.reserveLiter < 0) {
      errors.push('Cadangan tangki (reserve liter) harus angka 0 atau lebih');
    } else if (typeof profile.tankCapacityLiter === 'number' && profile.tankCapacityLiter > 0 && profile.reserveLiter > profile.tankCapacityLiter) {
      errors.push('Cadangan tangki tidak boleh lebih besar dari kapasitas tangki');
    }
  }
  if (profile.tankShape !== undefined && profile.tankShape !== null) {
    if (this.VALID_TANK_SHAPES.indexOf(profile.tankShape) === -1) {
      errors.push('Bentuk tangki harus "linear" atau "nonLinear"');
    }
  }
  if (profile.calibrationCurve !== undefined && profile.calibrationCurve !== null) {
    if (!Array.isArray(profile.calibrationCurve)) {
      errors.push('Kurva kalibrasi harus berupa array titik {liter, percent}');
    } else {
      const badPoint = profile.calibrationCurve.some((p) => (
        !p || typeof p !== 'object'
        || typeof p.liter !== 'number' || !isFinite(p.liter) || p.liter < 0
        || typeof p.percent !== 'number' || !isFinite(p.percent) || p.percent < 0 || p.percent > 100
      ));
      if (badPoint) errors.push('Setiap titik kurva kalibrasi harus {liter:angka>=0, percent:0-100}');
    }
  }
  // tankShape nonLinear butuh kurva kalibrasi (linear cukup asumsi liter
  // proporsional lurus ke tinggi/bar, tidak butuh titik kalibrasi).
  const effectiveShape = profile.tankShape !== undefined ? profile.tankShape : undefined;
  if (effectiveShape === 'nonLinear') {
    const curve = profile.calibrationCurve;
    if (!Array.isArray(curve) || curve.length < 1) {
      errors.push('Bentuk tangki "nonLinear" butuh minimal 1 titik kurva kalibrasi');
    }
  }
  if (profile.defaultFuelType !== undefined && profile.defaultFuelType !== null) {
    if (typeof profile.defaultFuelType !== 'string' || !profile.defaultFuelType.trim()) {
      errors.push('Jenis BBM default harus teks, tidak boleh kosong');
    }
  }
  return { valid: errors.length === 0, errors };
},

// save(vehicleId, profileData) — merge profileData ke profil yang sudah
// ada (partial update, field yang tidak dikirim tetap dipertahankan),
// validasi HASIL gabungan (bukan cuma profileData mentah — supaya
// kombinasi lama+baru tetap konsisten, mis. reserveLiter lama vs
// tankCapacityLiter baru), baru tulis ke D & panggil save() (SUDAH ADA,
// pola sama persis saveVehicle()/recordBbmLog()). {ok:false, errors}
// kalau invalid ATAU kendaraan tidak ditemukan — TIDAK menulis apa pun
// ke D dalam kondisi manapun selain sukses penuh.
save(vehicleId, profileData) {
  const veh = this._vehicles().find((v) => v.id === vehicleId);
  if (!veh) return { ok: false, errors: ['Kendaraan tidak ditemukan'] };
  const merged = Object.assign({}, veh.fuelTankProfile || {}, profileData || {});
  const result = this.validate(merged);
  if (!result.valid) return { ok: false, errors: result.errors };
  veh.fuelTankProfile = merged;
  if (typeof save === 'function') save();
  return { ok: true, profile: Object.assign({}, this.DEFAULTS, merged) };
},

};

// fuel-intelligence-engine.js — Fuel Engine (TASK-141, Fuel Intelligence
// Card).
//
// PRINSIP: 100% REUSE service yang SUDAH ADA — TIDAK ada rumus
// kmPerLiter/rpPerKm/estMonthlyCost baru (fuelEfficiency(), vehicle-core.js),
// TIDAK menghitung ulang tren biaya bulanan (VehicleFuelTrendSummary,
// sendiri 100% reuse VehicleTrendAPI), TIDAK menghitung ulang ambang
// pengingat isi BBM (VehicleReminder.fuelReminders()). Satu-satunya hal
// baru di sini adalah MENGGABUNGKAN ketiganya + FuelStorage jadi satu
// objek insight per kendaraan/armada, dipakai FuelCard/FuelModal/
// FuelAnalytics — pola sama persis VehicleFuelTrendSummary yang juga
// cuma menggabungkan tanpa recompute. PURE (read-only) — tidak pernah
// memanggil save() atau menyentuh DOM.
//
// TASK-142 (Fuel Tank Profile): tambah field `tankProfile` (opsional,
// guard typeof) ke vehicleInsight() — 100% REUSE FuelTankProfile.get(),
// 0 rumus baru di sini, 0 field lama diubah/dihapus.
const FuelIntelligenceEngine = {

// _vehicles() — baca D.vehicles apa adanya (array kosong kalau belum
// ada), pola sama persis _vehicles() di VehicleIntelligence/VehicleReminder.
_vehicles() {
  return (typeof D !== 'undefined' && D.vehicles) ? D.vehicles : [];
},

// vehicleInsight(vehicleId) — gabungan tren biaya BBM (VehicleFuelTrendSummary,
// termasuk efisiensi saat ini via fuelEfficiency() apa adanya) + pengingat
// isi BBM (VehicleReminder.fuelReminders()) + jumlah log (FuelStorage) +
// profil tangki (FuelTankProfile.get(), TASK-142) utk 1 kendaraan.
// {ok:false} kalau kendaraan tidak ditemukan (pola sama persis
// vehicleOverview()/vehicleInsight() lain di project ini).
vehicleInsight(vehicleId) {
  const veh = this._vehicles().find((v) => v.id === vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  const trend = (typeof VehicleFuelTrendSummary !== 'undefined')
    ? VehicleFuelTrendSummary.summary(vehicleId)
    : { ok: false, reason: 'VehicleFuelTrendSummary belum dimuat' };
  const reminders = (typeof VehicleReminder !== 'undefined')
    ? VehicleReminder.fuelReminders(vehicleId)
    : [];
  const logCount = (typeof FuelStorage !== 'undefined') ? FuelStorage.count(vehicleId) : 0;
  // tankProfile: opsional (TASK-142) — null kalau FuelTankProfile belum
  // dimuat, 0 dampak ke konsumen lama (field baru, murni additive).
  const tankProfile = (typeof FuelTankProfile !== 'undefined') ? FuelTankProfile.get(vehicleId) : null;
  return {
    ok: true,
    vehicleId,
    name: veh.name,
    emoji: veh.emoji,
    current: trend.ok ? trend.current : null,
    trend: trend.ok ? { months: trend.months, rows: trend.rows, total: trend.total } : null,
    reminders,
    logCount,
    tankProfile,
  };
},

// fleetInsight() — agregasi ringan lintas SEMUA D.vehicles: total biaya
// BBM (SUM trend.total tiap kendaraan, sendiri dari VehicleTrendAPI apa
// adanya), rata-rata km/L kendaraan yang datanya cukup, jumlah pengingat
// overdue/due-soon. 0 rumus baru — murni SUM/rata-rata dari vehicleInsight()
// di atas, pola sama persis fleetSummary() di VehicleIntelligence.
fleetInsight() {
  const rows = this._vehicles().map((v) => this.vehicleInsight(v.id)).filter((r) => r.ok);
  const allReminders = rows.reduce((acc, r) => acc.concat(r.reminders), []);
  const withEfficiency = rows.filter((r) => r.current && r.current.ok);
  const avgKmPerLiter = withEfficiency.length
    ? withEfficiency.reduce((s, r) => s + r.current.kmPerLiter, 0) / withEfficiency.length
    : null;
  const totalFuelCost = rows.reduce((s, r) => s + (r.trend ? r.trend.total : 0), 0);
  return {
    totalVehicles: rows.length,
    overdueCount: allReminders.filter((r) => r.severity === 'overdue').length,
    dueSoonCount: allReminders.filter((r) => r.severity === 'due-soon').length,
    avgKmPerLiter,
    totalFuelCost,
    rows,
  };
},

};

// fuel-gauge-engine.js — Fuel Gauge Engine (TASK-143).
//
// PRINSIP: 100% REUSE FuelTankProfile.get() (TASK-142, kalibrasi tangki per
// kendaraan) + fuelEfficiency() global (vehicle-core.js, SUDAH ADA, dipakai
// VehicleFuelTrendSummary/FuelIntelligenceEngine) utk kmPerLiter. TIDAK ada
// storage baru, TIDAK menyentuh fuel-tank-profile.js/vehicle-core.js, TIDAK
// ada UI. PURE (read-only, tidak pernah panggil save()) & DETERMINISTIK —
// input+profil sama selalu balikin output sama persis (tidak ada Date.now(),
// Math.random(), atau state mutable tersimpan di objek ini).
//
// SINGLE SOURCE OF TRUTH: modul ini dimaksudkan jadi SATU-SATUNYA tempat
// rumus konversi bar↔liter↔persen/estimasi jangkauan/status reserve dihitung
// utk domain fuel gauge. Konsumen MASA DEPAN (FuelCard, FuelAnalytics, serta
// Fuel Prediction/Fuel Reality Check yang belum ada) WAJIB pakai
// FuelGaugeEngine.* alih-alih menghitung ulang sendiri — sesi ini TIDAK
// mengubah fuel-card.js/fuel-analytics.js (keduanya saat ini belum punya
// rumus bar/liter/persen apa pun, jadi tidak ada yang perlu diganti; lihat
// AI_STATE.md § Sesi 143 untuk catatan audit ini) — wiring itu jadi kerjaan
// sesi lain yang eksplisit memintanya (1 task = 1 sesi, sesuai AI_RULES.md).
//
// METADATA KALIBRASI (internal): helper interpolasi di bawah balikin objek
// {value, segmentIndex, source} secara internal supaya kalau nanti ada
// auto-kalibrasi (mis. mendeteksi titik kurva yang kurang akurat dari histori
// BBM), engine ini sudah punya jejak "titik interpolasi mana yang dipakai"
// tanpa perlu ubah API publik. Field ini SENGAJA tidak diteruskan ke hasil
// publik (_stripMeta() di bawah) — caller cuma butuh angka hasil akhir.
//
// EXTENSION POINT CONFIDENCE (belum diimplementasi): _confidence() di bawah
// adalah stub yang DISENGAJA belum dipanggil dari mana pun & selalu balikin
// null — reserved utk sesi masa depan yang eksplisit memintanya (skor
// keyakinan estimasi, mis. berdasarkan jumlah titik kalibrasi/histori BBM).
// TIDAK mengubah API publik saat ini.
const FuelGaugeEngine = {

// _profile(vehicleId) — ambil profil tangki (TASK-142) + guard umum yang
// dipakai semua method publik di bawah: FuelTankProfile belum dimuat,
// kendaraan tidak ditemukan, atau tankCapacityLiter belum diisi (semua
// perhitungan liter/bar/persen butuh kapasitas tangki > 0 sbg pembagi).
// {ok:false, reason} kalau salah satu guard gagal, {ok:true, data} kalau
// lolos (pola {ok,...} sama persis modul fuel-* lain di project ini).
_profile(vehicleId) {
  if (typeof FuelTankProfile === 'undefined') {
    return { ok: false, reason: 'FuelTankProfile belum dimuat' };
  }
  const data = FuelTankProfile.get(vehicleId);
  if (!data) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  if (typeof data.tankCapacityLiter !== 'number' || !isFinite(data.tankCapacityLiter) || data.tankCapacityLiter <= 0) {
    return { ok: false, reason: 'Kapasitas tangki belum diatur (isi profil tangki dulu)' };
  }
  return { ok: true, data };
},

// _isValidNumber(n) — guard input angka umum (bukan number, NaN, Infinity
// ditolak). Dipakai semua method publik sebelum clamp, biar pesan error
// invalid-input konsisten satu tempat.
_isValidNumber(n) {
  return typeof n === 'number' && isFinite(n);
},

// _clamp(n, min, max) — batasi n ke rentang [min, max]. Dipakai buat
// requirement #8 (clamp semua nilai) di semua method publik.
_clamp(n, min, max) {
  return Math.min(Math.max(n, min), max);
},

// _curvePoints(profile) — titik kalibrasi nonLinear DIGABUNG dgn 2 jangkar
// fisik yang selalu berlaku apa pun bentuk tangki: liter 0 = 0% (kosong),
// liter tankCapacityLiter = 100% (penuh). Titik user (profile.calibrationCurve)
// menimpa jangkar kalau kebetulan liter-nya sama (mis. user isi titik di
// liter 0). Diurutkan menaik berdasarkan liter — dipakai _percentFromLiter().
// CATATAN: kurva diasumsikan monoton (liter naik -> persen naik), sama
// seperti validate() TASK-142 yang tidak memaksa monotonicity — GIGO by
// design, konsisten dgn modul fuel-* lain yang percaya data profil apa
// adanya.
_curvePoints(profile) {
  const map = new Map();
  map.set(0, 0);
  map.set(profile.tankCapacityLiter, 100);
  (profile.calibrationCurve || []).forEach((p) => map.set(p.liter, p.percent));
  return Array.from(map.entries())
    .map(([liter, percent]) => ({ liter, percent }))
    .sort((a, b) => a.liter - b.liter);
},

// _interpolate(points, x, xKey, yKey, segmentSource) — interpolasi linear
// piecewise generik: cari 2 titik yang mengapit x di sumbu xKey, balikin y
// di sumbu yKey secara proporsional. Balikin {value, segmentIndex, source}
// (metadata internal utk auto-kalibrasi masa depan, lihat catatan header —
// TIDAK diteruskan ke caller publik). x diasumsikan sudah di-clamp ke
// rentang titik oleh pemanggil, jadi loop selalu ketemu bracket (fallback
// titik terakhir kalau tidak, cuma jaga-jaga floating point).
_interpolate(points, x, xKey, yKey, segmentSource) {
  for (let i = 0; i < points.length - 1; i++) {
    const a = points[i];
    const b = points[i + 1];
    if (x >= a[xKey] && x <= b[xKey]) {
      const span = b[xKey] - a[xKey];
      const value = span === 0 ? a[yKey] : a[yKey] + ((x - a[xKey]) / span) * (b[yKey] - a[yKey]);
      return { value, segmentIndex: i, source: segmentSource };
    }
  }
  const last = points[points.length - 1];
  return { value: last[yKey], segmentIndex: points.length - 2, source: segmentSource };
},

// _percentFromLiter(profile, liter) — liter (SUDAH di-clamp pemanggil ke
// [0, tankCapacityLiter]) -> persen 0-100. Tangki 'linear' (atau nonLinear
// tanpa titik kalibrasi, seharusnya tidak kejadian krn validate() TASK-142
// mewajibkan >=1 titik) pakai rumus proporsional langsung (source
// 'linear-formula'). Tangki 'nonLinear' interpolasi lewat _curvePoints()
// (source 'calibration-curve'). Balikin {value, segmentIndex, source}
// (metadata internal, lihat _interpolate()).
_percentFromLiter(profile, liter) {
  if (profile.tankShape !== 'nonLinear' || !profile.calibrationCurve || !profile.calibrationCurve.length) {
    return { value: (liter / profile.tankCapacityLiter) * 100, segmentIndex: null, source: 'linear-formula' };
  }
  return this._interpolate(this._curvePoints(profile), liter, 'liter', 'percent', 'calibration-curve');
},

// _literFromPercent(profile, percent) — kebalikan _percentFromLiter():
// persen (SUDAH di-clamp pemanggil ke [0,100]) -> liter. 'linear' pakai
// rumus proporsional langsung. 'nonLinear' interpolasi titik kalibrasi yang
// sama (diurutkan ulang berdasarkan persen, bukan liter, krn sumbu-x
// interpolasi kali ini persen).
_literFromPercent(profile, percent) {
  if (profile.tankShape !== 'nonLinear' || !profile.calibrationCurve || !profile.calibrationCurve.length) {
    return { value: (percent / 100) * profile.tankCapacityLiter, segmentIndex: null, source: 'linear-formula' };
  }
  const points = this._curvePoints(profile).slice().sort((a, b) => a.percent - b.percent);
  return this._interpolate(points, percent, 'percent', 'liter', 'calibration-curve');
},

// _confidence(profile, meta) — EXTENSION POINT, belum diimplementasi
// (requirement #3: reserved, tidak dipanggil dari mana pun sesi ini).
// Rencana masa depan: skor keyakinan estimasi dari jumlah titik kalibrasi/
// histori BBM tersedia. Sengaja selalu balikin null sekarang — TIDAK
// mengubah API publik.
_confidence(profile, meta) {
  return null;
},

// calculateFuelLiter(vehicleId, fuelBar) — konversi bar indikator BBM ->
// liter, sesuai profil kalibrasi tangki kendaraan (TASK-142, linear/nonLinear).
// Parameter:
//   vehicleId (string) — id kendaraan.
//   fuelBar (number) — posisi bar indikator saat ini (0..fuelBarCount).
// Return: {ok:true, vehicleId, liter, clamped} kalau sukses — liter
//   dibulatkan 2 desimal. {ok:false, reason} kalau: FuelTankProfile belum
//   dimuat, kendaraan tidak ditemukan, tankCapacityLiter belum diatur, atau
//   fuelBar bukan angka valid (NaN/Infinity/bukan number).
// Clamping: fuelBar DI-CLAMP ke [0, fuelBarCount] SEBELUM dihitung (bukan
//   ditolak) — `clamped:true` menandakan input asli di luar rentang & sudah
//   dibatasi.
calculateFuelLiter(vehicleId, fuelBar) {
  const profile = this._profile(vehicleId);
  if (!profile.ok) return profile;
  if (!this._isValidNumber(fuelBar)) return { ok: false, reason: 'Nilai bar BBM tidak valid' };
  const barCount = profile.data.fuelBarCount;
  const clampedBar = this._clamp(fuelBar, 0, barCount);
  const percent = this._clamp((clampedBar / barCount) * 100, 0, 100);
  const literMeta = this._literFromPercent(profile.data, percent);
  const liter = Math.round(this._clamp(literMeta.value, 0, profile.data.tankCapacityLiter) * 100) / 100;
  return { ok: true, vehicleId, liter, clamped: clampedBar !== fuelBar };
},

// calculateFuelBar(vehicleId, liter) — konversi liter -> posisi bar
// indikator BBM, sesuai profil kalibrasi tangki kendaraan.
// Parameter:
//   vehicleId (string) — id kendaraan.
//   liter (number) — jumlah BBM saat ini dalam liter.
// Return: {ok:true, vehicleId, bar, clamped} kalau sukses — bar dibulatkan
//   2 desimal. {ok:false, reason} kalau: profil tidak tersedia (lihat
//   _profile()) atau liter bukan angka valid.
// Clamping: liter DI-CLAMP ke [0, tankCapacityLiter] SEBELUM dihitung;
//   hasil bar juga DI-CLAMP ke [0, fuelBarCount] (jaga-jaga floating point).
//   `clamped:true` kalau liter asli di luar rentang tangki.
calculateFuelBar(vehicleId, liter) {
  const profile = this._profile(vehicleId);
  if (!profile.ok) return profile;
  if (!this._isValidNumber(liter)) return { ok: false, reason: 'Nilai liter tidak valid' };
  const cap = profile.data.tankCapacityLiter;
  const clampedLiter = this._clamp(liter, 0, cap);
  const percentMeta = this._percentFromLiter(profile.data, clampedLiter);
  const barRaw = (this._clamp(percentMeta.value, 0, 100) / 100) * profile.data.fuelBarCount;
  const bar = Math.round(this._clamp(barRaw, 0, profile.data.fuelBarCount) * 100) / 100;
  return { ok: true, vehicleId, bar, clamped: clampedLiter !== liter };
},

// calculateFuelPercent(vehicleId, liter) — konversi liter -> persentase
// BBM 0-100, sesuai profil kalibrasi tangki kendaraan.
// Parameter:
//   vehicleId (string) — id kendaraan.
//   liter (number) — jumlah BBM saat ini dalam liter.
// Return: {ok:true, vehicleId, percent, clamped} kalau sukses — percent
//   bilangan bulat 0-100 (Math.round). {ok:false, reason} kalau: profil
//   tidak tersedia atau liter bukan angka valid.
// Clamping: liter DI-CLAMP ke [0, tankCapacityLiter] SEBELUM dihitung;
//   percent hasil DI-CLAMP ke [0,100]. `clamped:true` kalau liter asli di
//   luar rentang tangki.
calculateFuelPercent(vehicleId, liter) {
  const profile = this._profile(vehicleId);
  if (!profile.ok) return profile;
  if (!this._isValidNumber(liter)) return { ok: false, reason: 'Nilai liter tidak valid' };
  const cap = profile.data.tankCapacityLiter;
  const clampedLiter = this._clamp(liter, 0, cap);
  const percentMeta = this._percentFromLiter(profile.data, clampedLiter);
  const percent = Math.round(this._clamp(percentMeta.value, 0, 100));
  return { ok: true, vehicleId, percent, clamped: clampedLiter !== liter };
},

// estimateRemainingDistance(vehicleId, liter) — estimasi jarak tempuh
// tersisa (km) dari sisa BBM saat ini, 100% REUSE fuelEfficiency() global
// (vehicle-core.js — SUDAH ADA, 0 rumus km/L baru dihitung di sini).
// Parameter:
//   vehicleId (string) — id kendaraan.
//   liter (number) — jumlah BBM saat ini dalam liter (dihitung dari SISA
//     seluruh tangki, TIDAK dikurangi reserve — pakai getReserveStatus()
//     terpisah kalau butuh tahu status reserve).
// Return: {ok:true, vehicleId, km, kmPerLiter, clamped} kalau sukses — km
//   dibulatkan (Math.round). {ok:false, reason} kalau: profil tidak
//   tersedia, liter bukan angka valid, fuelEfficiency() belum dimuat, atau
//   data efisiensi BBM kendaraan belum cukup (reason dari fuelEfficiency()
//   diteruskan apa adanya).
// Clamping: liter DI-CLAMP ke [0, tankCapacityLiter] SEBELUM dihitung.
//   `clamped:true` kalau liter asli di luar rentang tangki.
estimateRemainingDistance(vehicleId, liter) {
  const profile = this._profile(vehicleId);
  if (!profile.ok) return profile;
  if (!this._isValidNumber(liter)) return { ok: false, reason: 'Nilai liter tidak valid' };
  if (typeof fuelEfficiency !== 'function') return { ok: false, reason: 'fuelEfficiency belum dimuat' };
  const eff = fuelEfficiency(vehicleId);
  if (!eff.ok) return { ok: false, reason: eff.reason || 'Data efisiensi BBM belum cukup' };
  const cap = profile.data.tankCapacityLiter;
  const clampedLiter = this._clamp(liter, 0, cap);
  const km = Math.round(clampedLiter * eff.kmPerLiter);
  return { ok: true, vehicleId, km, kmPerLiter: eff.kmPerLiter, clamped: clampedLiter !== liter };
},

// getReserveStatus(vehicleId, liter) — status cadangan (reserve) BBM saat
// ini, dari reserveLiter profil tangki (TASK-142, default 0 kalau belum
// diatur).
// Parameter:
//   vehicleId (string) — id kendaraan.
//   liter (number) — jumlah BBM saat ini dalam liter.
// Return: {ok:true, vehicleId, inReserve, reserveLiter, literAboveReserve,
//   clamped} kalau sukses. inReserve true kalau liter <= reserveLiter.
//   literAboveReserve (liter di atas ambang reserve, minimal 0, dibulatkan
//   2 desimal). {ok:false, reason} kalau profil tidak tersedia atau liter
//   bukan angka valid.
// Clamping: liter DI-CLAMP ke [0, tankCapacityLiter] SEBELUM dihitung.
//   `clamped:true` kalau liter asli di luar rentang tangki.
getReserveStatus(vehicleId, liter) {
  const profile = this._profile(vehicleId);
  if (!profile.ok) return profile;
  if (!this._isValidNumber(liter)) return { ok: false, reason: 'Nilai liter tidak valid' };
  const cap = profile.data.tankCapacityLiter;
  const reserve = profile.data.reserveLiter || 0;
  const clampedLiter = this._clamp(liter, 0, cap);
  const inReserve = clampedLiter <= reserve;
  const literAboveReserve = Math.round(Math.max(clampedLiter - reserve, 0) * 100) / 100;
  return {
    ok: true,
    vehicleId,
    inReserve,
    reserveLiter: reserve,
    literAboveReserve,
    clamped: clampedLiter !== liter,
  };
},

};

// fuel-history.js — Fuel History (TASK-141, Fuel Intelligence Card).
//
// PRINSIP: UI HANYA presenter. 100% REUSE FuelStorage.recent() (sesi ini
// — sendiri 100% reuse D.bbmLogs apa adanya) utk daftar catatan isi BBM
// terbaru. Tap 1 baris membuka bbmModal (BBM.openModal(), car-notes.js,
// SUDAH ADA) utk lihat/edit detail — TIDAK ada form/CRUD baru di sini,
// murni daftar ringkas. Markup reuse class tx-item/tx-icon/tx-info/
// tx-name/tx-meta/tx-amount (SUDAH ADA, dipakai BBM.renderList() sendiri)
// apa adanya — 0 class CSS baru.
const FuelHistory = {

// render(vehicleId) — isi #fuelIntelHistoryList dengan sampai 8 catatan
// BBM terbaru kendaraan ini. Silent (kosongkan diam-diam) kalau container
// belum ada di halaman (pola sama persis presenter lain di project ini).
render(vehicleId) {
  const el = document.getElementById('fuelIntelHistoryList');
  if (!el) return;
  if (typeof FuelStorage === 'undefined') { el.innerHTML = ''; return; }
  const rows = FuelStorage.recent(vehicleId, 8);
  if (!rows.length) {
    el.innerHTML = '<div class="empty"><div class="empty-text">Belum ada catatan BBM</div></div>';
    return;
  }
  el.innerHTML = rows.map((b) => this._row(b)).join('');
},

// _row(b) — 1 baris riwayat, format & data-action SAMA PERSIS baris
// BBM.renderList() (car-notes.js) supaya tap-nya membuka modal edit yang
// sama, cuma daftarnya lebih ringkas (8 terbaru, tanpa pagination/hapus
// inline — hapus/edit didelegasikan ke bbmModal yang terbuka).
_row(b) {
  const money = (typeof fmt === 'function') ? fmt(b.cost) : ('Rp ' + Math.round(b.cost || 0));
  const km = (b.km != null) ? b.km.toLocaleString('id-ID') + ' km' : '(km tidak dicatat)';
  return `<div class="tx-item u-pointer" data-action="openBbmModal" data-args="${escapeHtml(JSON.stringify([b.id]))}">
    <div class="tx-icon" style="background:var(--accent4-soft)">⛽</div>
    <div class="tx-info"><div class="tx-name">${km} · ${b.liter}L</div><div class="tx-meta">${escapeHtml(b.date)}${b.spbu ? ' · ' + escapeHtml(b.spbu) : ''}${b.fullTank ? ' · Full Tank' : ' · Isi sebagian'}</div></div>
    <div class="tx-amount red">${money}</div>
  </div>`;
},

};

// fuel-analytics.js — Fuel Analytics (TASK-141, Fuel Intelligence Card).
//
// PRINSIP: UI HANYA presenter. 100% REUSE VehicleFuelTrendSummary.summary()
// (Sesi 81, Batch 7 — sendiri 100% reuse VehicleTrendAPI.monthlyCostTrend()
// utk histori biaya BBM per bulan + VehicleIntelligence.vehicleOverview().fuel
// utk efisiensi saat ini) via FuelIntelligenceEngine.vehicleInsight() (sesi
// ini) — TIDAK ada rumus SUM/rata-rata/kmPerLiter/rpPerKm baru di sini.
// Bar chart digambar dgn div width% sederhana (bukan SVG BBM.svgCostBar()
// punya car-notes.js, yg formatnya beda/khusus form tambah-BBM) — murni
// tampilan, 0 data baru dihitung.
//
// FUEL_ANALYTICS_NAV_TARGETS (Sesi 253 — Batch Vehicle Navigation
// Consistency) — tujuan navigasi ketiga kartu findash-card di _effBlock().
// MURNI DATA (0 logic navigasi baru), format {page,tab,subtab,goTo} SAMA
// PERSIS format target dashHubNavigateToFeature() yang SUDAH ADA
// (dashboard-hub.js). Nama disendirikan per-file supaya tidak bentrok dgn
// const global lain (lihat kasus S251). Ketiganya (efisiensi/biaya-km/
// estimasi-bulan) sama-sama soal BBM kendaraan ini -> Kendaraan > tab BBM >
// bbmList (SAMA PERSIS target 'cn-bbm' di dashboard-hub-registry.js,
// TERVERIFIKASI ADA di index.html/app_production.html).
const FUEL_ANALYTICS_NAV_TARGETS = Object.freeze({
  efficiency: { page: 'carnotes', tab: 'bbm', subtab: 'ringkasan', goTo: 'bbmList' },
  costPerKm: { page: 'carnotes', tab: 'bbm', subtab: 'ringkasan', goTo: 'bbmList' },
  monthlyEst: { page: 'carnotes', tab: 'bbm', subtab: 'ringkasan', goTo: 'bbmList' },
});

const FuelAnalytics = {

// render(vehicleId) — isi #fuelIntelAnalyticsBody dgn ringkasan efisiensi
// saat ini (km/L, Rp/km, estimasi biaya bulanan) + bar tren biaya BBM N
// bulan terakhir. Silent (kosongkan diam-diam) kalau container belum ada.
render(vehicleId) {
  const el = document.getElementById('fuelIntelAnalyticsBody');
  if (!el) return;
  if (typeof FuelIntelligenceEngine === 'undefined') { el.innerHTML = ''; return; }
  const insight = FuelIntelligenceEngine.vehicleInsight(vehicleId);
  if (!insight.ok) {
    el.innerHTML = '<div class="empty"><div class="empty-text">Data kendaraan tidak ditemukan</div></div>';
    return;
  }
  el.innerHTML = this._effBlock(insight.current) + this._trendBlock(insight.trend);
},

_money(n) {
  return (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
},

// _effBlock(current) — current = trend.current dari VehicleFuelTrendSummary
// apa adanya (hasil fuelEfficiency() via VehicleIntelligence, 0 recompute).
// S253 (Batch Vehicle Navigation Consistency): ketiga findash-card di sini
// clickable lewat pola SAMA PERSIS presenter lain (VehicleDashboard dst) —
// c.onClick -> u-pointer -> data-action -> data-args, JANGAN openCard(index).
_effBlock(current) {
  if (!current || !current.ok) {
    return '<div class="u-fs12 u-t2" style="margin-bottom:12px">Data efisiensi BBM belum cukup (butuh min. 2 log "Isi Full Tank" dgn km naik).</div>';
  }
  const cards = [
    { icon: '⚡', label: 'Efisiensi', value: `${current.kmPerLiter.toFixed(1)} km/L`, onClick: { action: 'dashHubNavigateToFeature', args: [FUEL_ANALYTICS_NAV_TARGETS.efficiency] } },
    { icon: '💸', label: 'Biaya/KM', value: this._money(current.rpPerKm), onClick: { action: 'dashHubNavigateToFeature', args: [FUEL_ANALYTICS_NAV_TARGETS.costPerKm] } },
  ];
  if (current.estMonthlyCost) {
    cards.push({ icon: '📅', label: 'Estimasi/Bulan', value: this._money(current.estMonthlyCost), onClick: { action: 'dashHubNavigateToFeature', args: [FUEL_ANALYTICS_NAV_TARGETS.monthlyEst] } });
  }
  const cardsHtml = cards.map((c) => `<div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}><div class="findash-card-icon">${c.icon}</div><div class="findash-card-body"><div class="findash-card-label">${escapeHtml(c.label)}</div><div class="findash-card-val">${escapeHtml(c.value)}</div></div></div>`).join('');
  return `<div class="findash-grid" style="margin-bottom:12px">${cardsHtml}</div>`;
},

// _trendBlock(trend) — trend = {months, rows, total} dari VehicleFuelTrendSummary
// apa adanya (rows[].total dari VehicleTrendAPI.monthlyCostTrend(type:'fuel'),
// 0 recompute). Bar width% dihitung dari nilai yang sudah ada, bukan rumus baru.
_trendBlock(trend) {
  if (!trend || !trend.rows || !trend.rows.length) {
    return '<div class="u-fs12 u-t2">Belum ada histori biaya BBM.</div>';
  }
  const max = Math.max(...trend.rows.map((r) => r.total), 1);
  const bars = trend.rows.map((r) => `
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
      <div class="u-fs11 u-t2" style="width:56px;flex-shrink:0">${escapeHtml(r.label)}</div>
      <div style="flex:1;background:var(--surface3);border-radius:6px;overflow:hidden;height:16px">
        <div style="width:${Math.round((r.total / max) * 100)}%;height:100%;background:var(--accent4)"></div>
      </div>
      <div class="u-fs11" style="width:84px;flex-shrink:0;text-align:right">${this._money(r.total)}</div>
    </div>`).join('');
  return `<div class="u-fs12 u-t2" style="margin-bottom:8px">Tren Biaya BBM (${trend.months} Bulan Terakhir) — Total ${this._money(trend.total)}</div>${bars}`;
},

};

// fuel-modal.js — Fuel Modal (TASK-141, Fuel Intelligence Card).
//
// PRINSIP: orkestrasi TIPIS saja. Buka overlay #fuelIntelModal (markup di
// modals.js, sesi ini) & panggil FuelAnalytics.render()/FuelHistory.render()
// (sesi ini, keduanya 100% reuse FuelIntelligenceEngine/FuelStorage) utk
// isi bodinya. Reuse openModal()/closeModal() (SUDAH ADA, dipakai semua
// modal lain di project ini) apa adanya — TIDAK ada mekanisme modal baru.
const FuelModal = {

curVehicleId: null,

// open(vehicleId?) — vehicleId opsional, default curVehicleId (kendaraan
// aktif di tab Car Notes, SUDAH ADA — sama seperti default vehicleId di
// BBM.openModal()/txBbmVehicle). {ok:false} (toast, tidak jadi buka
// modal) kalau kendaraan tidak ditemukan.
open(vehicleId) {
  const vid = vehicleId || (typeof curVehicleId !== 'undefined' ? curVehicleId : null);
  if (typeof FuelIntelligenceEngine === 'undefined') return;
  const insight = FuelIntelligenceEngine.vehicleInsight(vid);
  if (!insight.ok) {
    if (typeof toast === 'function') toast('⚠️ Kendaraan tidak ditemukan');
    return;
  }
  this.curVehicleId = vid;
  const titleEl = document.getElementById('fuelIntelModalVeh');
  if (titleEl) titleEl.textContent = (insight.emoji ? insight.emoji + ' ' : '') + insight.name;
  if (typeof FuelAnalytics !== 'undefined') FuelAnalytics.render(vid);
  if (typeof FuelHistory !== 'undefined') FuelHistory.render(vid);
  if (typeof openModal === 'function') openModal('fuelIntelModal');
},

};

