// CrossAIHook.getAIHook() (modules/cross/cross-ai-hook.js, sesi ini) —
// TIDAK ada rumus baru, TIDAK menghitung ulang health score/fleet
// summary/reminder, TIDAK membaca D langsung sama sekali (pola sama
// persis VehicleDashboard/VehicleInsightPresenter — 0 pembacaan D
// tambahan, beda dari FinanceDashboard._netWorthCard()).
//
// Satu-satunya aritmatika di file ini adalah PENJUMLAHAN 2 counter yang
// SUDAH ADA (budget.overCount milik FinanceIntelligence.budgetSummary() +
// reminder.overdueCount milik VehicleReminder.summary(), keduanya dibaca
// APA ADANYA dari hook) utk kartu "Total Perhatian Gabungan" — pola sama
// persis VehicleReminder.summary() sendiri yg menjumlah overdueCount+
// dueSoonCount+infoCount jadi total; BUKAN rumus/skoring baru, murni
// penjumlahan counter existing lintas-domain.
//
// Dipanggil dari DashboardHub.render() & live-wiring renderDashboard()
// (modules/shared/modules-render.js), TIDAK ada mekanisme render baru —
// pola SAMA PERSIS VehicleDashboard.render()/FinanceDashboard.render().
//
// CSS: TIDAK ada class baru — reuse penuh .findash-grid/.findash-card*
// (styles.css, Sesi 75) apa adanya.
const CrossDashboardCard = {

  render() {
    const el = document.getElementById('crossDashGrid');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    if (typeof CrossAIHook === 'undefined') {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data cross summary belum tersedia</div></div>';
      return;
    }
    const hook = CrossAIHook.getAIHook();
    if (!hook.ok) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data cross summary belum tersedia</div></div>';
      return;
    }

    // FIX DEDUP (lihat DASHBOARD-DEDUP.md § CrossDashboardCard): kartu
    // "Skor Kesehatan Finansial" & "Skor Kesehatan Armada" DIHAPUS dari
    // output di sini — keduanya 100% duplikat dengan kartu yang SUDAH
    // tampil di FinanceDashboard (tab Keuangan, #findashWrap) &
    // VehicleDashboard (tab Car Notes, #vehdashWrap), yang membaca sumber
    // data PERSIS SAMA (FinanceIntelligence.healthScore()/
    // VehicleIntelligence.fleetSummary() lewat CrossAIHook.getAIHook()).
    // _financeHealthCard()/_vehicleHealthCard() TETAP ada di bawah (tidak
    // dihapus, biar tidak ada breaking change kalau ada pemanggil lain di
    // masa depan) — cuma tidak lagi dipanggil dari render(). Yang tersisa
    // di tab Insight cuma "Total Perhatian Gabungan", satu-satunya angka
    // di kartu ini yang memang BELUM ada di kartu manapun (gabungan
    // budget lewat batas + servis/pajak/BBM lewat jatuh tempo).
    const cards = [
      this._combinedAttentionCard(hook.finance, hook.vehicle),
    ];

    el.innerHTML = cards.map((c) => `
      <div class="findash-card">
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // _financeHealthCard(finance) — finance = CrossAIHook.getAIHook().finance
  // (hasil FinanceDashboard.getAIHook() apa adanya). score/label dari
  // FinanceIntelligence.healthScore() — 0 recompute di sini, pola sama
  // persis _healthCard() milik FinanceDashboard sendiri.
  _financeHealthCard(finance) {
    const hs = finance && finance.ok && finance.healthScore;
    if (!hs) {
      return { icon: '❤️', label: 'Skor Kesehatan Finansial', value: '—', cls: '' };
    }
    const cls = hs.score >= 80 ? 'green' : hs.score >= 60 ? '' : hs.score >= 40 ? 'orange' : 'red';
    return { icon: '❤️', label: 'Skor Kesehatan Finansial', value: `${hs.score}/100`, cls, sub: hs.label };
  },

  // _vehicleHealthCard(vehicle) — vehicle = CrossAIHook.getAIHook().vehicle
  // (hasil VehicleAIHook.fleetSummary() apa adanya). avgHealth dari
  // VehicleIntelligence.fleetSummary() — 0 recompute di sini, pola sama
  // persis _healthCard() milik VehicleDashboard sendiri.
  _vehicleHealthCard(vehicle) {
    const fleet = vehicle && vehicle.ok && vehicle.intelligence && vehicle.intelligence.fleet;
    if (!fleet || !fleet.totalVehicles) {
      return { icon: '🚗', label: 'Skor Kesehatan Armada', value: '—', cls: '' };
    }
    const score = fleet.avgHealth;
    const cls = score >= 80 ? 'green' : score >= 60 ? '' : score >= 40 ? 'orange' : 'red';
    return { icon: '🚗', label: 'Skor Kesehatan Armada', value: `${score}/100`, cls, sub: `${fleet.totalVehicles} kendaraan` };
  },

  // _combinedAttentionCard(finance, vehicle) — penjumlahan MURNI 2 counter
  // yang SUDAH ADA (lihat catatan header file): budget.overCount
  // (FinanceIntelligence.budgetSummary()) + reminder.overdueCount
  // (VehicleReminder.summary()). 0 threshold/skoring baru — kalau salah
  // satu sisi belum ok, dianggap 0 dari sisi itu (pola guard sama persis
  // fleetSummary()/getAIHook() lain di file ini).
  _combinedAttentionCard(finance, vehicle) {
    const budgetOver = (finance && finance.ok && finance.budget && finance.budget.ok) ? (finance.budget.overCount || 0) : 0;
    const vehicleOverdue = (vehicle && vehicle.ok && vehicle.reminder) ? (vehicle.reminder.overdueCount || 0) : 0;
    const total = budgetOver + vehicleOverdue;
    return {
      icon: '⚠️',
      label: 'Total Perhatian Gabungan',
      value: String(total),
      cls: total > 0 ? 'orange' : 'green',
      sub: `${budgetOver} anggaran lewat batas · ${vehicleOverdue} servis/pajak/BBM lewat jatuh tempo`,
    };
  },

};

// modules/cross/cross-insight-presenter.js — Finance & Vehicle Shared
// Insight Presenter (Sesi 87, Batch 8). Lihat docs/BATCH_PLAN.md § Batch 8.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// FinanceIntelligence.insights() (modules/finance/finance-intelligence.js,
// Sesi 74) + VehicleIntelligence.insights() (modules/vehicle/
// vehicle-intelligence.js, Sesi 76, dipanggil TANPA vehicleId = fleet-
// level) — TIDAK ada rule/threshold baru, TIDAK menghitung ulang apa pun,
// murni MENGGABUNGKAN (concat) 2 daftar insight yang SUDAH ADA jadi satu
// feed. Pola SAMA PERSIS VehicleInsightFeed (Sesi 80) — feed list dgn
// ikon per type, SILENT (body dikosongkan) kalau tidak ada insight apa
// pun, TANPA link navigasi.
//
// Beda dgn VehicleInsightFeed: VehicleInsightFeed mencakup insight+
// reminder due-soon SATU domain (vehicle) — CrossInsightPresenter di sini
// LINTAS-DOMAIN (finance+vehicle digabung dlm satu feed), TIDAK menyertakan
// reminder due-soon vehicle (sudah domain VehicleInsightFeed sendiri,
// supaya tidak dobel tampil di 2 tempat) — HANYA insights() dasar dari
// kedua lapisan Intelligence.
//
// Dipanggil dari DashboardHub.render() & live-wiring renderDashboard()
// (modules/shared/modules-render.js), TIDAK ada mekanisme render baru.
const CrossInsightPresenter = {

  // _icon(type) — pemetaan type insight ('warning'/'positive'/'info') ke
  // emoji, pola sama persis _insightIcon() di VehicleInsightFeed, MURNI
  // presentasional.
  _icon(type) {
    return { warning: '🟡', positive: '🟢', info: 'ℹ️' }[type] || 'ℹ️';
  },

  render() {
    const el = document.getElementById('crossInsightBody');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    const financeInsights = (typeof FinanceIntelligence !== 'undefined' && typeof FinanceIntelligence.insights === 'function')
      ? FinanceIntelligence.insights()
      : [];
    const vehicleInsights = (typeof VehicleIntelligence !== 'undefined' && typeof VehicleIntelligence.insights === 'function')
      ? VehicleIntelligence.insights()
      : [];

    const list = [...financeInsights, ...vehicleInsights]
      .map((ins) => ({ icon: this._icon(ins.type), message: ins.message }));

    if (!list.length) {
      el.innerHTML = '';
      return;
    }

    el.innerHTML = list.map((item) => {
      const iconHtml = (typeof FeatureIcons !== 'undefined') ? FeatureIcons.render(item.icon, { size: 14 }) : (item.icon || '');
      return `
      <div class="fi-insight-row" style="padding:8px 0;border-bottom:1px solid var(--border,rgba(255,255,255,.08));font-size:13px;">
        <span class="fi-insight-icon">${iconHtml}</span><span>${escapeHtml(item.message)}</span>
      </div>
    `;
    }).join('');
  },

};

// modules/cross/unified-summary-api.js — Finance & Vehicle Unified Summary
// API (Sesi 88, Batch 8). Target sesi: Unified AI Briefing Foundation —
// lihat docs/BATCH_PLAN.md § Batch 8.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE CrossAIHook.getAIHook() (modules/
// cross/cross-ai-hook.js, Sesi 87 — sendiri wrapper tipis ke CrossSummaryAPI.
// summary(), gabungan FinanceDashboard.getAIHook()+VehicleAIHook.
// fleetSummary()) — TIDAK ada rumus baru, TIDAK duplikasi logic, TIDAK
// framework baru, TIDAK mengubah struktur data D. UnifiedSummaryAPI HANYA
// menyiapkan bentuk data yang siap-pakai utk lapisan briefing (sesi ini
// juga, lihat unified-ai-briefing.js) — meneruskan finance/vehicle APA
// ADANYA dari CrossAIHook, ditambah `insightCount` (PENJUMLAHAN MURNI
// panjang 2 array insight yang SUDAH ADA — finance.insights.length +
// vehicle.intelligence.insights.length — BUKAN membangun daftar gabungan
// baru, supaya TIDAK duplikasi logic penggabungan feed yang sudah jadi
// tanggung jawab CrossInsightPresenter (Sesi 87); satu-satunya aritmatika
// di sini murni MENGHITUNG panjang, pola sama persis VehicleReminder.
// summary() yang menjumlah overdueCount+dueSoonCount+infoCount jadi total).
//
// TIDAK ada UI di file ini — presenter briefing-nya file terpisah
// (modules/cross/unified-briefing-presenter.js, sesi ini juga tapi murni
// presenter, 100% reuse unified-ai-briefing.js -> layer ini).
const UnifiedSummaryAPI = {

// summary() — Unified Summary API. Reuse 100% CrossAIHook.getAIHook()
// (finance+vehicle apa adanya, TANPA parameter — sudah akun/fleet-level).
// {ok:false} kalau CrossAIHook belum dimuat, ATAU diteruskan apa adanya
// kalau CrossAIHook.getAIHook() sendiri {ok:false} (pola sama persis
// vehicleInsight() milik VehicleAIHook yang meneruskan {ok:false} dari
// layer di bawahnya tanpa membungkus ulang).
summary() {
  if (typeof CrossAIHook === 'undefined') {
    return { ok: false, reason: 'CrossAIHook belum dimuat' };
  }
  const hook = CrossAIHook.getAIHook();
  if (!hook.ok) return hook;

  const financeInsightCount = (hook.finance && hook.finance.ok && Array.isArray(hook.finance.insights))
    ? hook.finance.insights.length : 0;
  const vehicleInsightCount = (hook.vehicle && hook.vehicle.ok && hook.vehicle.intelligence && Array.isArray(hook.vehicle.intelligence.insights))
    ? hook.vehicle.intelligence.insights.length : 0;

  return {
    ok: true,
    finance: hook.finance,
    vehicle: hook.vehicle,
    insightCount: financeInsightCount + vehicleInsightCount,
  };
},

};

// modules/cross/unified-ai-briefing.js — Finance & Vehicle Unified AI
// Briefing (Sesi 88, Batch 8). Lihat docs/BATCH_PLAN.md § Batch 8.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE UnifiedSummaryAPI.summary()
// (modules/cross/unified-summary-api.js, sesi ini) — TIDAK ada rumus
// baru, TIDAK menghitung ulang health score/fleet/reminder/budget, TIDAK
// membaca D langsung sama sekali. Murni PURE (read-only, tidak menyentuh
// DOM/localStorage) — pola sama persis lapisan Intelligence/Reminder
// (FinanceIntelligence/VehicleIntelligence/VehicleReminder), bukan
// presenter (presenter-nya file terpisah, unified-briefing-presenter.js,
// sesi ini juga).
//
// generate() menyusun ringkasan 1-3 kalimat dari angka yang SUDAH TERSEDIA
// lewat UnifiedSummaryAPI.summary() — pola SAMA PERSIS VehicleDailyBrief
// (Sesi 80, teks 1-2 kalimat dari VehicleAIHook.fleetSummary() apa
// adanya), cuma dipindah ke lapisan LINTAS-DOMAIN (finance+vehicle) &
// dipisah jadi lapisan data murni (generate() mengembalikan {ok,text,
// parts}, bukan langsung menulis ke DOM — beda dari VehicleDailyBrief yang
// menggabung logic teks+render jadi satu file, di sini dipisah sesuai 2
// deliverable terpisah sesi ini: "Unified AI Briefing" (murni data/teks)
// & "Dashboard Briefing Presenter" (UI, file terpisah)).
//
// Kartu "Total Perhatian Gabungan" (CrossDashboardCard, Sesi 87) SUDAH
// menjumlah budget.overCount+vehicle.reminder.overdueCount utk tampilan
// kartu — di sini angka yang SAMA dibaca ulang dari counter mentah yang
// SAMA (budget.overCount/reminder.overdueCount, keduanya sudah ada di
// hasil UnifiedSummaryAPI.summary() apa adanya) utk keperluan TEKS
// (kalimat naratif, bukan kartu angka) — pola konsisten dgn threshold
// skor->warna yang juga dibaca/direplikasi independen di tiap presenter
// (FinanceDashboard/VehicleDashboard/CrossDashboardCard), BUKAN rumus
// baru, murni penjumlahan trivial atas 2 counter yang sudah final dari
// layer di bawahnya.
//
// ARSITEKTUR (S116 — Circular Dependency Hotfix): UnifiedAIBriefing ADA
// DI LAPISAN BAWAH root chain (CrossSummaryAPI -> CrossAIHook ->
// UnifiedSummaryAPI -> UnifiedAIBriefing) yang lalu DIKONSUMSI ke ATAS
// oleh LifeDashboardSummaryAPI -> DecisionCenterAPI -> ActionQueue/
// RecommendationPanel. File ini SENGAJA TIDAK BOLEH membaca ActionQueue,
// DecisionCenterAPI, atau LifeDashboardSummaryAPI (dependency ke ARAH
// SEBALIKNYA akan membentuk siklus balik ke generate() ini sendiri —
// pernah terjadi sesaat di S115 lewat ActionQueue.getQueue(), sudah
// di-revert sesi ini krn menyebabkan "Maximum call stack size exceeded"
// saat rantai modul asli dimuat bersamaan; lihat
// tests/decision-center-dependency-graph.test.js utk regression test yg
// memuat rantai modul ASLI, bukan mock, supaya siklus ini tidak bisa
// balik lagi tanpa ketahuan).
const UnifiedAIBriefing = {

// generate() — Unified AI Briefing. {ok:false} kalau UnifiedSummaryAPI
// belum dimuat ATAU summary() sendiri {ok:false} (diteruskan apa adanya).
// {ok:false, reason:'Tidak ada data untuk briefing'} kalau finance/vehicle
// keduanya tidak tersedia (0 hal buat diceritakan — pola guard "silent
// kalau kosong" sama persis VehicleDailyBrief).
generate() {
  if (typeof UnifiedSummaryAPI === 'undefined') {
    return { ok: false, reason: 'UnifiedSummaryAPI belum dimuat' };
  }
  const s = UnifiedSummaryAPI.summary();
  if (!s.ok) return s;

  const parts = [];

  const fh = (s.finance && s.finance.ok) ? s.finance.healthScore : null;
  if (fh) {
    parts.push(`Skor kesehatan finansial ${fh.score}/100 (${fh.label}).`);
  }

  const fleet = (s.vehicle && s.vehicle.ok && s.vehicle.intelligence) ? s.vehicle.intelligence.fleet : null;
  if (fleet && fleet.totalVehicles) {
    parts.push(`Skor kesehatan armada ${fleet.avgHealth}/100 dari ${fleet.totalVehicles} kendaraan.`);
  }

  const budgetOver = (s.finance && s.finance.ok && s.finance.budget && s.finance.budget.ok) ? (s.finance.budget.overCount || 0) : 0;
  const vehicleOverdue = (s.vehicle && s.vehicle.ok && s.vehicle.reminder) ? (s.vehicle.reminder.overdueCount || 0) : 0;
  const totalAttention = budgetOver + vehicleOverdue;
  if (totalAttention > 0) {
    parts.push(`${totalAttention} hal butuh perhatian (${budgetOver} anggaran lewat batas, ${vehicleOverdue} servis/pajak/BBM lewat jatuh tempo).`);
  } else if (fh || (fleet && fleet.totalVehicles)) {
    parts.push('Tidak ada hal mendesak yang butuh perhatian saat ini.');
  }

  if (s.insightCount > 0) {
    parts.push(`${s.insightCount} insight tersedia hari ini.`);
  }

  if (!parts.length) {
    return { ok: false, reason: 'Tidak ada data untuk briefing' };
  }
  return { ok: true, text: parts.join(' '), parts };
},

};

