    if (typeof CrossDashboardCard !== 'undefined') CrossDashboardCard.render();
    if (typeof CrossInsightPresenter !== 'undefined') CrossInsightPresenter.render();

    // Unified AI Briefing Foundation (Sesi 88, Batch 8, lihat
