// engine/rule-engine.js — Evaluator IF-THEN generik (§9.2). SATU-SATUNYA
// tempat yang menjalankan condition/action dari rules/rule-definitions.js
// + rule custom hasil EIERegistry.registerRule() (§20).
//
// Cooldown anti-spam (§9) disimpan lewat eie-store (EIEStore.ruleCooldowns),
// BUKAN state lokal di file ini, supaya bertahan antar sesi/reload.

const EIE_SEVERITY_ORDER = { critical: 3, warning: 2, info: 1 };

const RuleEngine = {
  /**
   * @param {Object} macroSnapshots - { usdidr, inflasi, bi_rate, ihsg, emas, bbm, ... }
   * @param {import('../domain/entities.js').UserFinanceSnapshot} userSnapshot
   * @param {Object} [ctx] - { simulated?: boolean } — simulasi What-If tidak menulis cooldown
   * @returns {Array} triggered insights (belum di-persist)
   */
  evaluate(macroSnapshots, userSnapshot, ctx = {}) {
    const rules = (typeof EIERegistry !== 'undefined' ? EIERegistry.getRules() : EIE_RULES);
    const triggered = [];
    for (const rule of rules) {
      if (!rule.enabled) continue;
      if (!ctx.simulated && this._inCooldown(rule.id, rule.cooldownDays)) continue;
      try {
        if (rule.condition(macroSnapshots, userSnapshot, ctx)) {
          const result = rule.action(macroSnapshots, userSnapshot, ctx) || {};
          triggered.push({
            ruleId: rule.id, severity: rule.severity, weight: rule.weight,
            message: result.message || '', recommendationId: result.recommendationId || null,
          });
          if (!ctx.simulated) this._markCooldown(rule.id);
        }
      } catch (e) {
        console.warn(`[EIE] Rule ${rule.id} error, di-skip:`, e);
      }
    }
    return triggered.sort((a, b) => (EIE_SEVERITY_ORDER[b.severity] || 0) - (EIE_SEVERITY_ORDER[a.severity] || 0));
  },

  _inCooldown(ruleId, days) {
    const store = eieGetStore();
    const last = (store.ruleCooldowns || {})[ruleId];
    if (!last || !days) return false;
    const elapsedDays = (Date.now() - last) / (1000 * 60 * 60 * 24);
    return elapsedDays < days;
  },

  _markCooldown(ruleId) {
    const store = eieGetStore();
    store.ruleCooldowns = store.ruleCooldowns || {};
    store.ruleCooldowns[ruleId] = Date.now();
    // Tidak await eieSave() di sini secara sengaja — caller (ScoringEngine)
    // yang menentukan titik commit tunggal supaya tidak banyak write kecil
    // ber-hamburan ke IndexedDB dalam 1 siklus evaluasi.
  },
};

// engine/scoring-engine.js — Orkestrasi EES/PEHS/ERI + Status Ekonomi
// (§5-8), memanggil RuleEngine (§9) untuk insight, lalu PERSIST hasil ke
// eie-store. Ini SATU-SATUNYA tempat yang menulis EIEScoreSnapshot &
// Insight[] ke store (selaras dgn aturan "services/engine = satu2nya
// penulis" di §2 dokumen desain).

const EIEScoringEngine = {
  /**
   * Hitung EES/PEHS/ERI + Status Ekonomi dari snapshot yang SUDAH ada
   * (tidak baca D/adapter sendiri) — dipakai juga oleh ScenarioSimulator
   * (What-If, fase 2) supaya simulasi tidak menulis apa pun.
   */
  calculateAll(macroSnapshots, userSnapshot) {
    const ees = calcEES(userSnapshot);
    const pehs = calcPEHS(userSnapshot);
    const eri = calcERI(macroSnapshots);
    const { status, impactScore } = classifyEconomicStatus(ees.score, pehs.score, eri.score);
    return {
      economicExposureScore: ees.score,
      personalEconomicHealthScore: pehs.score,
      economicRiskIndex: eri.score,
      status,
      breakdown: { ees: ees.breakdown, pehs: pehs.breakdown, eri: eri.breakdown, impactScore },
    };
  },

  /**
   * Alur utama fase 1: baca macro (cache) + user (live dari D), hitung
   * skor, evaluasi rule -> insight, lalu PERSIST semuanya sekali jalan.
   * TIDAK mengirim notifikasi apa pun di sini (lihat notification-service.js
   * — sengaja pasif di fase 1, "senyap").
   */
  async recomputeAndPersist() {
    await eieEnsureLoaded();
    const macro = MacroDataAdapter.getLatest();
    const user = UserFinanceAdapter.getSnapshot();
    const scores = this.calculateAll(macro, user);
    const triggered = RuleEngine.evaluate(macro, user, { simulated: false });

    const store = eieGetStore();
    const today = new Date().toISOString().slice(0, 10);
    const snapshot = { date: today, ...scores };
    // 1 entry per hari: kalau hari yang sama sudah ada, timpa (bukan duplikat).
    store.scoreHistory = (store.scoreHistory || []).filter((s) => s.date !== today);
    store.scoreHistory.push(snapshot);
    store.scoreHistory = store.scoreHistory.slice(-365);

    const now = Date.now();
    const newInsights = triggered.map((t, i) => ({
      id: `ins_${now}_${i}_${t.ruleId}`,
      ruleId: t.ruleId, severity: t.severity, message: t.message,
      recommendationId: t.recommendationId, createdAt: now, read: false, dismissed: false,
    }));
    store.insights = (store.insights || []).concat(newInsights).slice(-200);
    store.lastSyncAt = now;

    await eieSave();
    EIEBus.emit('eie:scores-updated', { snapshot, insights: newInsights });
    return { snapshot, insights: newInsights };
  },

  async getLatestSnapshot() {
    await eieEnsureLoaded();
    const store = eieGetStore();
    const arr = store.scoreHistory || [];
    return arr.length ? arr[arr.length - 1] : null;
  },
};

// engine/insight-generator.js — Fase 1: template + slot filling SUDAH
// dilakukan langsung di dalam rule.action() (rules/rule-definitions.js),
// jadi file ini fokus jadi helper baca/kelola Insight[] tersimpan, dengan
// interface yang sama persis siap diisi upgrade AI di fase 3 (§21):
//
//   InsightGenerator.generate(triggeredRule, macro, user) -> string
//
// Prinsip kunci (§21): LLM TIDAK PERNAH menggantikan Rule Engine untuk
// angka/skor — hanya boleh merangkai bahasa kalau suatu saat dipasang.
// Fase 1 ini generate() masih pure passthrough (rule sudah generate teks).

const InsightGenerator = {
  /** Fase 1: passthrough. Fase 3 bisa ganti isi ini dgn panggilan LLM
   * (guarded try/catch, fallback ke passthrough kalau offline/gagal). */
  generate(triggeredRule) {
    return triggeredRule.message;
  },

  async list({ onlyUnread = false } = {}) {
    await eieEnsureLoaded();
    const store = eieGetStore();
    let list = store.insights || [];
    if (onlyUnread) list = list.filter((i) => !i.read);
    return list.slice().sort((a, b) => b.createdAt - a.createdAt);
  },

  async markRead(insightId) {
    await eieEnsureLoaded();
    const store = eieGetStore();
    const ins = (store.insights || []).find((i) => i.id === insightId);
    if (ins) { ins.read = true; await eieSave(); }
    return ins || null;
  },

  async dismiss(insightId) {
    await eieEnsureLoaded();
    const store = eieGetStore();
    const ins = (store.insights || []).find((i) => i.id === insightId);
    if (ins) { ins.dismissed = true; await eieSave(); }
    return ins || null;
  },
};

// services/macro-sync-service.js — Orkestrasi refresh macro + recompute
// skor. Ini titik masuk utama yang dipanggil UI/scheduler (§2: "SATU-
// SATUNYA tempat menulis ke EIEStore.*" ada di layer services/engine).
//
// FASE 1 ("senyap"): tidak ada auto-trigger apa pun terpasang secara
// default. Fungsi di bawah HARUS dipanggil eksplisit (mis. dari scheduler
// fase 2, atau manual dari console/UI) — mengikuti pola lazy-load
// lifeOSEnsureLoaded() yang sudah ada, supaya app tidak "diam-diam" jadi
// lebih berat/berisik dari sebelumnya sampai fase UI benar-benar dipasang.

const MacroSyncService = {
  /** Refresh macro (fase 1: dari cache/manual input) lalu recompute skor + insight. */
  async syncAndRecompute() {
    await eieEnsureLoaded();
    await MacroDataAdapter.refresh();
    return EIEScoringEngine.recomputeAndPersist();
  },

  /** Hanya recompute dari data yang sudah ada di cache, tanpa refresh macro. */
  async recomputeOnly() {
    await eieEnsureLoaded();
    return EIEScoringEngine.recomputeAndPersist();
  },
};

// services/notification-service.js — Event listener -> Notification API /
// in-app toast (§2, §14 dokumen desain).
//
// FASE 1 ("senyap", sesuai permintaan implementasi bertahap): service ini
// TIDAK subscribe ke EIEBus secara default & TIDAK pernah memanggil
// Notification API atau toast(). Ini murni siap pakai (interface sudah
// ada) supaya fase 2 tinggal panggil `NotificationService.enable()` tanpa
// perlu ubah scoring-engine/rule-engine sama sekali.
//
// Kenapa penting dipisah begini: memunculkan notifikasi browser/toast
// otomatis tanpa persetujuan eksplisit user bisa terasa mengganggu &
// prematur selama UI EIE (dashboard, insight feed) belum ada tempat bagi
// user untuk mengatur preferensinya. Jadi fase 1 sengaja senyap total.

const NotificationService = {
  _unsubscribe: null,
  _enabled: false,

  /** Aktifkan listener (dipanggil eksplisit di fase 2, TIDAK dipanggil otomatis di fase 1). */
  enable(options = {}) {
    if (this._enabled) return;
    this._enabled = true;
    this._unsubscribe = EIEBus.on('eie:scores-updated', ({ insights }) => {
      if (!insights || !insights.length) return;
      const critical = insights.filter((i) => i.severity === 'critical');
      const toShow = options.criticalOnly ? critical : insights;
      toShow.forEach((ins) => this._deliver(ins, options));
    });
  },

  disable() {
    if (this._unsubscribe) this._unsubscribe();
    this._unsubscribe = null;
    this._enabled = false;
  },

  _deliver(insight, options) {
    // In-app toast, reuse fungsi global toast() yang sudah ada di app
    // (dipakai fitur lain, mis. worthit.js) — guarded, tidak pernah lempar
    // error kalau toast() belum tersedia saat file ini dimuat lebih awal.
    try {
      if (typeof toast === 'function' && !options.silent) {
        toast(`${insight.severity === 'critical' ? '🔴' : (insight.severity === 'warning' ? '🟡' : 'ℹ️')} ${insight.message}`);
      }
    } catch (e) {
      console.warn('[EIE] NotificationService gagal deliver toast:', e);
    }
  },
};

// services/recommendation-service.js — mapping recommendationId -> aksi
// konkret (deep link ke fitur app existing yang SUDAH ada, bukan fitur
// baru). Data-only map + 1 fungsi baca, tidak ada state/I/O.
//
// `target` di sini mengikuti pola sama dgn FEATURE_REGISTRY di
// dashboard-hub-registry.js ({ page, tab?, goTo? }) supaya bisa dipanggil
// lewat fungsi navigasi yang sama, TIDAK menduplikasi mekanisme navigasi
// baru. Fase 2 UI (klik baris rekomendasi -> dashHubNavigateToFeature())
// sudah tersambung, lihat ui/eie-insight-feed.js.

