// scheduler/eie-scheduler.js — Trigger periodik untuk MacroSyncService
// (§14). FASE 1 ("senyap"): TIDAK ada setInterval yang otomatis jalan saat
// file ini dimuat. start()/stop() harus dipanggil eksplisit — supaya
// menambahkan file ini ke build TIDAK diam-diam membuat app polling/refresh
// di background sebelum ada UI yang benar-benar membutuhkannya (fase 2).

const EIEScheduler = {
  _timerId: null,

  /** @param {number} intervalMs default 6 jam */
  start(intervalMs = 6 * 60 * 60 * 1000) {
    if (this._timerId) return; // sudah jalan, tidak dobel
    this._timerId = setInterval(() => {
      MacroSyncService.recomputeOnly().catch((e) => console.warn('[EIE] Scheduler recompute gagal:', e));
    }, intervalMs);
  },

  stop() {
    if (this._timerId) { clearInterval(this._timerId); this._timerId = null; }
  },

  isRunning() {
    return !!this._timerId;
  },
};

// ui/eie-dashboard.js — Kartu Status Ekonomi (§19). HANYA render, tidak
// pernah akses EIEStore/adapter langsung — selalu lewat EIEScoringEngine/
// MacroSyncService. Dipanggil dari DashboardHub.render() (pola "tambahan
// murni" sama seperti LifeOSHome.render()).

const EIEDashboard = {
  _rendering: false,
  // Status buka/tutup panel "Chart & Analisa" di kartu watchlist —
  // disimpan di memori JS (bukan localStorage) sengaja, cukup per-sesi
  // halaman terbuka, reset lagi ke tertutup tiap reload (pola sama dgn
  // `_rendering` di atas: state UI murni, bukan data yg perlu persist).
  _watchlistExpanded: false,

  async render() {
    const wrap = document.getElementById('eieWrap');
    if (!wrap) return; // container belum ada di halaman ini, aman diam2.
    if (this._rendering) return;
    this._rendering = true;
    try {
      await eieEnsureLoaded();
      // fase 3: nyalakan lagi notifikasi kalau user sudah pernah aktifkan
      // di sesi sebelumnya (sekali per sesi — bootstrap() sendiri no-op
      // aman kalau dipanggil berkali-kali karena NotificationService.enable()
      // sudah guard `if(this._enabled)return`).
      if (typeof EIENotifSettings !== 'undefined') EIENotifSettings.bootstrap();
      const today = new Date().toISOString().slice(0, 10);
      let snapshot = await EIEScoringEngine.getLatestSnapshot();
      // Recompute paling banyak 1x/hari — bukan tiap buka Dashboard Hub,
      // supaya tidak jadi kerja berat berulang tiap render. syncAndRecompute()
      // (bukan recomputeOnly()) supaya boundary harian ini juga jadi titik
      // auto-fetch USD/IDR (API publik) & IHSG (AI+web search) — lihat
      // MacroDataAdapter.refresh(); gagal fetch tetap fallback ke cache lama
      // secara diam-diam (tidak pernah melempar ke sini).
      if (!snapshot || snapshot.date !== today) {
        const result = await MacroSyncService.syncAndRecompute();
        snapshot = result.snapshot;
      }
      this._renderStatusCard(snapshot);
      this._renderWatchlistCard();
      if (typeof EIEInsightFeed !== 'undefined') EIEInsightFeed.render();
    } catch (e) {
      console.warn('[EIE] EIEDashboard.render() gagal:', e);
    } finally {
      this._rendering = false;
    }
  },

  _renderStatusCard(score) {
    const el = document.getElementById('eieStatusCard');
    if (!el || !score) return;
    const meta = STATUS_META[score.status] || STATUS_META.normal;
    const barColor = score.status === 'risiko_tinggi' ? 'var(--accent2)' : (score.status === 'waspada' ? 'var(--accent4)' : 'var(--accent3)');
    el.innerHTML = `
      <div style="display:flex;align-items:center;gap:10px;">
        <div style="font-size:28px;line-height:1;">${meta.icon}</div>
        <div>
          <div style="font-weight:600;font-size:15px;">${meta.label}</div>
          <div style="font-size:12.5px;opacity:.75;">Eksposur: ${score.economicExposureScore} · Kesehatan: ${score.personalEconomicHealthScore} · Risiko Makro: ${score.economicRiskIndex}</div>
        </div>
      </div>
      <div style="margin-top:8px;height:6px;border-radius:4px;background:var(--panel2,rgba(255,255,255,.08));overflow:hidden;">
        <div style="height:100%;width:${Math.max(4, Math.min(100, score.breakdown && score.breakdown.impactScore || 0))}%;background:${barColor};"></div>
      </div>
      <div style="margin-top:6px;font-size:11.5px;opacity:.6;">Diperbarui: ${score.date}</div>
      ${this._macroSourceHintHTML()}
      <button class="btn btn-ghost btn-sm u-mt8" data-action="eieManualSync" data-args='["$el"]'>🔄 Perbarui Kurs USD & IHSG Sekarang</button>
    `;
  },

  /**
   * Kartu "Daftar pantauan" (IHSG + USD/IDR) — tampilan meniru widget
   * watchlist saham (angka besar + panah naik/turun + sparkline utk item
   * utama, lalu grid kartu kecil di bawahnya). Murni presenter: baca dari
   * `MacroDataAdapter.getLatest()`/`getHistory()`, tidak pernah tulis balik.
   * Diam-diam no-op kalau container `#eieWatchlistCard` belum ada di
   * halaman (pola sama seperti `render()` di atas).
   */
  _renderWatchlistCard() {
    const el = document.getElementById('eieWatchlistCard');
    if (!el || typeof MacroDataAdapter === 'undefined') return;
    const latest = MacroDataAdapter.getLatest();
    const ihsg = latest.ihsg;
    const usd = latest.usdidr;
    if (!ihsg || !usd) return;
    const ihsgHist = MacroDataAdapter.getHistory('ihsg', 30).map((s) => s.value);
    const now = new Date();
    const jam = String(now.getHours()).padStart(2, '0') + ':' + String(now.getMinutes()).padStart(2, '0');

    el.innerHTML = `
      <div style="display:flex;align-items:center;justify-content:space-between;">
        <div style="font-weight:600;font-size:15px;">Daftar pantauan Anda</div>
        <div style="display:flex;align-items:center;gap:6px;font-size:11.5px;opacity:.6;">
          <span>Diperbarui ${jam}</span>
          <button class="btn btn-ghost btn-sm" style="padding:2px 6px;" data-action="eieManualSync" data-args='["$el"]' aria-label="Segarkan">🔄</button>
        </div>
      </div>
      <div style="margin-top:10px;display:flex;align-items:center;justify-content:space-between;">
        <div>
          <div style="font-size:32px;font-weight:700;line-height:1;">${this._fmtIndexValue(ihsg.value)}</div>
          <div style="margin-top:4px;font-size:12.5px;">
            <span style="opacity:.65;">IHSG · IDX</span>
            <span style="color:${this._trendColor(ihsg.trend)};font-weight:600;">${this._fmtChangePct(ihsg.changePct)}</span>
          </div>
        </div>
        ${this._trendBadgeHTML(ihsg.trend)}
      </div>
      ${this._sparklineHTML(ihsgHist, ihsg.trend, this._watchlistExpanded ? 110 : 56)}
      <div style="margin-top:12px;display:grid;grid-template-columns:1fr 1fr;gap:10px;">
        ${this._watchlistMiniCardHTML('USD/IDR', 'Kurs', usd)}
      </div>
      <button class="btn btn-ghost btn-sm btn-full u-mt10" data-action="eieToggleWatchlistDetail">
        ${this._watchlistExpanded ? '▲ Sembunyikan Chart & Analisa' : '▼ Lihat Chart & Analisa AI'}
      </button>
      ${this._watchlistExpanded ? this._watchlistAiNoteHTML(ihsg, usd) : ''}
    `;
  },

  /** Kartu kecil 1 indikator (dipakai di grid bawah kartu watchlist utama). */
  _watchlistMiniCardHTML(label, exchange, snap) {
    return `
      <div style="background:var(--panel2,rgba(255,255,255,.06));border-radius:14px;padding:12px;">
        <div style="font-size:16.5px;font-weight:700;">${this._fmtIndexValue(snap.value)}</div>
        <div style="margin-top:2px;font-size:11.5px;opacity:.65;">${label}</div>
        <div style="margin-top:2px;font-size:11.5px;color:${this._trendColor(snap.trend)};font-weight:600;">${this._fmtChangePct(snap.changePct)}</div>
      </div>
    `;
  },

  /** Lingkaran panah naik/turun/datar di kanan atas — hijau naik, merah turun.
   * SEKARANG tombol beneran (dulu cuma <div> dekoratif, tidak mengarah kemana
   * pun) — tap membuka/menutup panel "Chart & Analisa" di bawahnya, sama
   * seperti tombol teks di bawah kartu. */
  _trendBadgeHTML(trend) {
    const bg = trend === 'up' ? 'var(--accent3)' : (trend === 'down' ? 'var(--accent2)' : 'var(--panel2,rgba(255,255,255,.15))');
    const arrow = trend === 'up' ? '↑' : (trend === 'down' ? '↓' : '→');
    return `<button data-action="eieToggleWatchlistDetail" aria-label="Lihat chart & analisa AI" style="width:38px;height:38px;border-radius:50%;background:${bg};border:none;display:flex;align-items:center;justify-content:center;color:#fff;font-size:18px;flex-shrink:0;cursor:pointer;">${arrow}</button>`;
  },

  _trendColor(trend) {
    return trend === 'up' ? 'var(--accent3)' : (trend === 'down' ? 'var(--accent2)' : 'inherit');
  },

  _fmtIndexValue(v) {
    if (typeof v !== 'number') return '-';
    return v.toLocaleString('id-ID', { maximumFractionDigits: 2 });
  },

  _fmtChangePct(pct) {
    if (typeof pct !== 'number') return '';
    const sign = pct > 0 ? '+' : '';
    return `${sign}${pct.toFixed(2)}%`;
  },

  /** Sparkline SVG sederhana dari histori nilai (min. 2 titik supaya ada
   * garis). Kurang dari 2 titik -> string kosong, diam2 tidak render apa2
   * (belum pernah ada histori, mis. baru pertama kali sync). `h` (tinggi
   * px) bisa dibesarkan saat panel "Chart & Analisa" dibuka supaya lebih
   * mudah dibaca, default 56 (ukuran ringkas di kartu tertutup). */
  _sparklineHTML(values, trend, h) {
    if (!Array.isArray(values) || values.length < 2) return '';
    const w = 280;
    const height = h || 56;
    const min = Math.min(...values);
    const max = Math.max(...values);
    const range = (max - min) || 1;
    const step = w / (values.length - 1);
    const pts = values.map((v, i) => {
      const x = i * step;
      const y = height - ((v - min) / range) * height;
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    });
    const color = trend === 'down' ? 'var(--accent2)' : 'var(--accent3)';
    const fillPts = `0,${height} ${pts.join(' ')} ${w},${height}`;
    return `
      <div style="margin-top:8px;">
        <svg viewBox="0 0 ${w} ${height}" style="width:100%;height:${height}px;display:block;" preserveAspectRatio="none">
          <polygon points="${fillPts}" fill="${color}" opacity="0.12"></polygon>
          <polyline points="${pts.join(' ')}" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></polyline>
        </svg>
      </div>
    `;
  },

  /**
   * Catatan "Analisa & Rekomendasi AI" utk kartu watchlist — heuristik
   * rule-based (BUKAN saran investasi berlisensi), pola & nada sama persis
   * dgn `PenyusutanAI`/`InvestAI` (icon + kalimat singkat, tanpa panggilan
   * API eksternal apa pun supaya selalu tersedia offline). Baca trend/
   * changePct IHSG & USD/IDR yg SUDAH dihitung `MacroDataAdapter`, tidak
   * pernah menghitung ulang/menebak angka baru.
   */
  _watchlistAiNoteHTML(ihsg, usd) {
    const notes = [];
    if (ihsg.trend === 'up') {
      notes.push({ icon: '📈', text: `IHSG naik ${this._fmtChangePct(ihsg.changePct)} dibanding data sebelumnya — sentimen pasar saham domestik sedang cenderung positif.` });
    } else if (ihsg.trend === 'down') {
      notes.push({ icon: '📉', text: `IHSG turun ${this._fmtChangePct(ihsg.changePct)} dibanding data sebelumnya — kalau kamu punya investasi saham/reksadana saham, ini wajar terjadi & bukan berarti harus buru-buru jual.` });
    } else {
      notes.push({ icon: '➖', text: 'IHSG relatif stabil (perubahan di bawah 0,05%) dibanding data sebelumnya.' });
    }
    if (usd.trend === 'up') {
      notes.push({ icon: '💱', text: `Rupiah melemah, USD/IDR naik jadi ${this._fmtIndexValue(usd.value)}. Barang impor, belanja luar negeri, atau cicilan berbasis USD bisa jadi lebih mahal — kalau ada rencana beli barang impor besar, pertimbangkan lebih cepat.` });
    } else if (usd.trend === 'down') {
      notes.push({ icon: '💱', text: `Rupiah menguat, USD/IDR turun jadi ${this._fmtIndexValue(usd.value)}. Momentum lumayan buat kebutuhan berbasis USD (belanja impor, DP kendaraan impor, dll).` });
    } else {
      notes.push({ icon: '💱', text: `Kurs USD/IDR relatif stabil di ${this._fmtIndexValue(usd.value)}.` });
    }
    if (ihsg.trend === 'up' && usd.trend === 'down') {
      notes.push({ icon: '✅', text: 'Kombinasi IHSG naik & Rupiah menguat biasanya menandakan kondisi makro yang cenderung mendukung — bukan jaminan, tapi sinyal cukup positif.' });
    } else if (ihsg.trend === 'down' && usd.trend === 'up') {
      notes.push({ icon: '⚠️', text: 'Kombinasi IHSG turun & Rupiah melemah bersamaan — kalau eksposurmu ke aset berisiko (saham/valas) lumayan besar, ini momen bagus utk cek ulang alokasi lewat kartu 💹 Performa Investasi.' });
    }
    const itemsHtml = notes.map((n) => `
      <div style="display:flex;gap:8px;align-items:flex-start;margin-bottom:8px;font-size:12px;line-height:1.5;">
        <span>${n.icon}</span><span>${n.text}</span>
      </div>
    `).join('');
    return `
      <div style="margin-top:10px;padding-top:10px;border-top:1px solid var(--border,rgba(255,255,255,.08));">
        <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;opacity:.6;margin-bottom:6px;">🤖 Analisa & Rekomendasi AI</div>
        ${itemsHtml}
        <div style="font-size:10.5px;opacity:.5;margin-top:2px;">Catatan otomatis berbasis data terakhir, bukan saran investasi berlisensi.</div>
      </div>
    `;
  },

  /** Baris kecil status sumber data USD/IDR & IHSG (auto-api/auto-ai/manual/belum
   * disinkron) supaya user tahu kenapa angkanya belum berubah kalau, mis., API
   * key AI di Pengaturan belum diisi (IHSG tidak bisa auto tanpa itu). */
  _macroSourceHintHTML() {
    try {
      const cache = (typeof MacroDataAdapter !== 'undefined' && MacroDataAdapter.getLatest()) || {};
      const label = (id, name) => {
        const s = cache[id];
        if (!s) return `${name}: belum ada data`;
        if (s.source === 'auto-api' || s.source === 'auto-ai') return `${name}: auto ✓`;
        if (s.source === 'manual-input') return `${name}: manual`;
        return `${name}: belum disinkron`;
      };
      return `<div style="margin-top:2px;font-size:11px;opacity:.55;">${label('usdidr', 'USD/IDR')} · ${label('ihsg', 'IHSG')}</div>`;
    } catch (e) {
      return '';
    }
  },
};

/** Tombol "▼ Lihat Chart & Analisa AI" / lingkaran panah tren di kartu
 * watchlist — toggle buka/tutup panel chart lebih besar + catatan AI.
 * State disimpan di `EIEDashboard._watchlistExpanded` (murni in-memory),
 * lalu render ulang HANYA kartu watchlist (bukan seluruh dashboard) supaya
 * ringan & tidak mengganggu kartu lain yg sedang tampil. */
function eieToggleWatchlistDetail() {
  EIEDashboard._watchlistExpanded = !EIEDashboard._watchlistExpanded;
  EIEDashboard._renderWatchlistCard();
}

/** Tombol manual "🔄 Perbarui Kurs USD & IHSG" — dipanggil dari data-action
 * lewat dispatcher global (features-helpers-global-security.js), $el = elemen
 * tombol itu sendiri supaya bisa dikasih status loading/disabled sementara. */
async function eieManualSync(btn) {
  const originalLabel = btn ? btn.textContent : null;
  if (btn) { btn.disabled = true; btn.textContent = '⏳ Memperbarui…'; }
  try {
    await eieEnsureLoaded();
    await MacroSyncService.syncAndRecompute();
    await EIEDashboard.render();
    if (typeof toast === 'function') toast('✅ Data kurs & IHSG diperbarui');
  } catch (e) {
    console.warn('[EIE] eieManualSync() gagal:', e);
    if (typeof toast === 'function') toast('⚠️ Gagal update, tetap pakai data sebelumnya');
  } finally {
    const stillBtn = document.getElementById('eieStatusCard') ? document.querySelector('#eieStatusCard [data-action="eieManualSync"]') : null;
    if (stillBtn) { stillBtn.disabled = false; }
    else if (btn) { btn.disabled = false; btn.textContent = originalLabel; }
  }
}

// ui/eie-insight-feed.js — Feed insight & rekomendasi (§3, §19). HANYA
// render, akses data lewat InsightGenerator/RecommendationService (bukan
// EIEStore langsung).
//
// Baris rekomendasi ("→ ...") DAPAT DIKLIK — fase 2 UI yang disebut di
// komentar services/recommendation-service.js. `rec.target` di sana sudah
// mengikuti bentuk sama persis dengan FEATURE_REGISTRY[].target di
// dashboard-hub-registry.js, jadi navigasinya REUSE dashHubNavigateToFeature()
// (dashboard-hub.js) lewat dispatcher data-action global yang sudah ada
// (features-helpers-global-security.js) — TIDAK menulis mekanisme navigasi
// baru di sini. dashHubNavigateToFeature() sendiri yang urus showPage +
// ganti tab + scroll/flash-highlight ke target.goTo, persis seperti dipakai
// puluhan kartu fitur lain di grid Dashboard Hub.

const EIEInsightFeed = {
  async render() {
    const el = document.getElementById('eieInsightFeed');
    if (!el) return;
    try {
      const list = (await InsightGenerator.list({ onlyUnread: false }))
        .filter((i) => !i.dismissed)
        .slice(0, 8);
      if (!list.length) {
        el.innerHTML = `<div style="font-size:12.5px;opacity:.6;padding:6px 0;">Belum ada insight — kondisi makro & keuanganmu belum memicu rule apa pun saat ini.</div>`;
        return;
      }
      const sevIcon = { critical: '🔴', warning: '🟡', info: 'ℹ️' };
      el.innerHTML = list.map((ins) => {
        const rec = ins.recommendationId ? RecommendationService.getById(ins.recommendationId) : null;
        // rec.target bisa kosong/tidak dikenal (mis. recommendationId baru
        // yang belum didaftarkan) — kalau begitu tetap tampil sbg teks
        // statis (fallback aman), bukan tombol mati/error.
        const recLine = rec
          ? (rec.target
            ? `<div class="u-pointer" style="margin-top:3px;font-size:11.5px;opacity:.7;" data-action="dashHubNavigateToFeature" data-args='${escapeHtml(JSON.stringify([rec.target]))}'>→ ${escapeHtml(rec.label)}</div>`
            : `<div style="margin-top:3px;font-size:11.5px;opacity:.7;">→ ${escapeHtml(rec.label)}</div>`)
          : '';
        return `
          <div style="padding:8px 0;border-bottom:1px solid var(--border,rgba(255,255,255,.08));font-size:13px;">
            <div>${sevIcon[ins.severity] || 'ℹ️'} ${escapeHtml(ins.message)}</div>
            ${recLine}
          </div>
        `;
      }).join('');
    } catch (e) {
      console.warn('[EIE] EIEInsightFeed.render() gagal:', e);
    }
  },
};

// ui/eie-notif-settings.js — Toggle notifikasi EIE di Pengaturan (fase 3).
// HANYA render + baca/tulis toggle lewat eie-store; tidak pernah menyentuh
// D (sama seperti ui/eie-dashboard.js & ui/eie-insight-feed.js). Menyalakan
// notifikasi sungguhan lewat NotificationService.enable()/disable() yang
// dari fase 1 memang sudah dibuat siap pakai untuk titik integrasi ini
// (lihat komentar di services/notification-service.js).
//
// Markup HTML toggle-nya ada di index.html/app_production.html, kartu
// "🌦️ Notifikasi Kondisi Ekonomi" di stgGroup4 (Notifikasi & Backup),
// dipanggil dari renderSettings() (modules-render.js) — pola sama persis
// dengan renderNotifSettings() (toggle reminder tagihan yang sudah ada).

const EIENotifSettings = {
  /** Render status toggle saat halaman Pengaturan dibuka. */
  async render() {
    const toggle = document.getElementById('eieNotifToggle');
    const status = document.getElementById('eieNotifStatus');
    if (!toggle) return; // markup belum ada di halaman ini, aman diam2.
    try {
      await eieEnsureLoaded();
      const store = eieGetStore();
      const on = !!store.notificationsEnabled;
      toggle.checked = on;
      if (status) status.textContent = on ? 'Aktif' : 'Belum aktif';
    } catch (e) {
      console.warn('[EIE] EIENotifSettings.render() gagal:', e);
    }
  },

  /** Dipanggil sekali di awal sesi (lihat EIEDashboard.render()) supaya
   * preferensi tersimpan dari sesi sebelumnya benar2 aktif lagi setelah
   * reload, bukan cuma tersimpan di store tanpa efek. */
  async bootstrap() {
    try {
      await eieEnsureLoaded();
      const store = eieGetStore();
      if (store.notificationsEnabled && typeof NotificationService !== 'undefined') {
        NotificationService.enable();
      }
    } catch (e) {
      console.warn('[EIE] EIENotifSettings.bootstrap() gagal:', e);
    }
  },

  async toggle(checked) {
    try {
      await eieEnsureLoaded();
      const store = eieGetStore();
      store.notificationsEnabled = !!checked;
      await eieSave();
      if (typeof NotificationService !== 'undefined') {
        if (checked) NotificationService.enable();
        else NotificationService.disable();
      }
      if (typeof toast === 'function') {
        toast(checked ? '🔔 Notifikasi Kondisi Ekonomi diaktifkan' : '🔕 Notifikasi Kondisi Ekonomi dimatikan');
      }
    } catch (e) {
      console.warn('[EIE] EIENotifSettings.toggle() gagal:', e);
    } finally {
      this.render();
    }
  },
};

/** Wrapper global dipanggil langsung dari onchange= di HTML (bukan lewat
 * dispatcher data-action), sama pola dgn toggleNotifEnabled() yang sudah
 * ada utk reminder tagihan. */
function toggleEieNotif(checked) {
  EIENotifSettings.toggle(checked);
}

// eie-registry.js — Plugin registry EIE. Dimuat PALING AKHIR (lihat urutan
// load di scripts/build.js), supaya EIE_RULES bawaan (rules/rule-definitions.js)
// sudah tersedia untuk diregistrasi sbg default.
//
// - registerIndicator(): daftar sumber data makro custom (fase 2, dipakai
//   kalau ada indikator baru selain 6 inti — contoh §20 "Harga Nikel").
// - registerRule(): daftar rule custom TANPA mengubah rule-engine.js.
//   Rule bawaan (EIE_RULES) otomatis ikut lewat getRules().
//
// PENTING: file ini TIDAK melakukan apa pun terhadap FEATURE_REGISTRY
// (dashboard-hub-registry.js) di fase 1 — belum ada kartu/menu UI EIE yang
// didaftarkan (sesuai permintaan implementasi bertahap: mulai dari yang
// ringan/senyap dulu). Titik integrasi UI menyusul di fase 2.

const EIERegistry = {
  _customIndicators: {},
  _customRules: [],

  registerIndicator(id, def) {
    if (!id || typeof def !== 'object') throw new Error('[EIE] registerIndicator butuh (id, def)');
    this._customIndicators[id] = def;
  },

  registerRule(rule) {
    const errors = validateRuleShape(rule);
    if (errors.length) {
      console.warn('[EIE] registerRule ditolak, rule tidak valid:', rule && rule.id, errors);
      return false;
    }
    rule.enabled = rule.enabled !== false;
    this._customRules.push(rule);
    return true;
  },

  getRules() {
    return EIE_RULES.concat(this._customRules);
  },

  getCustomIndicators() {
    return this._customIndicators;
  },
};

// ai-core.js — Smart Delivery Engine, Sesi 1/6: fondasi murni.
//
// Lihat RENCANA-SESI-RINGKAS.md (Smart Delivery Engine) untuk peta 6 sesi
// lengkap. Sesi ini CUMA fondasi (bus + storage + context) — TANPA fitur,
// TANPA decision/rule/recommend/learn (itu Sesi 2), TANPA logistics
// (Sesi 3), TANPA wiring ke modul lain (Sesi 6). File ini sengaja tidak
// berefek apa pun ke app yang berjalan sampai Sesi 2+ mulai memakainya.
//
// Kenapa 1 file, bukan 3 (ai-core.js + ai-context.js + ai-storage.js +
// ai-event-engine.js) seperti blueprint asli — lihat RENCANA-SESI-RINGKAS.md
// bagian "Kenapa dipangkas". Isinya tetap 3 lapisan terpisah, cuma
// dikumpulkan jadi 1 file lewat 3 namespace: AIBus, AIStore, AIContext.
//
// ATURAN WAJIB (sama persis pola eie-bus.js/eie-store.js yang sudah
// terbukti dipakai di economic-intelligence/):
// - Tidak pernah menyentuh D. Tidak ada property baru di D, tidak ada
//   perubahan struktur D sedikit pun.
// - Tidak pernah memanggil save() milik D.
// - Persist lewat IDBStore (reuse instance global yang sama dgn app), key
//   'ai:store', terpisah total dari siklus save/load milik D, LifeOSStore,
//   & EIEStore.
// - Modul lain di modules/ai/ (ai-decision-engine.js dkk, Sesi 2+) mengakses
//   store ini HANYA lewat aiLoad()/aiSave()/aiGetStore() di file ini —
//   jangan import/re-declare state terpisah di file lain.

// ------------------------------------------------------------------------
// AIBus — event bus internal Smart Delivery Engine. Pub/sub sederhana,
// TIDAK bergantung library luar, TIDAK menyentuh IndexedDB. Dipakai supaya
// decision-engine/logistics-engine (Sesi 2-3) bisa "memancarkan" event
// (mis. 'ai:recommendation-ready', 'ai:decision-made') tanpa listener
// (service/UI) perlu polling.
//
// PENTING (Sesi 1 — "senyap"): bus ini TIDAK auto-listen ke apa pun secara
// default. Tidak ada notifikasi/toast yang terpasang di file ini. Modul
// lain baru aktif kalau di-subscribe eksplisit (Sesi 2+).
// ------------------------------------------------------------------------
const AIBus = {
  _listeners: Object.create(null),

  on(eventName, handler) {
    if (!this._listeners[eventName]) this._listeners[eventName] = [];
    this._listeners[eventName].push(handler);
    return () => this.off(eventName, handler); // unsubscribe helper
  },

  off(eventName, handler) {
    const arr = this._listeners[eventName];
    if (!arr) return;
    this._listeners[eventName] = arr.filter((h) => h !== handler);
  },

  emit(eventName, payload) {
    const arr = this._listeners[eventName];
    if (!arr || !arr.length) return;
    // Salin array supaya handler yang unsubscribe di tengah iterasi aman.
    arr.slice().forEach((handler) => {
      try {
        handler(payload);
      } catch (e) {
        // AI Core tidak boleh menjatuhkan app utama kalau 1 listener error.
        console.warn('[AICore] Listener error untuk event "' + eventName + '":', e);
      }
    });
  },
};

// ------------------------------------------------------------------------
// AIStore — SATU-SATUNYA tempat Smart Delivery Engine boleh MENULIS/MEMBACA
// persistensi. Struktur field disiapkan longgar dari sekarang (Sesi 1)
// supaya Sesi 2 (decision/rule/recommend/learn) & Sesi 3 (logistics) tinggal
// mengisi, bukan menambah key baru yang berisiko lupa didaftarkan.
// ------------------------------------------------------------------------
let AIStore = {
  decisionLog: [],   // DecisionLogEntry[] — riwayat keputusan AI (diisi Sesi 2)
  recommendations: [], // Recommendation[] — rekomendasi aktif (diisi Sesi 2)
  learningData: {},   // { [key]: any } — data pembelajaran ringan (diisi Sesi 2)
  ruleCooldowns: {},  // { [ruleId]: epochMsTerakhirTrigger } (diisi Sesi 2)
  lastRunAt: null,
};

const AI_STORE_KEY = 'ai:store';
const AI_STORE_DEFAULT = {
  decisionLog: [], recommendations: [], learningData: {},
  ruleCooldowns: {}, lastRunAt: null,
};

async function aiLoad() {
  // CATATAN: sama seperti eie-store.js/lifeos-store.js — IDBStore.get()
  // cuma terima 1 argumen, default diterapkan manual di sini.
  const raw = await IDBStore.get(AI_STORE_KEY);
  // Merge dgn default supaya field baru yg ditambah sesi selanjutnya
  // (mis. learningData isi baru di Sesi 2) tidak bikin `undefined` di
  // data lama user.
  AIStore = Object.assign({}, AI_STORE_DEFAULT, raw || {});
  return AIStore;
}

let _aiLoaded = false;
// Dipanggil oleh SATU entry point (service Sesi 2+) — load dari IDBStore
// SEKALI per sesi app, bukan tiap render, supaya tidak round-trip
// IndexedDB tiap kali fitur AI dibuka.
async function aiEnsureLoaded() {
  if (!_aiLoaded) {
    await aiLoad();
    _aiLoaded = true;
  }
  return AIStore;
}

async function aiSave() {
  return IDBStore.set(AI_STORE_KEY, AIStore);
}

function aiGetStore() {
  return AIStore;
}

/** Invalidate cache "sudah dimuat sekali per sesi" (lihat aiEnsureLoaded()
 * di atas). Pemanggil yang sah: applyRestoredData() (backup-restore.js),
 * setelah menulis ulang key 'ai:store' di IndexedDB dari file backup —
 * supaya render berikutnya baca ULANG dari IndexedDB, bukan state lama di
 * memori dari SEBELUM restore. Dipanggil lewat guard
 * `typeof aiInvalidateCache==='function'`, pola yang sama dgn cross-module
 * check lain di app ini. Wiring pemanggilan sebenarnya baru di Sesi 6. */
function aiInvalidateCache() {
  _aiLoaded = false;
}

// ------------------------------------------------------------------------
// AIContext — pembaca READ-ONLY ringkasan state app yang relevan buat AI
// (finance/shop/vehicle dst), TANPA menyentuh/menulis D sama sekali. Dipakai
// decision-engine (Sesi 2) & logistics-engine (Sesi 3) supaya tidak
// masing-masing baca D langsung dgn cara berbeda-beda.
//
// Sesi 1: hanya kerangka + snapshot() umum (timestamp + hasAppData).
// Sesi 13: Context Collector per-domain (lihat 4 builder `_aiContext*` di
// bawah) — fondasi wajib sebelum rule Cross Module Finance+Delivery
// (TODO.md #2) bisa membaca 2+ domain dalam 1 condition(). Lihat komentar
// di atas tiap builder untuk sumber fungsi yang di-reuse per domain.
// ------------------------------------------------------------------------

// _aiContextFinance() — reuse computeCashflowForecast() (tx-list-cashflow.js,
// Sesi 5) APA ADANYA, ambil field yang relevan buat rule cross-module
// (saldo & rata-rata arus kas). TIDAK menghitung ulang rumus apa pun di
// sini. Guard: skip (`available:false`) kalau D belum ada ATAU
// computeCashflowForecast belum di-load (mis. test yang cuma load
// ai-core.js sendirian) — TIDAK melempar error.
function _aiContextFinance() {
  if (typeof D === 'undefined' || !D || typeof computeCashflowForecast !== 'function') {
    return { available: false };
  }
  const cf = computeCashflowForecast();
  return {
    available: true,
    saldoNow: cf.saldoNow,
    incAvgBulanan: cf.incAvg,
    expAvgBulanan: cf.expAvg,
    billsDue30Hari: cf.billsDue,
    billsDueCount: (cf.upcoming || []).length,
    projected30Hari: cf.projected,
  };
}

// _aiContextAsset() — reuse netWorthForecast() (aset.js, Sesi 6) APA
// ADANYA. monthsAhead sengaja kecil (1) krn snapshot cuma butuh sinyal
// tren TERDEKAT (naik/turun), bukan proyeksi jangka panjang penuh (itu
// tugas fitur proyeksi Aset sendiri, bukan context collector ini). Skip
// kalau netWorthForecast belum di-load ATAU balikin {ok:false} (data
// histori belum cukup, lihat komentar netWorthForecast di aset.js).
// (Sesi 265, Ownership Sync — AI): assetCount SEKARANG hanya menghitung
// aset ownership SELF, reuse isAssetOwnershipSelf() (aset.js, Sesi 193),
// pola sama persis _aiContextVehicle() di bawah (Sesi 197). Guard typeof:
// kalau helper belum dimuat, anggap semua SELF (tidak exclude apa pun).
function _aiContextAsset() {
  if (typeof D === 'undefined' || !D || typeof netWorthForecast !== 'function') {
    return { available: false };
  }
  const fc = netWorthForecast({ monthsAhead: 1 });
  if (!fc.ok) return { available: false, reason: fc.reason };
  const assetSelfFilter = typeof isAssetOwnershipSelf === 'function' ? isAssetOwnershipSelf : (() => true);
  return {
    available: true,
    assetCount: Array.isArray(D.assets) ? D.assets.filter(assetSelfFilter).length : 0,
    netWorthNow: fc.netWorthNow,
    metode: fc.metode,
    trend: fc.projectedEnd >= fc.netWorthNow ? 'naik' : 'turun',
  };
}

// _aiContextVehicle() — reuse fuelEfficiency(vehicleId) (vehicle-core.js,
// Sesi 8, SUDAH dipakai rule vehicle-fuel-efficiency-drop Sesi 12) per
// kendaraan di D.vehicles. Kendaraan dgn histori kurang (fuelEfficiency
// balikin {ok:false}) TETAP masuk daftar (rpPerKm/estMonthlyCost null),
// TIDAK di-skip dari array, supaya vehicleCount tetap konsisten dgn
// D.vehicles.length.
// _aiContextVehicle() (Sesi 197, Ownership Sync — AI): TAMBAH 1 filter
// isVehicleOwnershipSelf(v.id) di atas D.vehicles (0 logic lama diubah) —
// kendaraan ber-ownership INVESTOR/CUSTOMER/THIRD_PARTY/FAMILY dikecualikan
// dari context AI Daily Briefing, pola sama persis isVehicleOwnershipSelf()
// di vehicle-core.js (Sesi 196). Guard typeof: kalau helper belum dimuat,
// anggap semua SELF (tidak exclude apa pun).
function _aiContextVehicle() {
  if (typeof D === 'undefined' || !D || !Array.isArray(D.vehicles) || typeof fuelEfficiency !== 'function') {
    return { available: false };
  }
  const selfVehicles = D.vehicles.filter((v) => typeof isVehicleOwnershipSelf !== 'function' || isVehicleOwnershipSelf(v.id));
  const vehicles = selfVehicles.map((v) => {
    const eff = fuelEfficiency(v.id);
    return {
      id: v.id,
      name: v.name,
      rpPerKm: eff.ok ? eff.rpPerKm : null,
      estMonthlyCost: eff.ok ? eff.estMonthlyCost : null,
    };
  });
  return { available: true, vehicleCount: vehicles.length, vehicles };
}

// _aiContextShop() — dua sinyal ringan Shop/Delivery, keduanya reuse yang
// SUDAH ADA:
// 1) lowStock: reuse _deliveryLowStockCheck() (cobek-pricing.js, Sesi 8)
//    APA ADANYA (ambang sudah bisa diatur user lewat
//    getAIDeliveryLowStockThreshold()).
// 2) recentAvgMarginPct: 5 transaksi Cobek terakhir, pola sort SAMA PERSIS
//    dgn Order.renderRecent() (cobek-order.js): `(b.id||0)-(a.id||0)`.
//    Formula margin (profit/total*100) SAMA PERSIS dgn yang dipakai emit
//    event 'delivery.created' di Order._saveInner() (cobek-order.js) —
//    field profit/total SUDAH tersimpan di tiap entri D.cobek, di sini
//    cuma dibaca ulang + dirata-rata, BUKAN rumus baru.
// _aiContextShop() (Sesi 265, Ownership Sync — AI): TAMBAH filter
// isProductOwnershipSelf/isCobekOwnershipSelf (0 logic lama diubah), pola
// sama persis prodSelfFilter/cobSelfFilter di feature-insights.js (S260) —
// produk/transaksi Cobek ber-ownership INVESTOR/CUSTOMER/THIRD_PARTY/FAMILY
// dikecualikan dari context AI Daily Briefing. Guard typeof: kalau helper
// belum dimuat, anggap semua SELF (tidak exclude apa pun).
function _aiContextShop() {
  if (typeof D === 'undefined' || !D || !Array.isArray(D.cobek) || !Array.isArray(D.products)) {
    return { available: false };
  }
  const prodSelfFilter = typeof isProductOwnershipSelf === 'function' ? isProductOwnershipSelf : (() => true);
  const cobSelfFilter = typeof isCobekOwnershipSelf === 'function' ? isCobekOwnershipSelf : (() => true);
  const lowStock = (typeof _deliveryLowStockCheck === 'function') ? _deliveryLowStockCheck() : null;
  const recent = D.cobek
    .filter((c) => typeof c.profit === 'number' && typeof c.total === 'number' && c.total > 0)
    .filter(cobSelfFilter)
    .sort((a, b) => (b.id || 0) - (a.id || 0))
    .slice(0, 5);
  const recentAvgMarginPct = recent.length
    ? Math.round((recent.reduce((s, c) => s + (c.profit / c.total) * 100, 0) / recent.length) * 100) / 100
    : null;
  return {
    available: true,
    productCount: D.products.filter(prodSelfFilter).length,
    lowStockCount: lowStock ? lowStock.low.length : null,
    recentAvgMarginPct,
    recentOrdersConsidered: recent.length,
  };
}

// _aiMeasureMs(fn)/_aiMeasureMsAsync(fn) — Tahap 8 (Performance Check,
// TODO.md #4e). Helper timing generik TUNGGAL, dipakai ulang oleh
// AIService.healthCheck() (satu-satunya pemanggil sejauh ini) buat
// mengukur durasi eksekusi 5 fungsi yang jadi scope Performance Check
// (Context Collector/Rule Evaluation/Recommendation/Daily Briefing/
// Simulation — lihat docs/PRODUCT_DECISIONS.md § Performance Check).
// Pakai Date.now() (bukan performance.now()) supaya konsisten dgn pola
// timestamp yang sudah dipakai di seluruh modules/ai/ (mis.
// ai-decision-engine.js _inCooldown()/_markCooldown()) & tetap jalan di
// harness test (tests/helpers/loadSource.js tidak menyediakan global
// `performance` di sandbox vm-nya). Resolusi ms cukup buat "cek sehat",
// bukan micro-benchmark presisi tinggi. Murni wrapper — TIDAK menulis
// apa pun, TIDAK mengubah nilai balik fn asli (`result` dikembalikan apa
// adanya supaya pemanggil bisa tetap pakai hasilnya kalau perlu).
function _aiMeasureMs(fn) {
  const start = Date.now();
  const result = fn();
  return { result, ms: Date.now() - start };
}

async function _aiMeasureMsAsync(fn) {
  const start = Date.now();
  const result = await fn();
  return { result, ms: Date.now() - start };
}

const AIContext = {
  // snapshot() — ringkasan umum (timestamp + status ketersediaan D) DITAMBAH
  // ringkasan per-domain (finance/asset/vehicle/shop, Sesi 13). Tiap domain
  // sengaja dibungkus builder terpisah (`_aiContext*` di atas) yang SELALU
  // guard lewat `typeof fn==='function'` supaya domain yang belum di-load
  // di-skip (`{available:false}`) alih-alih melempar error atau menebak
  // bentuk data. PURE/read-only — tidak pernah menulis ke D atau memanggil
  // save() di jalur ini.
  snapshot() {
    return {
      generatedAt: new Date().toISOString(),
      hasAppData: typeof D !== 'undefined' && D !== null,
      finance: _aiContextFinance(),
      asset: _aiContextAsset(),
      vehicle: _aiContextVehicle(),
      shop: _aiContextShop(),
    };
  },
};

// Expose ke window kalau dijalankan di browser (pola sama dgn EIEBus/
// EIEStore/LifeOSStore — modul lain akses lewat variabel global ini,
// bukan module.exports, karena app ini tidak pakai bundler ES module).
if (typeof window !== 'undefined') {
  window.AIBus = AIBus;
  window.AIContext = AIContext;
}

// ai-decision-engine.js — Smart Delivery Engine, Sesi 2/6: "otak" AI.
//
// Lihat RENCANA-SESI-RINGKAS.md untuk peta 6 sesi. Sesi ini butuh Sesi 1
// (ai-core.js: AIBus, AIStore/aiEnsureLoaded/aiGetStore/aiSave, AIContext)
// SUDAH dimuat lebih dulu — lihat urutan di scripts/build.js.
//
// Kenapa 1 file, bukan 4 (ai-decision-engine.js + ai-rule-engine.js +
// ai-recommendation-engine.js + ai-learning-engine.js) — lihat
// RENCANA-SESI-RINGKAS.md bagian "Kenapa dipangkas". Isinya tetap 3
// lapisan terpisah + 1 orkestrator, dikumpulkan lewat namespace internal:
//   AIDecision.rules    — registry + evaluator IF-THEN generik (pola sama
//                          dgn EIERegistry+RuleEngine, tapi digabung jadi
//                          1 karena Sesi ini tidak menyediakan file
//                          registry terpisah).
//   AIDecision.recommend — mapping recommendationId -> aksi konkret (pola
//                          sama dgn RecommendationService), diisi domain
//                          modules di Sesi 4-5 lewat .register().
//   AIDecision.learn     — pencatatan hasil (diterima/ditolak/diabaikan)
//                          per rule, dipakai penyesuaian confidence ringan
//                          (BUKAN machine learning — cuma rasio hitung).
//   AIDecision.decide()  — orkestrator: evaluate rules -> persist decision
//                          log + cooldown -> emit event lewat AIBus.
//
// PENTING (Sesi 2 — masih "senyap"): TIDAK ada satu pun rule domain yang
// didaftarkan di file ini. AIDecision.rules._rules kosong sampai modul
// SHOP/COBEK/FINANCE/dst (Sesi 4-5) mulai memanggil
// AIDecision.rules.register(...). File ini murni mesin generik + kontrak
// yang dites, TIDAK berefek apa pun ke app yang berjalan sampai ada
// pendaftar.

const AI_VALID_SEVERITIES = ['info', 'warning', 'critical'];
const AI_SEVERITY_ORDER = { critical: 3, warning: 2, info: 1 };
const AI_VALID_OUTCOMES = ['accepted', 'rejected', 'ignored'];
// Sesi 11 — mapping severity (rule) -> priority (rekomendasi terformat).
// Tidak menambah severity baru; 'LOW' dipakai kalau weight rule rendah
// (lihat formatRecommendation) supaya 4 level priority (LOW/MEDIUM/HIGH/
// CRITICAL) tetap tersedia tanpa mengubah kontrak severity yang sudah ada.
const AI_PRIORITY_FROM_SEVERITY = { critical: 'CRITICAL', warning: 'HIGH', info: 'MEDIUM' };

/** Validasi struktur Rule sebelum diterima registry — sama filosofinya
 * dgn eie rule-schema.js: rule custom yang salah bentuk ditolak diam-diam
 * (return errors[], bukan throw) supaya 1 modul yang salah daftar tidak
 * bisa menjatuhkan modul lain yang sudah lebih dulu register. */
function validateAIRuleShape(rule) {
  const errors = [];
  if (!rule || typeof rule !== 'object') return ['Rule harus berupa object'];
  if (!rule.id || typeof rule.id !== 'string') errors.push('Rule.id wajib string');
  if (!rule.category || typeof rule.category !== 'string') errors.push('Rule.category wajib string');
  if (typeof rule.condition !== 'function') errors.push('Rule.condition wajib function (ctx)=>boolean');
  if (typeof rule.action !== 'function') errors.push('Rule.action wajib function (ctx)=>{message,recommendationId?}');
  if (!AI_VALID_SEVERITIES.includes(rule.severity)) errors.push('Rule.severity wajib salah satu dari: ' + AI_VALID_SEVERITIES.join(', '));
  if (typeof rule.weight !== 'number') errors.push('Rule.weight wajib number');
  if (typeof rule.cooldownHours !== 'number' || rule.cooldownHours < 0) errors.push('Rule.cooldownHours wajib number >= 0');
  return errors;
}

const AIDecision = {
  // ----------------------------------------------------------------------
  // .rules — registry + evaluator IF-THEN generik. Domain-agnostic:
  // logistik/keuangan/aset/dll semua mendaftar lewat interface yang sama.
  // ----------------------------------------------------------------------
  rules: {
    // Array (bukan map) — sama alasannya dgn AICommandCenter: urutan
    // pendaftaran dipertahankan apa adanya untuk konsumen (mis. urutan
    // tampil di daily briefing) tanpa bergantung urutan Object.keys().
    _rules: [],

    /** register(rule) — satu-satunya jalur pendaftaran rule. Return true
     * kalau berhasil, false kalau invalid atau id duplikat (skip diam-diam,
     * bukan exception — pola sama dgn AICommandCenter.registerCommand). */
    register(rule) {
      const errors = validateAIRuleShape(rule);
      if (errors.length) {
        console.warn('[AIDecision] Rule ditolak:', rule && rule.id, errors);
        return false;
      }
      if (this._rules.some((r) => r.id === rule.id)) return false; // id harus unik
      this._rules.push({
        id: rule.id,
        category: rule.category,
        condition: rule.condition,
        action: rule.action,
        severity: rule.severity,
        weight: rule.weight,
        cooldownHours: rule.cooldownHours,
        enabled: rule.enabled !== false, // default true kecuali eksplisit false
        description: typeof rule.description === 'string' ? rule.description : '',
      });
      return true;
    },

    unregister(id) {
      const before = this._rules.length;
      this._rules = this._rules.filter((r) => r.id !== id);
      return this._rules.length < before;
    },

    getAll() {
      return this._rules.slice();
    },

    /** evaluate(ctx) — jalankan semua rule enabled & di luar cooldown
     * terhadap ctx (bentuk ctx bebas, ditentukan pemanggil per-domain —
     * mis. { finance: {...}, logistics: {...} } di sesi lanjutan).
     * ctx.simulated=true (What-If, dipakai AIService.simulate() Sesi ini
     * juga) TIDAK menandai cooldown, supaya simulasi tidak mengganggu
     * jadwal munculnya rekomendasi nyata. */
    evaluate(ctx = {}) {
      const triggered = [];
      for (const rule of this._rules) {
        if (!rule.enabled) continue;
        if (!ctx.simulated && this._inCooldown(rule.id, rule.cooldownHours)) continue;
        try {
          if (rule.condition(ctx)) {
            const result = rule.action(ctx) || {};
            triggered.push({
              ruleId: rule.id, category: rule.category, severity: rule.severity, weight: rule.weight,
              message: result.message || '', recommendationId: result.recommendationId || null,
              // Sesi 11 — field opsional, dilewatkan apa adanya kalau rule
              // domain menyediakannya (lihat formatRecommendation di bawah).
              // Rule lama yang tidak mengisi field ini tetap jalan normal
              // (fallback dihitung dari severity/weight/category).
              title: typeof result.title === 'string' ? result.title : null,
              affectedModules: Array.isArray(result.affectedModules) ? result.affectedModules : null,
              estimatedImpact: (result.estimatedImpact && typeof result.estimatedImpact === 'object') ? result.estimatedImpact : null,
              actions: Array.isArray(result.actions) ? result.actions : null,
              // Sesi 344b — actionTargets: pasangan opsional utk 'actions' di atas
              // ({type,id} per index yg sama), dipakai AIRecommendCard (ai-chat.js)
              // supaya tombol aksi bisa BENERAN buka modal terkait, bukan cuma teks.
              // Rule yg tidak menyediakan (mayoritas) tetap jalan normal (null, sama
              // pola fallback field opsional lain di formatRecommendation di bawah).
              actionTargets: Array.isArray(result.actionTargets) ? result.actionTargets : null,
            });
            if (!ctx.simulated) this._markCooldown(rule.id);
          }
        } catch (e) {
          // 1 rule error tidak boleh menjatuhkan evaluasi rule lain.
          console.warn(`[AIDecision] Rule ${rule.id} error, di-skip:`, e);
        }
      }
      return triggered.sort((a, b) => (AI_SEVERITY_ORDER[b.severity] || 0) - (AI_SEVERITY_ORDER[a.severity] || 0));
    },

    _inCooldown(ruleId, hours) {
      const store = aiGetStore();
      const last = (store.ruleCooldowns || {})[ruleId];
      if (!last || !hours) return false;
      const elapsedHours = (Date.now() - last) / (1000 * 60 * 60);
      return elapsedHours < hours;
    },

    _markCooldown(ruleId) {
      const store = aiGetStore();
      store.ruleCooldowns = store.ruleCooldowns || {};
      store.ruleCooldowns[ruleId] = Date.now();
      // Tidak await aiSave() di sini secara sengaja — AIDecision.decide()
      // (di bawah) yang jadi titik commit tunggal, sama pola dgn EIE
      // RuleEngine._markCooldown() vs EIEScoringEngine.recomputeAndPersist().
    },
  },

  // ----------------------------------------------------------------------
  // .recommend — mapping recommendationId -> aksi konkret ({ label,
  // target }). Data-only registry, diisi domain modules (Sesi 4-5) lewat
  // .register(), TIDAK berisi rekomendasi bawaan apa pun di Sesi 2 ini.
  // ----------------------------------------------------------------------
  recommend: {
    _map: Object.create(null),

    register(id, def) {
      if (typeof id !== 'string' || id.trim() === '') return false;
      if (!def || typeof def !== 'object' || typeof def.label !== 'string') return false;
      this._map[id] = { label: def.label, target: def.target || null };
      return true;
    },

    getById(id) {
      return this._map[id] || null;
    },

    getAll() {
      return Object.assign({}, this._map);
    },
  },

  // ----------------------------------------------------------------------
  // .learn — pencatatan ringan hasil keputusan per rule (diterima/ditolak/
  // diabaikan user), dipersist ke AIStore.learningData. BUKAN machine
  // learning — cuma rasio hitung, dipakai UI/rule masa depan buat
  // menimbang seberapa "dipercaya" rekomendasi dari rule tertentu.
  // ----------------------------------------------------------------------
  learn: {
    /** recordOutcome(ruleId, outcome) — persist langsung (bukan nunggu
     * decide() berikutnya), supaya feedback user tidak hilang kalau app
     * ditutup sebelum siklus decide() berikutnya jalan. */
    async recordOutcome(ruleId, outcome) {
      if (typeof ruleId !== 'string' || ruleId.trim() === '') return null;
      if (!AI_VALID_OUTCOMES.includes(outcome)) return null;
      await aiEnsureLoaded();
      const store = aiGetStore();
      store.learningData = store.learningData || {};
      const stats = store.learningData[ruleId] || { accepted: 0, rejected: 0, ignored: 0 };
      stats[outcome] += 1;
      store.learningData[ruleId] = stats;
      await aiSave();
      return stats;
    },

    async getStats(ruleId) {
      await aiEnsureLoaded();
      const store = aiGetStore();
      return (store.learningData || {})[ruleId] || { accepted: 0, rejected: 0, ignored: 0 };
    },

    /** getConfidence(ruleId) — rasio accepted / (accepted+rejected),
     * mengabaikan 'ignored' (belum tentu penolakan). Default 0.5 (netral)
     * kalau belum ada data sama sekali, supaya rule baru tidak langsung
     * dianggap tidak dipercaya. */
    async getConfidence(ruleId) {
      const stats = await this.getStats(ruleId);
      const decided = stats.accepted + stats.rejected;
      if (decided === 0) return 0.5;
      return stats.accepted / decided;
    },
  },

  // ----------------------------------------------------------------------
  // decide(ctx) — orkestrator utama: evaluate rules -> tulis decisionLog +
  // cooldown -> PERSIST sekali jalan -> emit 'ai:decision-made' lewat
  // AIBus. Ini SATU-SATUNYA tempat yang menulis AIStore.decisionLog
  // (selaras aturan "engine/service = satu-satunya penulis" dari pola EIE).
  // ----------------------------------------------------------------------
  async decide(ctx = {}) {
    await aiEnsureLoaded();
    const triggered = this.rules.evaluate(ctx);

    if (ctx.simulated) {
      // Simulasi (What-If): kembalikan hasil TANPA menulis apa pun ke
      // store (cooldown pun tidak ditandai — lihat rules.evaluate di atas).
      // recommendations tetap dibentuk (read-only, dari `triggered` yang
      // sudah bawa title/affectedModules/estimatedImpact/actions) supaya
      // UI What-If bisa pakai kontrak output yang sama dgn decide() nyata.
      const simDecisions = triggered.map((t, i) => ({
        id: `sim_${i}_${t.ruleId}`, ruleId: t.ruleId, category: t.category, severity: t.severity,
        message: t.message, recommendationId: t.recommendationId,
        title: t.title, affectedModules: t.affectedModules, estimatedImpact: t.estimatedImpact, actions: t.actions,
        actionTargets: t.actionTargets,
      }));
      return { decisions: [], triggered, recommendations: simDecisions.map((d) => this.formatRecommendation(d)), simulated: true };
    }

    const store = aiGetStore();
    const now = Date.now();
    const decisions = triggered.map((t, i) => ({
      id: `dec_${now}_${i}_${t.ruleId}`,
      ruleId: t.ruleId, category: t.category, severity: t.severity,
      message: t.message, recommendationId: t.recommendationId,
      // Sesi 11 — disimpan di decisionLog kalau rule menyediakan, supaya
      // riwayat (poin 7 kontrak: timestamp/module/reason/result/confidence)
      // tetap utuh dipanggil ulang lewat formatRecommendation() nanti,
      // bukan cuma dihitung sekali saat decide().
      title: t.title, affectedModules: t.affectedModules,
      estimatedImpact: t.estimatedImpact, actions: t.actions, actionTargets: t.actionTargets,
      createdAt: now, outcome: null,
    }));
    store.decisionLog = (store.decisionLog || []).concat(decisions).slice(-500);
    store.lastRunAt = now;
    await aiSave();

    const recommendations = decisions.map((d) => this.formatRecommendation(d));

    if (decisions.length) {
      AIBus.emit('ai:decision-made', { decisions, recommendations });
    }
    return { decisions, triggered, recommendations, simulated: false };
  },

  // ----------------------------------------------------------------------
  // formatRecommendation(decision) — Sesi 11: bentuk output standar dipakai
  // bareng oleh Tahap 5 (Daily Briefing), Tahap 7 (Simulation), dan UI mana
  // pun, supaya semuanya konsumsi 1 bentuk yang sama alih-alih menghitung
  // ulang logic bisnisnya masing-masing. Pure/read-only — tidak menulis
  // store, tidak butuh await (semua input sudah ada di decision).
  // Field yang tidak disediakan rule (affectedModules/estimatedImpact/
  // actions/title) diisi fallback aman, TIDAK error.
  // ----------------------------------------------------------------------
  formatRecommendation(decision) {
    if (!decision || typeof decision !== 'object') return null;
    const rule = this.rules._rules.find((r) => r.id === decision.ruleId);
    const weight = rule ? rule.weight : 5;
    const rec = decision.recommendationId ? this.recommend.getById(decision.recommendationId) : null;
    return {
      id: decision.id,
      ruleId: decision.ruleId || null,
      title: decision.title || (rec && rec.label) || decision.message.slice(0, 60),
      reason: decision.message,
      // Confidence: 0-1, dari weight rule (1-10 -> 0.1-1.0) sebagai proxy
      // sederhana kalau rule tidak menyediakan angka sendiri. BUKAN dari
      // AIDecision.learn (itu async & butuh histori outcome — konsumen yang
      // butuh confidence adaptif tetap bisa panggil learn.getConfidence()
      // terpisah, formatRecommendation() ini murni sync).
      confidence: Math.max(0.1, Math.min(1, weight / 10)),
      priority: AI_PRIORITY_FROM_SEVERITY[decision.severity] || 'MEDIUM',
      affectedModules: decision.affectedModules || [decision.category],
      estimatedImpact: decision.estimatedImpact || {},
      actions: decision.actions || (rec && rec.label ? [rec.label] : []),
      // actionTargets — lihat catatan di rules.evaluate() di atas. TIDAK ada
      // fallback dari `rec` (AIDecision.recommend registry) krn registry itu masih
      // "senyap" (belum ada domain yg register()), jadi apa adanya dari decision saja.
      actionTargets: decision.actionTargets || null,
    };
  },
};

// ---------------------------------------------------------------------------
// Rule Cross Module pertama (TODO.md #1, keputusan produk dikonfirmasi user):
// 'cross-finance-delivery-margin-balance' — peringatan kalau margin rata-rata
// 5 transaksi Cobek terakhir TIPIS (AIContext.snapshot().shop.recentAvgMarginPct)
// BERSAMAAN dgn saldo total akun sedang RENDAH
// (AIContext.snapshot().finance.saldoNow). Ini rule pertama yang benar-benar
// membaca 2+ domain dalam 1 condition() — sebelumnya semua rule domain
// (finance-*/vehicle-*/asset-*/delivery-*) hanya baca domain sendiri.
//
// Ditempatkan di ai-decision-engine.js (bukan tx-list-cashflow.js/
// cobek-pricing.js) krn rule ini bukan milik satu domain tunggal — butuh
// AIContext (ai-core.js) + getter finance + getter shop yang KETIGANYA harus
// sudah di-load. scripts/build.js sudah menjamin urutan ini (ai-core.js/
// ai-decision-engine.js dimuat SETELAH tx-list-cashflow.js & cobek-pricing.js).
//
// Ambang: SENGAJA TIDAK membuat ambang baru — reuse APA ADANYA 2 getter yang
// sudah ada & sudah bisa diatur user lewat Pengaturan > 🤖 AI Asisten:
//   - getAIDeliveryThinMarginThreshold() (cobek-pricing.js, default 10%)
//   - getAIFinanceLowBalanceMultiplier() (tx-list-cashflow.js, default 0.5x)
// Beda dari delivery-thin-margin (baca ctx.payload event 'delivery.created',
// 1 transaksi saja): rule ini baca recentAvgMarginPct (rata-rata 5 transaksi
// terakhir dari AIContext) supaya bisa dievaluasi kapan saja (bukan cuma
// persis saat 1 transaksi baru disimpan), sesuai sifat AIContext.snapshot()
// sendiri (ringkasan state terkini, bukan event sesaat).
// ---------------------------------------------------------------------------

function _crossFinanceDeliveryCheck() {
  if (typeof AIContext === 'undefined' || typeof AIContext.snapshot !== 'function') return { trigger: false };
  const snap = AIContext.snapshot();
  const fin = snap.finance, shop = snap.shop;
  if (!fin || !fin.available || !shop || !shop.available) return { trigger: false };
  if (typeof shop.recentAvgMarginPct !== 'number') return { trigger: false }; // belum cukup histori transaksi Cobek
  if (!fin.expAvgBulanan || fin.expAvgBulanan <= 0) return { trigger: false };
  const marginThreshold = (typeof getAIDeliveryThinMarginThreshold === 'function') ? getAIDeliveryThinMarginThreshold() : 10;
  const balanceMultiplier = (typeof getAIFinanceLowBalanceMultiplier === 'function') ? getAIFinanceLowBalanceMultiplier() : 0.5;
  const marginLow = shop.recentAvgMarginPct < marginThreshold;
  const balanceLow = fin.saldoNow < fin.expAvgBulanan * balanceMultiplier;
  return {
    trigger: marginLow && balanceLow,
    saldoNow: fin.saldoNow,
    expAvgBulanan: fin.expAvgBulanan,
    balanceMultiplier,
    recentAvgMarginPct: shop.recentAvgMarginPct,
    marginThreshold,
  };
}

let _crossModuleAIRulesRegistered = false;
// registerCrossModuleAIRules() — dipanggil sekali saat boot (self-test.js
// init(), SETELAH registerFinanceAIRules()/registerDeliveryAIRules() —
// urutan tidak wajib krn rule ini baca lewat AIContext.snapshot(), bukan
// manggil register*AIRules() domain lain). Idempotent & return false kalau
// AIDecision belum ada, pola sama persis dgn register*AIRules() domain lain.
function registerCrossModuleAIRules() {
  if (_crossModuleAIRulesRegistered) return false;
  if (typeof AIDecision === 'undefined' || !AIDecision.rules || typeof AIDecision.rules.register !== 'function') return false;
  AIDecision.rules.register({
    id: 'cross-finance-delivery-margin-balance',
    category: 'cross',
    severity: 'warning',
    weight: 6,
    cooldownHours: 24,
    description: 'Margin rata-rata transaksi Cobek terakhir tipis (di bawah ambang) BERSAMAAN dgn saldo total akun sedang rendah (AIContext.snapshot()).',
    condition: () => _crossFinanceDeliveryCheck().trigger,
    action: () => {
      const c = _crossFinanceDeliveryCheck();
      const fmt = typeof fmtFull === 'function' ? fmtFull : (n => 'Rp ' + Math.round(n || 0).toLocaleString('id-ID'));
      return { message: `Margin transaksi Cobek belakangan cuma ${c.recentAvgMarginPct.toFixed(1)}% (di bawah ambang ${c.marginThreshold}%), sementara saldo total akun cuma ${fmt(c.saldoNow)}, di bawah ${c.balanceMultiplier}x rata-rata pengeluaran bulanan (${fmt(Math.round(c.expAvgBulanan))}).` };
    },
  });
  _crossModuleAIRulesRegistered = true;
  return true;
}

if (typeof window !== 'undefined') {
  window.AIDecision = AIDecision;
}

// ai-service.js — Smart Delivery Engine, Sesi 2/6: facade tunggal.
//
// Lihat RENCANA-SESI-RINGKAS.md untuk peta 6 sesi. Butuh ai-core.js
// (Sesi 1) & ai-decision-engine.js (di atas, Sesi 2 ini) sudah dimuat
// lebih dulu — lihat urutan di scripts/build.js.
//
// Kenapa 1 file, bukan 5 (ai-daily-briefing.js + ai-health-check.js +
// ai-simulation.js + ai-prompt.js + ai-service.js) — lihat
// RENCANA-SESI-RINGKAS.md bagian "Kenapa dipangkas". AIService adalah
// SATU-SATUNYA pintu masuk yang dipakai UI/modul lain (Sesi 4-6) —
// mereka tidak boleh memanggil AIDecision/AIStore langsung, supaya kalau
// internal berubah nanti, kontrak publik (4 method di bawah) tetap sama.
//
// PENTING (Sesi 2 — masih "senyap"): tidak ada UI, tidak ada wiring
// otomatis. Method di bawah baru "hidup" kalau dipanggil eksplisit oleh
// kode lain (Sesi 4-6). Dengan 0 rule domain terdaftar (lihat catatan di
// ai-decision-engine.js), dailyBriefing()/simulate() akan selalu
// mengembalikan hasil kosong sampai ada modul yang register rule/rekomendasi.

// _aiLastPendingCobekOrder() — Sesi 15 (Tahap 5, Delivery Summary): cari
// transaksi Cobek TERAKHIR yang belum diserahkan/dikirim, buat sumber data
// LogisticsEngine.deliverySummary() di dailyBriefing(). Filter & urutan
// SAMA PERSIS dgn pola yang sudah ada (`D.cobek.filter(c=>c.items &&
// c.delivered===false)` di cobek-order.js #106, sort
// `(b.id||0)-(a.id||0)` di _aiContextShop() ai-core.js) — bukan rumus
// baru. Guard `typeof D==='undefined'` (tidak pernah menyentuh/mengubah D,
// murni baca) — kalau D belum ada atau tidak ada order pending, balik null.
// (Sesi 265, Ownership Sync — AI): TAMBAH filter isCobekOwnershipSelf di
// atas D.cobek (0 logic lama diubah) — pesanan Cobek ber-ownership
// INVESTOR/CUSTOMER/THIRD_PARTY/FAMILY dikecualikan dari Delivery Summary
// AI Daily Briefing, pola sama persis _aiContextShop() (ai-core.js, S265).
// Guard typeof: kalau helper belum dimuat, anggap semua SELF.
function _aiLastPendingCobekOrder() {
  if (typeof D === 'undefined' || !D || !Array.isArray(D.cobek)) return null;
  const cobSelfFilter = typeof isCobekOwnershipSelf === 'function' ? isCobekOwnershipSelf : (() => true);
  const pending = D.cobek
    .filter((c) => c.items && c.delivered === false)
    .filter(cobSelfFilter)
    .sort((a, b) => (b.id || 0) - (a.id || 0));
  return pending[0] || null;
}

// _aiFindDuplicateRuleIds() — Tahap 8 (AI Health Check, TODO.md #3, Duplicate
// Detection). Cek AIDecision.rules.getAll() (array _rules) buat id yang
// muncul lebih dari 1x. Secara normal TIDAK PERNAH terjadi krn
// rules.register() sudah menolak id yang sudah ada (`this._rules.some(r=>
// r.id===rule.id)) return false` di ai-decision-engine.js) — deteksi ini
// murni JARING PENGAMAN kalau suatu saat ada jalur lain yang menambah ke
// _rules tanpa lewat register() (mis. bug refactor), BUKAN mengasumsikan
// bug itu ada sekarang. Murni baca (tidak menulis apa pun).
function _aiFindDuplicateRuleIds() {
  const counts = Object.create(null);
  AIDecision.rules.getAll().forEach((r) => {
    if (!r || typeof r.id !== 'string') return;
    counts[r.id] = (counts[r.id] || 0) + 1;
  });
  return Object.keys(counts).filter((id) => counts[id] > 1);
}

// _aiFindDuplicateRecommendations() — beda kasus dari rule id di atas:
// AIDecision.recommend._map adalah OBJECT keyed by id, jadi id-nya sendiri
// TIDAK MUNGKIN dobel (key object unik by definisi bahasa). Yang dicek di
// sini justru KONTEN-nya: kalau 2+ id BERBEDA terdaftar dgn label+target
// yang PERSIS SAMA, itu indikasi 2 modul domain tidak sengaja mendaftarkan
// rekomendasi yang sama 2x dgn id berbeda (redundan, bukan bug fatal, tapi
// berguna buat dibersihkan). Murni baca (tidak menulis apa pun).
function _aiFindDuplicateRecommendations() {
  const map = AIDecision.recommend.getAll();
  const byContent = Object.create(null);
  Object.keys(map).forEach((id) => {
    const def = map[id] || {};
    const key = JSON.stringify([def.label || '', def.target || null]);
    (byContent[key] = byContent[key] || []).push(id);
  });
  return Object.keys(byContent)
    .map((key) => byContent[key])
    .filter((ids) => ids.length > 1)
    .map((ids) => {
      const def = map[ids[0]] || {};
      return { label: def.label || '', target: def.target || null, ids };
    });
}

// _aiFindDeadRuleIds() — Tahap 8 (AI Health Check, TODO.md #4, Dead Code
// Detection). Cek AIDecision.rules.getAll() buat rule yang `enabled ===
// false` — rule ini TERDAFTAR (lolos validateAIRuleShape + register()) tapi
// TIDAK PERNAH dievaluasi (`rules.evaluate()` skip rule kalau `!rule.enabled`
// di baris paling atas loop-nya, lihat ai-decision-engine.js) — secara
// efektif "kode mati": ada di registry, tapi action()-nya tidak akan pernah
// jalan lewat decide()/simulate() manapun. TIDAK ada API buat mengaktifkan
// balik selain unregister() lalu register() ulang dgn enabled:true — jadi
// hasil ini murni informasional (mis. rule yang sengaja dinonaktifkan
// sementara tapi lupa dihapus/diaktifkan lagi). Murni baca (tidak menulis
// apa pun).
function _aiFindDeadRuleIds() {
  return AIDecision.rules.getAll()
    .filter((r) => r && r.enabled === false)
    .map((r) => r.id);
}

// _aiFindBrokenRecommendationRefs() — Tahap 8 (AI Health Check, TODO.md #4b,
// Broken Reference). Beda dari Dead Code Detection (rule yang tidak pernah
// jalan) — ini soal `recommendationId` yang PERNAH dihasilkan rule (tercatat
// di decisionLog, hasil evaluate() -> action() nyata) tapi TIDAK/TIDAK LAGI
// terdaftar di `AIDecision.recommend` (mis. modul domain yang dulu
// register() rekomendasi itu belum sempat di-load, atau id-nya diganti tanpa
// update rule). Kenapa baca `decisionLog` (histori), BUKAN cek statis semua
// rule: `recommendationId` cuma diketahui dari HASIL `rule.action(ctx)` —
// baru ada setelah rule benar-benar trigger dgn ctx nyata (lihat
// `rules.evaluate()`), tidak bisa dibaca dari definisi rule sebelum
// dijalankan. decisionLog sudah menyimpan histori itu (SATU-SATUNYA
// penulis: `AIDecision.decide()`), jadi dipakai ulang di sini — bukan
// menjalankan ulang rule (yang butuh ctx domain nyata & bisa menandai
// cooldown lagi, tidak cocok utk pemeriksaan read-only). Dedup by
// recommendationId (1 id yang broken dihitung sekali walau muncul di banyak
// decision). Murni baca (tidak menulis apa pun).
function _aiFindBrokenRecommendationRefs() {
  const store = aiGetStore();
  const log = (store && Array.isArray(store.decisionLog)) ? store.decisionLog : [];
  const seen = Object.create(null);
  const broken = [];
  log.forEach((d) => {
    const recId = d && d.recommendationId;
    if (!recId || typeof recId !== 'string' || seen[recId]) return;
    seen[recId] = true;
    if (!AIDecision.recommend.getById(recId)) broken.push(recId);
  });
  return broken;
}

// _aiFindOrphanedStorageKeys() — Tahap 8 (AI Health Check, TODO.md #4d,
// Storage Audit). Cek 2 object di AIStore yang keyed by ruleId —
// `ruleCooldowns` (diisi `_markCooldown()` tiap rule trigger nyata) &
// `learningData` (diisi `recordFeedback()`, lihat ai-decision-engine.js)
// — buat key yang ruleId-nya TIDAK/TIDAK LAGI terdaftar di
// `AIDecision.rules.getAll()`. Ini bisa terjadi krn `rules.unregister(id)`
// HANYA menghapus dari `_rules` (lihat definisinya di
// ai-decision-engine.js), TIDAK PERNAH ikut membersihkan
// `ruleCooldowns`/`learningData` — jadi kalau modul domain yang dulu
// register() sebuah rule kemudian di-refactor/dihapus (unregister()), jejak
// cooldown & data pembelajarannya tetap tertulis selamanya di AIStore
// (storage leak ringan, ukurannya kecil per-entry tapi tidak pernah
// menyusut). Beda dari Dead Code Detection (`_aiFindDeadRuleIds()` di
// atas): itu soal rule yang MASIH terdaftar tapi `enabled:false`, ini
// soal rule yang SUDAH TIDAK terdaftar sama sekali tapi jejaknya masih
// ada di storage. Murni baca/deteksi — TIDAK menghapus entry apa pun
// secara otomatis (keputusan cleanup, mis. apakah histori pembelajaran
// rule lama masih ingin dipertahankan, butuh keputusan produk terpisah).
function _aiFindOrphanedStorageKeys() {
  const store = aiGetStore();
  const registeredIds = new Set(AIDecision.rules.getAll().map((r) => r.id));
  const cooldowns = (store && store.ruleCooldowns) || {};
  const learning = (store && store.learningData) || {};
  return {
    orphanedCooldownRuleIds: Object.keys(cooldowns).filter((id) => !registeredIds.has(id)),
    orphanedLearningDataRuleIds: Object.keys(learning).filter((id) => !registeredIds.has(id)),
  };
}

// AI_REMINDER_DOMAIN_ORDER — urutan prioritas reminder per
// docs/PRODUCT_DECISIONS.md § Reminder Priority (Finance -> Vehicle ->
// Shop -> Asset -> Goal -> LifeOS). Array literal lokal (bukan registry
// baru) krn urutan ini SATU-SATUNYA konsumen sejauh ini (Reminder
// Summary) — kalau nanti ada konsumen lain yang butuh urutan sama,
// baru layak diangkat jadi registry terpisah.
const AI_REMINDER_DOMAIN_ORDER = ['finance', 'vehicle', 'shop', 'asset', 'goal', 'lifeos'];

// _aiReminderAndTargetSummary(context) — Tahap 5 (Daily Briefing, TODO.md
// #8): bangun `reminderSummary` (array per domain, urutan
// AI_REMINDER_DOMAIN_ORDER) & `targetSummary` sekaligus dalam 1 fungsi
// supaya `goalAdapterList(D)` (dipakai KEDUA field) cuma dihitung SEKALI
// per pemanggilan dailyBriefing() — bukan 2x terpisah.
//
// Reminder Summary SENGAJA reuse fungsi condition() rule AI yang SUDAH
// ADA per domain (pola yang sama dipakai `registerFinanceAIRules()` dkk),
// BUKAN menulis ulang logic "apa yang butuh diingatkan" dari nol:
//   - finance -> `context.finance.billsDueCount`/`billsDue30Hari`
//     (AIContext.snapshot(), sudah dihitung sekali di dailyBriefing()
//     lewat computeCashflowForecast() — REUSE hasil yang sudah ada,
//     TIDAK panggil computeCashflowForecast() lagi).
//   - vehicle -> `_vehicleOverdueCheck()` (sparepart-servis.js, dipakai
//     jg oleh rule 'vehicle-service-overdue').
//   - shop -> `_deliveryLowStockCheck()` (cobek-pricing.js, dipakai jg
//     oleh rule delivery low-stock).
//   - asset -> `_assetZakatDueCheck()` (aset.js, dipakai jg oleh rule
//     asset zakat).
//   - goal -> `goalAdapterList(D)` (lifeos/adapters/goal-adapter.js,
//     READ-ONLY — arah baca AI->LifeOS sudah diizinkan eksplisit di
//     docs/LIFEOS_SCOPE.md), reminder = goal yang progressPct<100.
//   - lifeos -> `todayAdapterList(D)` (lifeos/adapters/today-adapter.js),
//     jumlah item "hari ini" yang masih pending.
// Tiap domain guard `typeof fn==='function'` (pola SAMA PERSIS dgn 4
// builder `_aiContext*` di ai-core.js) — domain yang modulnya belum
// di-load `available:false, count:0`, TIDAK throw, TIDAK menebak data.
//
// Target Summary = `goalAdapterList(D)` APA ADANYA (list lengkap, tidak
// difilter) + `incompleteCount` (turunan ringan dari list yang sama,
// BUKAN rumus baru). `null` kalau `goalAdapterList` belum di-load ATAU
// `D` belum ada.
function _aiReminderAndTargetSummary(context) {
  const hasD = typeof D !== 'undefined' && D;
  const entries = {};

  const fin = context && context.finance;
  entries.finance = (fin && fin.available)
    ? { domain: 'finance', available: true, count: fin.billsDueCount || 0, detail: { billsDue30Hari: fin.billsDue30Hari, billsDueCount: fin.billsDueCount } }
    : { domain: 'finance', available: false, count: 0, detail: null };

  const vehicleCheck = (typeof _vehicleOverdueCheck === 'function') ? _vehicleOverdueCheck() : null;
  entries.vehicle = vehicleCheck
    ? { domain: 'vehicle', available: true, count: vehicleCheck.overdue.length, items: vehicleCheck.overdue.slice(0, 3) }
    : { domain: 'vehicle', available: false, count: 0, items: [] };

  const shopCheck = (typeof _deliveryLowStockCheck === 'function') ? _deliveryLowStockCheck() : null;
  entries.shop = shopCheck
    ? { domain: 'shop', available: true, count: shopCheck.low.length, items: shopCheck.low.slice(0, 3).map((p) => ({ id: p.id, name: p.name, stock: p.stock })) }
    : { domain: 'shop', available: false, count: 0, items: [] };

  const assetCheck = (typeof _assetZakatDueCheck === 'function') ? _assetZakatDueCheck() : null;
  entries.asset = (assetCheck && assetCheck.trigger)
    ? { domain: 'asset', available: true, count: assetCheck.jumlah, detail: { totalZakat: assetCheck.totalZakat, minThreshold: assetCheck.minThreshold } }
    : { domain: 'asset', available: !!assetCheck, count: 0, detail: null };

  const goalList = (typeof goalAdapterList === 'function' && hasD) ? goalAdapterList(D) : null;
  const incompleteGoals = goalList ? goalList.filter((g) => g.progressPct < 100) : [];
  entries.goal = goalList
    ? { domain: 'goal', available: true, count: incompleteGoals.length, items: incompleteGoals.slice(0, 3).map((g) => ({ id: g.id, name: g.name, progressPct: g.progressPct })) }
    : { domain: 'goal', available: false, count: 0, items: [] };

  const todayList = (typeof todayAdapterList === 'function' && hasD) ? todayAdapterList(D) : null;
  entries.lifeos = todayList
    ? { domain: 'lifeos', available: true, count: todayList.length, items: todayList.slice(0, 3).map((i) => ({ id: i.id, label: i.label })) }
    : { domain: 'lifeos', available: false, count: 0, items: [] };

  const reminderSummary = AI_REMINDER_DOMAIN_ORDER.map((d) => entries[d]);
  const targetSummary = goalList
    ? { count: goalList.length, incompleteCount: incompleteGoals.length, items: goalList }
    : null;

  return { reminderSummary, targetSummary };
}

const AIService = {
  /** dailyBriefing({limit}) — ringkasan harian: snapshot context + N
   * keputusan/rekomendasi terakhir dari decisionLog, rekomendasi
   * di-resolve ke { label, target } lewat AIDecision.recommend. TIDAK
   * memicu evaluasi rule baru (itu tugas decide(), dipanggil terpisah
   * oleh titik wiring Sesi 6) — briefing murni MEMBACA hasil yang sudah
   * ada, supaya bisa dipanggil sesering apa pun tanpa efek samping.
   *
   * Sesi 15 (Tahap 5 — Delivery Summary): field `deliverySummary` diisi
   * dari `LogisticsEngine.deliverySummary()`, sumber datanya transaksi
   * Cobek TERAKHIR yang belum diserahkan/dikirim (`_aiLastPendingCobekOrder()`
   * di atas). HANYA `totalPenjualan`/`diskon` yang diisi dari order —
   * field lain (kendaraan/jarak/berat/volume/biaya operasional) TIDAK ada
   * di data order Cobek sama sekali, jadi SENGAJA tidak diisi/ditebak
   * (LogisticsEngine sendiri sudah fallback aman ke 0 untuk parameter yang
   * kosong, TIDAK throw — lihat komentar `deliverySummary()` di
   * logistics-engine.js). Konsekuensinya: `capacity`/`estimasiBBM`/`ongkir`
   * di hasil ini akan 0/AMAN selama belum ada input kendaraan & rute
   * manual — HANYA `profit.totalPenjualan`/`profit.diskon` yang
   * merepresentasikan data nyata. Kalau tidak ada order pending ATAU
   * LogisticsEngine belum di-load, `deliverySummary` balik `null` (TIDAK
   * ada order palsu/di-reka-reka).
   *
   * Sesi 23 (Tahap 5 — Financial Summary, ROADMAP.md "Financial Summary
   * (terpisah)"): field `financialSummary` diisi APA ADANYA dari
   * `context.finance` (AIContext.snapshot(), sudah ada sejak Sesi 13 —
   * reuse computeCashflowForecast() TANPA rumus baru) — cuma diangkat jadi
   * field TOP-LEVEL terpisah (bukan nested-only di `context.finance`),
   * pola sama persis dgn `deliverySummary`/`recommendations` yang juga
   * diangkat ke top-level dari sumber yang sudah ada. `null` kalau domain
   * finance belum tersedia (`context.finance.available===false`, mis.
   * tx-list-cashflow.js belum di-load), TIDAK menebak data.
   *
   * Sesi 31 (Tahap 5 — Reminder Summary & Target Summary, TODO.md #8,
   * struktur final per `docs/PRODUCT_DECISIONS.md`): field
   * `reminderSummary` (array 6 entri, urutan `AI_REMINDER_DOMAIN_ORDER` —
   * Finance -> Vehicle -> Shop -> Asset -> Goal -> LifeOS, tiap entri
   * `{domain, available, count, items?/detail?}`) & `targetSummary`
   * (`{count, incompleteCount, items}` dari `goalAdapterList(D)` APA
   * ADANYA, `null` kalau belum tersedia). Keduanya dibangun 1x lewat
   * `_aiReminderAndTargetSummary()` di atas (lihat komentarnya utk daftar
   * lengkap fungsi yang di-reuse per domain) — struktur "5 bagian Daily
   * Briefing" (Finance/Delivery/Reminder/Target/Recommendation Summary)
   * SEKARANG LENGKAP semua. */
  async dailyBriefing({ limit = 10 } = {}) {
    await aiEnsureLoaded();
    const store = aiGetStore();
    const context = AIContext.snapshot();
    const recentDecisions = (store.decisionLog || [])
      .slice()
      .sort((a, b) => b.createdAt - a.createdAt)
      .slice(0, limit)
      .map((d) => Object.assign({}, d, {
        recommendation: d.recommendationId ? AIDecision.recommend.getById(d.recommendationId) : null,
      }));

    const lastPendingOrder = _aiLastPendingCobekOrder();
    const deliverySummary = (lastPendingOrder
      && typeof LogisticsEngine !== 'undefined'
      && typeof LogisticsEngine.deliverySummary === 'function')
      ? Object.assign(
        { sourceOrderId: lastPendingOrder.id },
        LogisticsEngine.deliverySummary({
          totalPenjualan: lastPendingOrder.total,
          diskon: lastPendingOrder.diskon,
        }),
      )
      : null;

    const financialSummary = (context.finance && context.finance.available)
      ? context.finance
      : null;

    // Sesi 31 (Tahap 5 — Reminder Summary & Target Summary, TODO.md #8,
    // struktur final per docs/PRODUCT_DECISIONS.md § Daily Briefing/§
    // Reminder Priority): reuse `_aiReminderAndTargetSummary()` di atas
    // (1 fungsi, 1 pemanggilan `goalAdapterList(D)`, bukan duplikasi).
    // Dibungkus try/catch terpisah supaya kalau ADA yang gagal tak
    // terduga, 2 field ini balik null (informasional) TANPA
    // menjatuhkan dailyBriefing() secara keseluruhan (field lain, mis.
    // financialSummary/deliverySummary, tetap terisi normal) — pola sama
    // dgn guard try/catch di healthCheck().
    let reminderSummary = null;
    let targetSummary = null;
    try {
      const rt = _aiReminderAndTargetSummary(context);
      reminderSummary = rt.reminderSummary;
      targetSummary = rt.targetSummary;
    } catch (e) {
      console.warn('[AIService] dailyBriefing(): reminderSummary/targetSummary gagal dihitung:', e);
    }

    return {
      generatedAt: new Date().toISOString(),
      context,
      lastRunAt: store.lastRunAt || null,
      recentDecisions,
      deliverySummary,
      financialSummary,
      reminderSummary,
      targetSummary,
      // Sesi 11 — bentuk standar (id/title/reason/confidence/priority/
      // affectedModules/estimatedImpact/actions), sama kontrak dgn
      // decide().recommendations & simulate(), supaya UI briefing dan
      // UI What-If konsumsi struktur yang identik. `recentDecisions` di
      // atas TETAP ada apa adanya (backward compatible, tidak dihapus).
      recommendations: recentDecisions.map((d) => AIDecision.formatRecommendation(d)),
    };
  },

  /** healthCheck() — pemeriksaan integritas ringan, non-invasif (TIDAK
   * menulis apa pun ke store). Dipakai buat diagnostik manual (mis. lewat
   * console) atau widget "Status AI" di sesi UI mendatang, supaya bisa
   * cepat tahu kalau ada modul yang lupa didaftarkan (rules kosong terus,
   * padahal Sesi 4-5 seharusnya sudah register).
   *
   * TODO.md #3 (Tahap 8, Duplicate Detection): field `duplicateRuleIds`
   * (id rule yang muncul >1x di `AIDecision.rules.getAll()` — normalnya
   * SELALU kosong krn `rules.register()` sendiri sudah menolak id
   * duplikat, murni jaring pengaman) & `duplicateRecommendations`
   * (kelompok id `AIDecision.recommend` berbeda yang label+target-nya
   * PERSIS SAMA — indikasi rekomendasi didaftarkan redundan 2x dgn id
   * beda). Keduanya informasional (TIDAK menjatuhkan `ok` ke false),
   * sama seperti `rulesRegistered`/`recommendationsRegistered` — hanya
   * error struktural (lihat blok try/catch di bawah) yang menjatuhkan
   * `ok`.
   *
   * TODO.md #4 (Tahap 8, Dead Code Detection): field `deadRuleIds` — id
   * rule yang terdaftar tapi `enabled===false`, artinya TIDAK PERNAH
   * dievaluasi `rules.evaluate()` (lihat `_aiFindDeadRuleIds()` di atas).
   * Sama pola dgn 2 field duplikat di atas: informasional, TIDAK
   * menjatuhkan `ok`.
   *
   * TODO.md #4b (Tahap 8, Broken Reference): field
   * `brokenRecommendationRefs` — `recommendationId` yang PERNAH tercatat
   * di `decisionLog` (hasil rule trigger nyata) tapi TIDAK/TIDAK LAGI
   * terdaftar di `AIDecision.recommend` (lihat
   * `_aiFindBrokenRecommendationRefs()` di atas). Sama pola dgn 3 field
   * lain: informasional, TIDAK menjatuhkan `ok`.
   *
   * TODO.md #4d (Tahap 8, Storage Audit): field `orphanedStorageKeys` —
   * `{ orphanedCooldownRuleIds, orphanedLearningDataRuleIds }`, ruleId di
   * `AIStore.ruleCooldowns`/`AIStore.learningData` yang rule-nya SUDAH
   * di-unregister() (lihat `_aiFindOrphanedStorageKeys()` di atas). Sama
   * pola dgn 4 field lain: informasional, TIDAK menjatuhkan `ok`.
   *
   * TODO.md #4e (Tahap 8, Performance Check): field `performance` — durasi
   * eksekusi (ms, `Date.now()` lewat `_aiMeasureMs()`/`_aiMeasureMsAsync()`
   * di ai-core.js) dari 5 fungsi yang jadi scope Performance Check per
   * `docs/PRODUCT_DECISIONS.md` § Performance Check: Context Collector
   * (`AIContext.snapshot()`), Rule Evaluation (`AIDecision.rules.evaluate()`,
   * dipanggil dgn `{simulated:true}` supaya TIDAK menandai cooldown nyata —
   * murni pengukuran, pola sama dgn `simulate()`), Recommendation
   * (`AIDecision.formatRecommendation()`, dipanggil dgn decision TERAKHIR
   * dari `decisionLog` kalau ada, atau decision sintetik minimal kalau
   * belum pernah ada decide() sama sekali — supaya tetap terukur walau
   * historinya kosong), Daily Briefing (`this.dailyBriefing({limit:1})` —
   * limit kecil khusus di jalur pengukuran ini supaya health check tetap
   * ringan, TIDAK mengubah default `dailyBriefing()` publik) & Simulation
   * (`this.simulate({})`). Kelimanya read-only (tidak ada yang menulis ke
   * store — lihat catatan masing-masing method), jadi aman dipanggil
   * berulang dari health check tanpa efek samping. Sama pola dgn 5 field
   * lain di atas: informasional, TIDAK menjatuhkan `ok` (hanya
   * `performanceError` yang dicatat kalau blok ini gagal total). */
  async healthCheck() {
    const checks = {
      busReady: typeof AIBus !== 'undefined' && typeof AIBus.emit === 'function',
      storeReady: false,
      rulesRegistered: 0,
      recommendationsRegistered: 0,
      duplicateRuleIds: [],
      duplicateRecommendations: [],
      deadRuleIds: [],
      brokenRecommendationRefs: [],
      orphanedStorageKeys: { orphanedCooldownRuleIds: [], orphanedLearningDataRuleIds: [] },
      contextReady: false,
      performance: {
        contextCollectorMs: null,
        ruleEvaluationMs: null,
        recommendationMs: null,
        dailyBriefingMs: null,
        simulationMs: null,
      },
    };
    let ok = checks.busReady;

    try {
      await aiEnsureLoaded();
      checks.storeReady = aiGetStore() != null;
      ok = ok && checks.storeReady;
    } catch (e) {
      checks.storeError = String((e && e.message) || e);
      ok = false;
    }

    try {
      checks.rulesRegistered = AIDecision.rules.getAll().length;
      checks.recommendationsRegistered = Object.keys(AIDecision.recommend.getAll()).length;
      checks.duplicateRuleIds = _aiFindDuplicateRuleIds();
      checks.duplicateRecommendations = _aiFindDuplicateRecommendations();
      checks.deadRuleIds = _aiFindDeadRuleIds();
      checks.brokenRecommendationRefs = _aiFindBrokenRecommendationRefs();
      checks.orphanedStorageKeys = _aiFindOrphanedStorageKeys();
    } catch (e) {
      checks.decisionEngineError = String((e && e.message) || e);
      ok = false;
    }

    let contextSnapshotForPerf = null;
    try {
      const timed = _aiMeasureMs(() => AIContext.snapshot());
      contextSnapshotForPerf = timed.result;
      checks.contextReady = !!(timed.result && timed.result.generatedAt);
      checks.performance.contextCollectorMs = timed.ms;
    } catch (e) {
      checks.contextError = String((e && e.message) || e);
      ok = false;
    }

    try {
      checks.performance.ruleEvaluationMs = _aiMeasureMs(
        () => AIDecision.rules.evaluate(Object.assign({}, contextSnapshotForPerf, { simulated: true })),
      ).ms;

      const store = aiGetStore();
      const log = (store && Array.isArray(store.decisionLog)) ? store.decisionLog : [];
      const lastDecision = log.length ? log[log.length - 1] : {
        id: 'perf-check', ruleId: null, severity: 'info', message: '', recommendationId: null,
      };
      checks.performance.recommendationMs = _aiMeasureMs(
        () => AIDecision.formatRecommendation(lastDecision),
      ).ms;
    } catch (e) {
      checks.performanceError = String((e && e.message) || e);
    }

    try {
      checks.performance.dailyBriefingMs = (await _aiMeasureMsAsync(
        () => this.dailyBriefing({ limit: 1 }),
      )).ms;
      checks.performance.simulationMs = (await _aiMeasureMsAsync(
        () => this.simulate({}),
      )).ms;
    } catch (e) {
      checks.performanceError = String((e && e.message) || e);
    }

    return { ok, checkedAt: new Date().toISOString(), checks };
  },

  /** simulate(ctx) — jalankan rule evaluation What-If TANPA menulis apa
   * pun ke store (tidak ada decisionLog baru, tidak ada cooldown
   * tertandai) — pola sama dgn EIE ScenarioSimulator. Berguna buat UI
   * mendatang yang mau menunjukkan "kalau kondisi X, AI akan
   * merekomendasikan apa" tanpa efek samping nyata.
   *
   * Sesi 15 (Tahap 7 — Profit Simulation): kalau ctx.profit diisi (bentuk
   * sama dgn parameter LogisticsEngine.profitCalculator — totalPenjualan/
   * diskon/ongkir/biayaBBM/biayaOperasional), hasilnya ikut disertakan di
   * field `profitSimulation`, murni TAMBAHAN read-only (LogisticsEngine
   * juga tidak menulis apa pun). Kalau ctx.profit tidak diisi ATAU
   * LogisticsEngine belum di-load (mis. sandbox test yang tidak
   * memuatnya), `profitSimulation` balik `null` — kontrak lama
   * (decisions/triggered/recommendations/simulated) TIDAK berubah sama
   * sekali, jadi pemanggil existing (dailyBriefing lewat rule biasa, test
   * lama) tidak perlu tahu field baru ini.
   *
   * Sesi 33 (Tahap 7 — Delivery Simulation, TARGET sesi ini): field baru
   * `deliverySimulation` — reuse `LogisticsEngine.deliverySummary()` (§9,
   * orkestrator Tahap 3 yang SAMA PERSIS dipakai `dailyBriefing()`) supaya
   * simulasi bisa jalan utk 4 skenario What-If sekaligus dalam SATU
   * pemanggilan: perubahan harga BBM (`hargaBBM`), ongkir
   * (`jarak`/`biayaPerKm`/`beratKg`/`volumeM3`/dst — parameter
   * `smartOngkir()` yg dipanggil `deliverySummary()` di dalamnya),
   * margin (`marginPct`), & profit (`totalPenjualan`/`diskon`, dihitung
   * `deliverySummary()` lewat `profitCalculator()` internal kalau
   * `totalPenjualan` terisi) — TIDAK ada rumus/engine baru, murni
   * parameter berbeda ke fungsi yang sudah ada.
   *
   * "Data nyata" (sesuai target sesi ini): baseline `totalPenjualan`/
   * `diskon` diambil dari order Cobek pending TERAKHIR (reuse
   * `_aiLastPendingCobekOrder()`, sumber SAMA PERSIS dgn
   * `dailyBriefing().deliverySummary`, BUKAN helper baru), lalu
   * `ctx.delivery` (kalau dikasih) di-timpa di atas baseline itu — jadi
   * pemanggil bisa nguji "kalau BBM naik jadi Rp X" atau "kalau margin
   * turun jadi Y%" TERHADAP data order nyata yang sedang berjalan, tanpa
   * perlu isi ulang totalPenjualan/diskon dari nol. Kalau tidak ada order
   * pending SAMA SEKALI, `ctx.delivery` sendiri masih bisa dipakai berdiri
   * sendiri (murni skenario manual, sama seperti `ctx.profit`). Kalau
   * keduanya kosong ATAU LogisticsEngine belum di-load, `deliverySimulation`
   * balik `null` (tidak menebak data) — kontrak lama TIDAK berubah. */
  async simulate(ctx = {}) {
    const result = await AIDecision.decide(Object.assign({}, ctx, { simulated: true }));
    result.profitSimulation = (ctx.profit
      && typeof LogisticsEngine !== 'undefined'
      && typeof LogisticsEngine.profitCalculator === 'function')
      ? LogisticsEngine.profitCalculator(ctx.profit)
      : null;

    const lastPendingOrder = _aiLastPendingCobekOrder();
    const deliveryBaseline = lastPendingOrder
      ? { totalPenjualan: lastPendingOrder.total, diskon: lastPendingOrder.diskon }
      : null;
    const deliveryParams = (deliveryBaseline || ctx.delivery)
      ? Object.assign({}, deliveryBaseline, ctx.delivery)
      : null;
    result.deliverySimulation = (deliveryParams
      && typeof LogisticsEngine !== 'undefined'
      && typeof LogisticsEngine.deliverySummary === 'function')
      ? Object.assign(
        lastPendingOrder ? { sourceOrderId: lastPendingOrder.id } : {},
        LogisticsEngine.deliverySummary(deliveryParams),
      )
      : null;

    return result;
  },

  /** simulateScenarios(scenarios) — builder skenario TERSTRUKTUR (Tahap 7,
   * TARGET Sesi 45): jalankan BEBERAPA skenario What-If sekaligus dalam
   * SATU pemanggilan, masing-masing diberi LABEL eksplisit — beda dari
   * `simulate(ctx)` polos yang cuma menjalankan SATU ctx ad-hoc tanpa
   * nama/struktur (itu sebabnya `ROADMAP.md` menandai "Scenario Engine"
   * masih 🟡 walau What-If/Profit/Delivery Simulation sudah ✅).
   *
   * Sengaja MURNI TEKNIS — pembungkus terstruktur di atas `simulate()`
   * yang sudah ada, BUKAN kumpulan preset skenario bisnis baru yang
   * ditebak. Nilai BBM/margin/ongkir/dst SEPENUHNYA datang dari
   * pemanggil (persis seperti `ctx.profit`/`ctx.delivery` di
   * `simulate()`) — jadi TIDAK butuh keputusan produk soal skenario
   * spesifik apa yang "benar" utk app ini (beda dgn misal menentukan
   * "skenario BBM naik 20%" yg butuh angka bisnis nyata).
   *
   * Bentuk input FLEKSIBEL, 2 cara (biar backward-friendly dgn ctx polos
   * yang sudah biasa dipakai `simulate()`):
   * - `{name, ctx}` — cara TERSTRUKTUR, name dipakai apa adanya.
   * - ctx polos (tanpa properti `name`/`ctx`) — name di-default
   *   `"Skenario 1"`/`"Skenario 2"`/dst berdasar urutan index.
   *
   * `simulate(ctx)` DIPANGGIL APA ADANYA per skenario (TIDAK ada
   * rule/engine baru, kontrak lama `simulate()` sama sekali tidak
   * berubah) — method baru ini murni ORKESTRASI berulang + pelabelan.
   * Error di 1 skenario DITANGKAP per-item (field `error`, `result:null`)
   * supaya tidak menjatuhkan skenario lain dalam batch yang sama. Input
   * bukan array/array kosong balik `[]`, TIDAK throw. */
  async simulateScenarios(scenarios) {
    if (!Array.isArray(scenarios) || !scenarios.length) return [];
    const results = [];
    for (let i = 0; i < scenarios.length; i += 1) {
      const raw = scenarios[i];
      const isStructured = raw && typeof raw === 'object'
        && (Object.prototype.hasOwnProperty.call(raw, 'name')
          || Object.prototype.hasOwnProperty.call(raw, 'ctx'));
      const name = (isStructured && typeof raw.name === 'string' && raw.name.trim())
        ? raw.name.trim()
        : `Skenario ${i + 1}`;
      const ctx = isStructured ? (raw.ctx || {}) : (raw || {});
      try {
        // eslint-disable-next-line no-await-in-loop -- skenario dijalankan
        // berurutan dgn sengaja (bukan Promise.all) supaya urutan hasil di
        // `results` PERSIS sama dgn urutan input, gampang dipetakan UI.
        const result = await this.simulate(ctx);
        results.push({ name, ctx, result, error: null });
      } catch (e) {
        results.push({ name, ctx, result: null, error: String((e && e.message) || e) });
      }
    }
    return results;
  },

  /** buildPrompt(purpose, extra) — rangkai teks prompt siap pakai buat
   * pemanggilan LLM di masa depan (belum ada pemanggilan LLM di file ini
   * sama sekali — murni penyusun teks). Prinsip sama dgn catatan di
   * economic-intelligence/engine/insight-generator.js: LLM TIDAK PERNAH
   * menggantikan rule engine untuk angka/keputusan — prompt ini hanya
   * dipakai kalau suatu saat ada lapisan yang MERANGKAI BAHASA dari hasil
   * yang sudah dihitung rule engine, bukan untuk membiarkan LLM
   * memutuskan sendiri. */
  async buildPrompt(purpose, extra = {}) {
    const briefing = await this.dailyBriefing({ limit: 5 });
    const lines = [
      `Tujuan: ${typeof purpose === 'string' && purpose.trim() ? purpose.trim() : '(tidak ditentukan)'}`,
      `Waktu: ${briefing.generatedAt}`,
      `Jumlah keputusan AI terbaru: ${briefing.recentDecisions.length}`,
    ];
    briefing.recentDecisions.forEach((d, i) => {
      lines.push(`${i + 1}. [${d.severity}] ${d.message}`);
    });
    if (extra && typeof extra === 'object') {
      Object.keys(extra).forEach((key) => {
        lines.push(`${key}: ${JSON.stringify(extra[key])}`);
      });
    }
    return lines.join('\n');
  },
  /** wireEvents() — Sesi 6: satu-satunya titik yang menyambungkan event
   * bisnis ('finance.updated','asset.updated','vehicle.updated',
   * 'delivery.created') ke AIDecision.decide(). Dipanggil SEKALI saat
   * app boot (lihat init() di self-test.js). Sengaja idempotent (guard
   * _wired) supaya aman kalau termanggil dobel. TIDAK di-debounce dgn
   * sengaja (setTimeout tidak reliable di semua konteks test/sandbox) —
   * decide() sendiri murah (baca D + rule evaluation ringan), jadi
   * dipanggil langsung tiap event tanpa delay tambahan. */
  _wired: false,
  wireEvents() {
    if (this._wired) return;
    if (typeof AIBus === 'undefined' || typeof AIBus.on !== 'function') return;
    const handle = (eventName) => (payload) => {
      AIDecision.decide({ event: eventName, payload }).catch((e) => {
        console.warn('[AIService] decide() gagal untuk event "' + eventName + '":', e);
      });
    };
    ['finance.updated', 'asset.updated', 'vehicle.updated', 'delivery.created'].forEach((evt) => {
      AIBus.on(evt, handle(evt));
    });
    this._wired = true;
  },
};

if (typeof window !== 'undefined') {
  window.AIService = AIService;
}

// logistics-engine.js — Smart Delivery Engine, Sesi 3/6: mesin hitung logistik.
//
// Lihat RENCANA-SESI-RINGKAS.md untuk peta 6 sesi. Sesi ini TIDAK butuh
// ai-core.js/ai-decision-engine.js/ai-service.js (Sesi 1-2) sama sekali —
// murni fungsi hitung berbasis D & rumus yang SUDAH ADA (OngkirCalc di
// cobek-pricing.js, PriceReko di file yang sama, estimateRpPerKm di
// vehicle-core.js). Baru dipakai bareng AI di Sesi 6 (wiring).
//
// Kenapa 1 file, bukan 6 (logistics-storage.js + logistics-route.js +
// logistics-load.js + logistics-fuel.js + logistics-pricing.js +
// logistics-engine.js) — lihat RENCANA-SESI-RINGKAS.md bagian "Kenapa
// dipangkas". TIDAK ADA storage sendiri di sini (beda dari AIStore Sesi 1):
// engine ini sengaja stateless/pure — semua hasil dihitung ulang dari
// parameter yang dikasih pemanggil + baca D read-only, TIDAK ada yang
// dipersist ke IndexedDB oleh file ini. Kalau nanti (Sesi 4+) hasil
// LogisticsEngine perlu disimpan (mis. jadi rekomendasi AI), itu lewat
// AIStore Sesi 1 (AIDecision.recommend / dst), bukan storage baru di sini.
//
// ATURAN WAJIB (sama seperti ai-core.js):
// - Tidak pernah menyentuh D. Tidak ada property baru di D, tidak ada
//   perubahan struktur D sedikit pun — HANYA membaca (mis. D.vehicles lewat
//   estimateRpPerKm()).
// - Tidak pernah memanggil save().
// - Tidak duplikat rumus OngkirCalc/PriceReko — SELALU panggil fungsi
//   aslinya (OngkirCalc.leg, PriceReko.roundNice, estimateRpPerKm), supaya
//   kalau rumus itu berubah di kw190/kw191, hasil di sini otomatis ikut
//   berubah juga (satu sumber kebenaran).
// - TIDAK menyentuh DOM sama sekali (beda dari OngkirCalc/PriceReko yang
//   baca document.getElementById(...) langsung) — semua input lewat
//   parameter object, supaya bisa dites murni & dipakai dari mana saja
//   (mis. rule AI di Sesi 4-5) tanpa perlu modal/form terbuka dulu.

const LogisticsEngine = {
  // ------------------------------------------------------------------------
  // route(params) — biaya angkut/pcs dari 2 etape (Ambil ke Produsen +
  // opsional Pekalongan->Rumah Konsumen), rumus PERSIS OngkirCalc.leg() di
  // cobek-pricing.js (kw190/kw191-ongkir-jarak), cuma dipanggil dgn
  // parameter murni (bukan baca #ongkirKmProdusen dkk dari DOM).
  // ------------------------------------------------------------------------
  route({ kmProdusen, biayaPerKmProdusen, kmKonsumen, biayaPerKmKonsumen, metode, pcs } = {}) {
    const m = metode === 'ambil' ? 'ambil' : 'antar'; // default sama seperti OngkirCalc._metode
    const legProdusen = OngkirCalc.leg(biayaPerKmProdusen, kmProdusen, pcs);
    const legKonsumen = m === 'antar' ? OngkirCalc.leg(biayaPerKmKonsumen, kmKonsumen, pcs) : 0;
    const totalPerPcs = legProdusen + legKonsumen;
    return {
      metode: m,
      pcs: parseFloat(pcs) || 0,
      legProdusen,
      legKonsumen,
      totalPerPcs,
    };
  },

  // ------------------------------------------------------------------------
  // fuel(vehicleId) — bungkus estimateRpPerKm() (vehicle-core.js) jadi
  // bentuk konsisten & aman dipanggil walau fungsinya belum ter-load
  // (mis. dari test yang cuma load file ini sendirian) — return null kalau
  // fungsi tidak ada ATAU histori BBM kendaraan itu belum cukup, TIDAK throw.
  // ------------------------------------------------------------------------
  fuel(vehicleId) {
    if (typeof estimateRpPerKm !== 'function') return null;
    const est = estimateRpPerKm(vehicleId);
    if (!est) return null;
    return {
      vehicleId,
      rpPerKm: est.rpPerKm,
      kmPerLiter: est.kmPerLiter,
      avgHargaPerLiter: est.avgHarga,
    };
  },

  // ------------------------------------------------------------------------
  // load(params) — dari total pcs yang mau dikirim & kapasitas angkut sekali
  // jalan, hitung berapa kali rit (trip) dibutuhkan & rata-rata pcs/rit.
  // Kapasitas SENGAJA jadi parameter (bukan dibaca dari D.vehicles), karena
  // D.vehicles belum punya field kapasitas muat sama sekali (lihat catatan
  // "tidak menyentuh D" di atas) — pemanggil (Sesi 4+, mis. UI produk Shop)
  // yang menentukan angka kapasitas, entah dari input manual atau field baru
  // yang ditambahkan belakangan di modul lain.
  // ------------------------------------------------------------------------
  load({ totalPcs, capacityPerTrip } = {}) {
    const total = Math.max(0, parseFloat(totalPcs) || 0);
    const cap = Math.max(1, Math.floor(parseFloat(capacityPerTrip)) || 1);
    const trips = total > 0 ? Math.ceil(total / cap) : 0;
    return {
      totalPcs: total,
      capacityPerTrip: cap,
      trips,
      pcsPerTrip: trips > 0 ? Math.ceil(total / trips) : 0,
    };
  },

  // ------------------------------------------------------------------------
  // price(params) — rekomendasi harga jual dari modal+transport+margin,
  // rumus PERSIS PriceReko.calc()/roundNice() di cobek-pricing.js, cuma
  // parameter murni (bukan baca #pBeli/#prkTransport/#prkMargin dari DOM).
  // ------------------------------------------------------------------------
  price({ modal, transport, marginPct } = {}) {
    const modalNum = parseFloat(modal) || 0;
    const transportNum = parseFloat(transport) || 0;
    const marginNum = parseFloat(marginPct) || 0;
    const base = modalNum + transportNum;
    const raw = base * (1 + marginNum / 100);
    const result = (typeof PriceReko !== 'undefined' && typeof PriceReko.roundNice === 'function')
      ? PriceReko.roundNice(raw)
      : Math.round(raw);
    return { modal: modalNum, transport: transportNum, marginPct: marginNum, base, result };
  },

  // ------------------------------------------------------------------------
  // optimizeRoute({stops, biayaPerKm, vehicleId, pcs}) — urutkan banyak
  // pelanggan (stops) jadi rute nearest-neighbor sederhana (diurutkan dari
  // km terdekat ke terjauh dari titik ambil/gudang), lalu hitung total
  // KM, total ongkir (pakai route() per etape, rumus SAMA persis dgn
  // OngkirCalc.leg(), bukan rumus baru), estimasi BBM (fuel()), & profit
  // kasar (totalOngkir - totalBiayaBBM) kalau vehicleId dikasih. Setiap
  // `stop` minimal punya {name, km}; pcs per stop opsional (default 1).
  // SENGAJA nearest-neighbor by km (bukan TSP/lat-lng) — D.customers TIDAK
  // punya koordinat, jadi ini pendekatan paling jujur dari data yg ADA,
  // bukan tebakan geografis.
  // ------------------------------------------------------------------------
  optimizeRoute({ stops, biayaPerKm, vehicleId } = {}) {
    const list = Array.isArray(stops) ? stops.filter((s) => s && isFinite(parseFloat(s.km))) : [];
    if (!list.length) return { ok: false, reason: 'Tidak ada stop dengan km valid', order: [], totalKm: 0 };

    const ordered = list
      .map((s) => ({
        name: s.name || '(tanpa nama)',
        km: Math.max(0, parseFloat(s.km) || 0),
        pcs: Math.max(0, parseFloat(s.pcs) || 1),
      }))
      .sort((a, b) => a.km - b.km);

    const rpKm = Math.max(0, parseFloat(biayaPerKm) || 0);
    let totalKm = 0;
    let totalOngkir = 0;
    const order = ordered.map((s, i) => {
      // Jarak leg ini = selisih km dari stop sebelumnya (rute menuju
      // makin jauh), stop pertama = km dari titik awal.
      const legKm = i === 0 ? s.km : Math.max(0, s.km - ordered[i - 1].km);
      const legOngkir = (typeof OngkirCalc !== 'undefined' && typeof OngkirCalc.leg === 'function')
        ? OngkirCalc.leg(rpKm, legKm, s.pcs)
        : legKm * rpKm * s.pcs;
      totalKm += legKm;
      totalOngkir += legOngkir;
      return { urutan: i + 1, name: s.name, km: s.km, legKm, pcs: s.pcs, legOngkir };
    });

    const fuel = vehicleId ? this.fuel(vehicleId) : null;
    const totalBiayaBBM = fuel ? Math.round(fuel.rpPerKm * totalKm) : null;
    const profitKasar = totalBiayaBBM !== null ? Math.round(totalOngkir - totalBiayaBBM) : null;

    return {
      ok: true,
      order,
      totalKm,
      totalOngkir: Math.round(totalOngkir),
      fuel,
      totalBiayaBBM,
      profitKasar,
    };
  },

  // ------------------------------------------------------------------------
  // plan(ctx) — orkestrator: gabungkan route+load+fuel+price jadi satu
  // "rencana pengiriman" sekali panggil. Bagian mana pun yang parameternya
  // tidak dikasih pemanggil otomatis di-skip (null), TIDAK menebak nilai
  // default yang berisiko salah (mis. tidak asal isi vehicleId). Hasil
  // route.totalPerPcs otomatis dipakai sbg `transport` di price() kalau
  // pemanggil tidak override transport-nya sendiri — supaya "harga" yang
  // keluar dari plan() ini konsisten dgn "ongkir" yang dihitung di plan yang
  // sama (bukan 2 angka lepas yang bisa beda kalau dihitung terpisah).
  // ------------------------------------------------------------------------
  plan({
    kmProdusen, biayaPerKmProdusen, kmKonsumen, biayaPerKmKonsumen, metode, pcs,
    totalPcs, capacityPerTrip, vehicleId, modal, marginPct, transport,
  } = {}) {
    const route = this.route({ kmProdusen, biayaPerKmProdusen, kmKonsumen, biayaPerKmKonsumen, metode, pcs });
    const load = (totalPcs !== undefined && capacityPerTrip !== undefined)
      ? this.load({ totalPcs, capacityPerTrip })
      : null;
    const fuel = vehicleId ? this.fuel(vehicleId) : null;
    const price = (modal !== undefined)
      ? this.price({ modal, transport: transport !== undefined ? transport : route.totalPerPcs, marginPct })
      : null;
    return { generatedAt: new Date().toISOString(), route, load, fuel, price };
  },

  // ==========================================================================
  // TAHAP 3 — SMART LOGISTICS ENGINE (blueprint "OVERRIDE IMPLEMENTATION
  // PLAN"). Layer BARU, additive — semua method di atas (route/fuel/load/
  // price/optimizeRoute/plan) TIDAK diubah/dihapus. Sesuai IMPLEMENTATION
  // RULE blueprint: pakai helper yg SUDAH ADA (weightCalculator/
  // volumeCalculator/packingCalculator di cobek-etalase.js, sudah dimuat
  // lebih dulu — lihat scripts/build.js) alih-alih menulis ulang rumusnya,
  // dan TIDAK bikin file baru.
  // ==========================================================================

  // --------------------------------------------------------------------------
  // volumeCylinder({diameter, tinggi, qty}) — helper tambahan utk produk
  // berbentuk tabung (mis. cobek gerabah bulat) yang TIDAK punya dimensi
  // panjang/lebar/tinggi kotak. volumeCalculator() (cobek-etalase.js) TETAP
  // dipakai duluan kalau dimensi kotak tersedia (sesuai instruksi blueprint
  // §3: "gunakan data dimensi produk apabila tersedia") — fungsi ini cuma
  // fallback kalau yang ada cuma diameter+tinggi.
  // --------------------------------------------------------------------------
  volumeCylinder({ diameter, tinggi, qty } = {}) {
    const d = Math.max(0, parseFloat(diameter) || 0); // cm
    const t = Math.max(0, parseFloat(tinggi) || 0); // cm
    const q = Math.max(0, parseFloat(qty) || 0);
    const r = d / 2;
    const volumeCm3PerUnit = Math.PI * r * r * t;
    const totalM3 = (volumeCm3PerUnit * q) / 1e6; // cm3 -> m3, sama konversi dgn volumeCalculator()
    return { diameter: d, tinggi: t, qty: q, volumeCm3PerUnit, totalM3 };
  },

  // --------------------------------------------------------------------------
  // fuelCalculator({jarak, konsumsiKmPerLiter, hargaBBM}) — kalkulator BBM
  // PURE dari 3 parameter (blueprint §5), BEDA dari fuel(vehicleId) di atas
  // (yg baca histori Isi Full Tank D.vehicles lewat estimateRpPerKm()).
  // Dipakai saat kendaraan belum tercatat di D.vehicles / mau simulasi
  // manual (mis. Vehicle Capacity Checker §1 di bawah, yg terima input
  // konsumsi+harga BBM langsung, bukan vehicleId).
  // --------------------------------------------------------------------------
  fuelCalculator({ jarak, konsumsiKmPerLiter, hargaBBM } = {}) {
    const km = Math.max(0, parseFloat(jarak) || 0);
    const kmPerLiter = Math.max(0, parseFloat(konsumsiKmPerLiter) || 0);
    const harga = Math.max(0, parseFloat(hargaBBM) || 0);
    const liter = kmPerLiter > 0 ? km / kmPerLiter : 0;
    const biayaBBM = Math.round(liter * harga);
    return { jarak: km, konsumsiKmPerLiter: kmPerLiter, hargaBBM: harga, liter: Math.round(liter * 100) / 100, biayaBBM };
  },

  // --------------------------------------------------------------------------
  // vehicleCapacityCheck({jenisKendaraan, merkKendaraan, kapasitasBeratKg,
  // kapasitasVolumeM3, konsumsiKmPerLiter, hargaBBM, items, totalBeratKg,
  // totalVolumeM3}) — Vehicle Capacity Checker (blueprint §1). Muatan boleh
  // dikasih lewat `items` (reuse packingCalculator() -> weightCalculator()/
  // volumeCalculator() yang sudah ada) ATAU langsung lewat totalBeratKg/
  // totalVolumeM3 kalau pemanggil sudah punya angkanya. Status HANYA 3 nilai
  // sesuai kontrak blueprint: AMAN / HAMPIR_OVERLOAD / OVERLOAD (underscore
  // -- beda dari calculateVehicleCapacity() lama di cobek-pricing.js yang
  // pakai 'HAMPIR OVERLOAD' dgn spasi; fungsi lama itu TIDAK disentuh/diubah,
  // ini kontrak baru terpisah sesuai spec Tahap 3).
  // --------------------------------------------------------------------------
  vehicleCapacityCheck({
    jenisKendaraan, merkKendaraan, kapasitasBeratKg, kapasitasVolumeM3,
    konsumsiKmPerLiter, hargaBBM, items, totalBeratKg, totalVolumeM3,
  } = {}) {
    let totalBerat = parseFloat(totalBeratKg);
    let totalVolume = parseFloat(totalVolumeM3);
    if ((!isFinite(totalBerat) || !isFinite(totalVolume)) && typeof packingCalculator === 'function') {
      const packing = packingCalculator({ items, capacityKg: kapasitasBeratKg, capacityM3: kapasitasVolumeM3 });
      if (!isFinite(totalBerat)) totalBerat = packing.totalKg;
      if (!isFinite(totalVolume)) totalVolume = packing.totalM3;
    }
    totalBerat = Math.max(0, totalBerat || 0);
    totalVolume = Math.max(0, totalVolume || 0);

    const capKg = Math.max(0, parseFloat(kapasitasBeratKg) || 0);
    const capM3 = Math.max(0, parseFloat(kapasitasVolumeM3) || 0);
    const sisaBeratKg = capKg > 0 ? capKg - totalBerat : null;
    const sisaVolumeM3 = capM3 > 0 ? capM3 - totalVolume : null;
    const percentBerat = capKg > 0 ? (totalBerat / capKg) * 100 : null;
    const percentVolume = capM3 > 0 ? (totalVolume / capM3) * 100 : null;
    const percents = [percentBerat, percentVolume].filter((p) => p !== null);
    const percentUsed = percents.length ? Math.max(...percents) : null;
    const status = percentUsed === null ? 'AMAN'
      : percentUsed > 100 ? 'OVERLOAD'
      : percentUsed >= 80 ? 'HAMPIR_OVERLOAD'
      : 'AMAN';

    const fuel = this.fuelCalculator({ jarak: 0, konsumsiKmPerLiter, hargaBBM });

    return {
      jenisKendaraan: jenisKendaraan || null,
      merkKendaraan: merkKendaraan || null,
      totalBeratKg: totalBerat,
      totalVolumeM3: totalVolume,
      kapasitasBeratKg: capKg,
      kapasitasVolumeM3: capM3,
      sisaBeratKg,
      sisaVolumeM3,
      percentUsed: percentUsed !== null ? Math.round(percentUsed * 10) / 10 : null,
      status,
      konsumsiKmPerLiter: fuel.konsumsiKmPerLiter,
      hargaBBM: fuel.hargaBBM,
    };
  },

  // --------------------------------------------------------------------------
  // operationalCost({biayaBBM, biayaSopir, biayaOperasional, biayaLain}) —
  // blueprint §6. biayaSopir eksplisit opsional (default 0), sisanya juga
  // default 0 supaya pemanggil boleh isi sebagian saja.
  // --------------------------------------------------------------------------
  operationalCost({ biayaBBM, biayaSopir, biayaOperasional, biayaLain } = {}) {
    const bbm = Math.max(0, parseFloat(biayaBBM) || 0);
    const sopir = Math.max(0, parseFloat(biayaSopir) || 0);
    const operasional = Math.max(0, parseFloat(biayaOperasional) || 0);
    const lain = Math.max(0, parseFloat(biayaLain) || 0);
    const total = bbm + sopir + operasional + lain;
    return { biayaBBM: bbm, biayaSopir: sopir, biayaOperasional: operasional, biayaLain: lain, total };
  },

  // --------------------------------------------------------------------------
  // smartOngkir({jarak, beratKg, volumeM3, jenisKendaraan, biayaPerKm,
  // biayaOperasional, marginPct}) — blueprint §7: ongkir yang
  // mempertimbangkan jarak+berat+volume+jenis kendaraan+biaya
  // operasional+margin, BUKAN cuma jarak seperti route()/OngkirCalc.leg()
  // lama (fungsi lama TIDAK diubah — lihat "BACKWARD COMPATIBILITY" di
  // blueprint). Rumus: biaya jarak (reuse OngkirCalc.leg() kalau ada, rumus
  // SAMA persis dgn route()) + faktor berat (Rp/kg) + faktor volume (Rp/m3)
  // + biaya operasional, lalu ditambah margin%.
  // --------------------------------------------------------------------------
  smartOngkir({
    jarak, biayaPerKm, pcs, beratKg, rpPerKg, volumeM3, rpPerM3,
    jenisKendaraan, biayaOperasional, marginPct,
  } = {}) {
    const km = Math.max(0, parseFloat(jarak) || 0);
    const rpKm = Math.max(0, parseFloat(biayaPerKm) || 0);
    const p = Math.max(1, parseFloat(pcs) || 1);
    const biayaJarak = (typeof OngkirCalc !== 'undefined' && typeof OngkirCalc.leg === 'function')
      ? OngkirCalc.leg(rpKm, km, p) * p // OngkirCalc.leg() balikin per-pcs, kalikan lagi jadi total etape ini
      : rpKm * km;
    const biayaBerat = Math.max(0, parseFloat(beratKg) || 0) * Math.max(0, parseFloat(rpPerKg) || 0);
    const biayaVolume = Math.max(0, parseFloat(volumeM3) || 0) * Math.max(0, parseFloat(rpPerM3) || 0);
    const opCost = Math.max(0, parseFloat(biayaOperasional) || 0);
    const subtotal = biayaJarak + biayaBerat + biayaVolume + opCost;
    const margin = Math.max(0, parseFloat(marginPct) || 0);
    const totalOngkir = Math.round(subtotal * (1 + margin / 100));
    return {
      jenisKendaraan: jenisKendaraan || null,
      jarak: km, biayaJarak: Math.round(biayaJarak),
      beratKg: parseFloat(beratKg) || 0, biayaBerat: Math.round(biayaBerat),
      volumeM3: parseFloat(volumeM3) || 0, biayaVolume: Math.round(biayaVolume),
      biayaOperasional: opCost,
      marginPct: margin,
      subtotal: Math.round(subtotal),
      totalOngkir,
    };
  },

  // --------------------------------------------------------------------------
  // profitCalculator({totalPenjualan, diskon, ongkir, biayaBBM,
  // biayaOperasional}) — blueprint §8, breakdown LENGKAP (beda dari
  // calculateProfit() lama di cobek-pricing.js yang cuma revenue-modal-
  // ongkir per produk; fungsi lama itu TIDAK diubah). Semua parameter
  // default 0 (boleh isi sebagian).
  // --------------------------------------------------------------------------
  profitCalculator({ totalPenjualan, diskon, ongkir, biayaBBM, biayaOperasional } = {}) {
    const penjualan = Math.max(0, parseFloat(totalPenjualan) || 0);
    const disc = Math.max(0, parseFloat(diskon) || 0);
    const ong = Math.max(0, parseFloat(ongkir) || 0);
    const bbm = Math.max(0, parseFloat(biayaBBM) || 0);
    const op = Math.max(0, parseFloat(biayaOperasional) || 0);
    const penjualanBersih = penjualan - disc;
    const profitBersih = penjualanBersih - ong - bbm - op;
    const marginPct = penjualan > 0 ? (profitBersih / penjualan) * 100 : 0;
    return {
      totalPenjualan: penjualan, diskon: disc, ongkir: ong, biayaBBM: bbm, biayaOperasional: op,
      penjualanBersih, profitBersih, marginPct: Math.round(marginPct * 100) / 100,
    };
  },

  // --------------------------------------------------------------------------
  // deliverySummary(ctx) — blueprint §9, orkestrator TERAKHIR yang
  // menggabungkan §1-§8 jadi satu ringkasan akhir. Sama filosofi dgn plan()
  // lama (tiap bagian yang parameternya tidak dikasih otomatis di-skip,
  // TIDAK menebak default yang berisiko salah). TIDAK memanggil AI/
  // Dashboard/Simulation apa pun (di luar scope Tahap 3 sesuai blueprint).
  // --------------------------------------------------------------------------
  deliverySummary({
    jenisKendaraan, merkKendaraan, kapasitasBeratKg, kapasitasVolumeM3,
    konsumsiKmPerLiter, hargaBBM, items, totalBeratKg, totalVolumeM3,
    jarak, biayaPerKm, pcs,
    rpPerKg, rpPerM3, biayaSopir, biayaOperasionalLain, biayaLain,
    totalPenjualan, diskon, marginPct,
  } = {}) {
    const capacity = this.vehicleCapacityCheck({
      jenisKendaraan, merkKendaraan, kapasitasBeratKg, kapasitasVolumeM3,
      konsumsiKmPerLiter, hargaBBM, items, totalBeratKg, totalVolumeM3,
    });
    const fuel = this.fuelCalculator({ jarak, konsumsiKmPerLiter, hargaBBM });
    const operational = this.operationalCost({
      biayaBBM: fuel.biayaBBM, biayaSopir, biayaOperasional: biayaOperasionalLain, biayaLain,
    });
    const ongkir = this.smartOngkir({
      jarak, biayaPerKm, pcs, beratKg: capacity.totalBeratKg, rpPerKg,
      volumeM3: capacity.totalVolumeM3, rpPerM3, jenisKendaraan,
      biayaOperasional: operational.total, marginPct,
    });
    const profit = (totalPenjualan !== undefined)
      ? this.profitCalculator({
        totalPenjualan, diskon, ongkir: ongkir.totalOngkir,
        biayaBBM: fuel.biayaBBM, biayaOperasional: operational.total - fuel.biayaBBM,
      })
      : null;
    return {
      generatedAt: new Date().toISOString(),
      berat: capacity.totalBeratKg,
      volume: capacity.totalVolumeM3,
      statusKendaraan: capacity.status,
      capacity,
      estimasiBBM: fuel,
      biayaOperasional: operational,
      ongkir,
      profit,
    };
  },
};

if (typeof window !== 'undefined') {
  window.LogisticsEngine = LogisticsEngine;
}

// logistics-service.js — Smart Delivery Engine, Sesi 3/6: facade logistik.
//
// Lihat RENCANA-SESI-RINGKAS.md untuk peta 6 sesi. Butuh logistics-engine.js
// (di atas, Sesi 3 ini) sudah dimuat lebih dulu — lihat urutan di
// scripts/build.js.
//
// Kenapa 1 file, bukan 3 (logistics-service.js + logistics-ui.js +
// logistics-modal.js) — lihat RENCANA-SESI-RINGKAS.md bagian "Kenapa
// dipangkas". TIDAK ada modal baru dibikin di sini sama sekali: kalau nanti
// (Sesi 4+) hasil LogisticsService perlu ditampilkan ke user, pemanggilnya
// makai modal generik yang SUDAH ADA di modules/shared/modal-navigasi.js
// (showChoiceModal/askConfirm/showInfoModal dkk) — LogisticsService cuma
// menyediakan data terstruktur + ringkasan teks siap tampil lewat
// formatSummary(), TIDAK merender HTML/DOM apa pun sendiri.
//
// PENTING (Sesi 3 — masih "senyap", sama seperti Sesi 1-2): tidak ada
// wiring otomatis ke modul lain, tidak ada tombol/menu baru. Method di
// bawah baru "hidup" kalau dipanggil eksplisit oleh kode lain (Sesi 4-6).

const LogisticsService = {
  /** planDelivery(ctx) — satu-satunya jalur yang seharusnya dipakai modul
   * lain (Sesi 4-6) buat dapat rencana pengiriman (rute+beban+BBM+harga)
   * — mereka tidak perlu tahu/panggil LogisticsEngine langsung, supaya
   * kalau internal engine berubah nanti, kontrak publik ini tetap sama.
   * Lihat LogisticsEngine.plan() utk bentuk parameter & hasil lengkap. */
  async planDelivery(ctx = {}) {
    return LogisticsEngine.plan(ctx);
  },

  /** optimizeRoute(ctx) — satu-satunya jalur yang seharusnya dipakai modul
   * lain (Sesi 6+) buat urutan rute banyak-pelanggan; lihat
   * LogisticsEngine.optimizeRoute() utk bentuk parameter & hasil lengkap. */
  async optimizeRoute(ctx = {}) {
    return LogisticsEngine.optimizeRoute(ctx);
  },

  /** formatSummary(plan) — rangkai hasil planDelivery() jadi teks ringkas
   * siap ditampilkan lewat modal generik yang sudah ada (mis.
   * showInfoModal(judul, LogisticsService.formatSummary(plan))) — TIDAK
   * menyentuh DOM di sini, murni penyusun string, sama prinsipnya dgn
   * AIService.buildPrompt() di ai-service.js. Baris yang datanya tidak ada
   * (mis. plan.fuel null krn histori BBM belum cukup) otomatis di-skip,
   * bukan ditampilkan sbg "null"/"undefined". */
  formatSummary(plan) {
    if (!plan || typeof plan !== 'object') return 'Belum ada rencana pengiriman.';
    const lines = [];
    if (plan.route) {
      const r = plan.route;
      lines.push(`🚚 Ongkir: ${r.pcs} pcs, metode ${r.metode === 'ambil' ? 'ambil sendiri' : 'diantar'} — Rp${Math.round(r.totalPerPcs)}/pcs`);
    }
    if (plan.load) {
      const l = plan.load;
      lines.push(`📦 Muatan: ${l.totalPcs} pcs ÷ kapasitas ${l.capacityPerTrip}/rit = ${l.trips} kali jalan (≈${l.pcsPerTrip} pcs/rit)`);
    }
    if (plan.fuel) {
      const f = plan.fuel;
      lines.push(`⛽ BBM: ≈${f.kmPerLiter.toFixed(1)} km/liter, Rp${Math.round(f.rpPerKm)}/km`);
    }
    if (plan.price) {
      const p = plan.price;
      lines.push(`🏷️ Rekomendasi harga jual: Rp${Math.round(p.result)} (modal Rp${Math.round(p.modal)} + transport Rp${Math.round(p.transport)}, margin ${p.marginPct}%)`);
    }
    return lines.length ? lines.join('\n') : 'Belum cukup data untuk hitung rencana pengiriman.';
  },

  /** healthCheck() — pemeriksaan integritas ringan, non-invasif (TIDAK
   * memanggil route/load/fuel/price dgn data nyata, cuma cek fungsi &
   * dependensinya tersedia) — pola & tujuan sama dgn AIService.healthCheck()
   * di ai-service.js: cepat tahu kalau ada dependensi (OngkirCalc/PriceReko/
   * estimateRpPerKm) yang belum ter-load krn urutan build.js keliru. */
  async healthCheck() {
    const checks = {
      engineReady: typeof LogisticsEngine !== 'undefined' && typeof LogisticsEngine.plan === 'function',
      ongkirCalcReady: typeof OngkirCalc !== 'undefined' && typeof OngkirCalc.leg === 'function',
      priceRekoReady: typeof PriceReko !== 'undefined' && typeof PriceReko.roundNice === 'function',
      estimateRpPerKmReady: typeof estimateRpPerKm === 'function',
    };
    const ok = checks.engineReady && checks.ongkirCalcReady && checks.priceRekoReady;
    return { ok, checkedAt: new Date().toISOString(), checks };
  },

  // ==========================================================================
  // TAHAP 3 — SMART LOGISTICS ENGINE. Facade tipis, pola PERSIS sama dgn
  // planDelivery()/optimizeRoute() di atas: modul lain panggil lewat
  // LogisticsService (bukan LogisticsEngine langsung) supaya kontrak publik
  // tetap sama kalau internal engine berubah. Belum ada wiring/tombol UI
  // (sesuai blueprint "Belum membuat AI Chat/Simulation/Dashboard/Daily
  // Briefing" — method ini baru "hidup" kalau dipanggil eksplisit).
  // ==========================================================================

  /** vehicleCapacityCheck(ctx) — lihat LogisticsEngine.vehicleCapacityCheck()
   * utk bentuk parameter & hasil lengkap (blueprint Fitur §1). */
  async vehicleCapacityCheck(ctx = {}) {
    return LogisticsEngine.vehicleCapacityCheck(ctx);
  },

  /** fuelCalculator(ctx) — Fitur §5 (blueprint), BEDA dari fuel()/
   * calculateFuel() lama yg baca histori D.vehicles. */
  async fuelCalculator(ctx = {}) {
    return LogisticsEngine.fuelCalculator(ctx);
  },

  /** operationalCost(ctx) — Fitur §6 (blueprint). */
  async operationalCost(ctx = {}) {
    return LogisticsEngine.operationalCost(ctx);
  },

  /** smartOngkir(ctx) — Fitur §7 (blueprint): ongkir mempertimbangkan
   * jarak+berat+volume+jenis kendaraan+biaya operasional+margin. */
  async smartOngkir(ctx = {}) {
    return LogisticsEngine.smartOngkir(ctx);
  },

  /** profitCalculator(ctx) — Fitur §8 (blueprint), breakdown lengkap
   * (penjualan/diskon/ongkir/BBM/operasional/profit bersih/margin%). */
  async profitCalculator(ctx = {}) {
    return LogisticsEngine.profitCalculator(ctx);
  },

  /** deliverySummary(ctx) — Fitur §9 (blueprint), orkestrator akhir §1-§8.
   * Lihat LogisticsEngine.deliverySummary() utk bentuk parameter lengkap. */
  async deliverySummary(ctx = {}) {
    return LogisticsEngine.deliverySummary(ctx);
  },
};

if (typeof window !== 'undefined') {
  window.LogisticsService = LogisticsService;
}

// purchase-engine.js — Shop Business Engine, S198 (Business Engine untuk Shop).
//
// TARGET EKSPLISIT USER (S198): "Buat Business Engine untuk Shop. Reuse
// seluruh Shop existing. Jangan ubah business logic. Jangan implementasi ke
// modul lain. Jangan refactor. Hanya: PurchaseEngine/TripEngine/
// InventoryEngine/ProfitEngine. Engine berupa file baru saja. Belum
// digunakan UI. Belum dihubungkan ke Shop."
//
// PurchaseEngine = lapisan pembelian/restock (Produsen, harga beli per
// produsen, & rekomendasi restock StockRekoWidget). SAMA POLA dgn
// OwnershipEngine (modules/shared/ownership-engine.js, S191) & LogisticsEngine
// (modules/logistics/logistics-engine.js): pure/stateless, TIDAK PERNAH
// menyentuh D (kecuali baca read-only lewat fungsi Shop existing yang
// dipanggilnya), TIDAK PERNAH panggil save(), TIDAK ADA business logic BARU
// — semua angka & aturan di bawah ini murni membungkus fungsi yang SUDAH ADA
// di modules/shop/cobek-*.js (Produsen, Etalase, StockRekoWidget) supaya
// kalau rumus aslinya berubah, hasil di sini otomatis ikut berubah (satu
// sumber kebenaran, sama prinsip komentar LogisticsEngine).
//
// SESI INI SENGAJA TIDAK MENYENTUH modul lain apa pun: tidak ada field baru
// di D.*, tidak ada UI, tidak ada wiring dari cobek-*.js ke engine ini —
// wiring itu tugas sesi lain yang eksplisit memintanya.
const PurchaseEngine = {

  // recordCost(params) — hitung biaya pembelian stok (delta qty x harga
  // beli), PERSIS rumus di Etalase.save() (modules/shop/cobek-etalase.js):
  // `const cost=delta*hargaBeli`. Dibungkus jadi fungsi murni (parameter,
  // bukan baca #pStock/#pBeli dari DOM) supaya bisa dipanggil/dites tanpa
  // form produk terbuka. delta<=0 (stok tidak naik / stok turun) -> tidak
  // ada biaya pembelian (recorded:false), sama seperti Etalase.save() yang
  // cuma mencatat transaksi expense saat delta>0 & hargaBeli>0.
  recordCost({ prevStock, newStock, hargaBeli } = {}) {
    const prev = Math.max(0, parseFloat(prevStock) || 0);
    const next = Math.max(0, parseFloat(newStock) || 0);
    const beli = Math.max(0, parseFloat(hargaBeli) || 0);
    const delta = next - prev;
    const recorded = delta > 0 && beli > 0;
    const cost = recorded ? delta * beli : 0;
    return { prevStock: prev, newStock: next, hargaBeli: beli, delta, recorded, cost };
  },

  // produsenPrice(product, produsenId) — harga beli produk dari produsen
  // tertentu, PERSIS pola `product.hargaByProdusen[produsenId]` yang dibaca
  // di Etalase.onProdusenChange() (cobek-etalase.js). null kalau produk/
  // produsenId tidak ada atau belum ada histori harga dari produsen itu.
  produsenPrice(product, produsenId) {
    if (!product || !produsenId || !product.hargaByProdusen) return null;
    const val = product.hargaByProdusen[produsenId];
    return (val !== undefined) ? val : null;
  },

  // produsenProducts(produsen, products) — daftar produk yang punya histori
  // harga beli dari produsen tsb, PERSIS filter di Produsen.openModal()
  // (cobek-order.js): `p.hargaByProdusen && p.hargaByProdusen[pr.id]!==undefined`.
  produsenProducts(produsen, products) {
    if (!produsen) return [];
    return (products || []).filter(
      (p) => p.hargaByProdusen && p.hargaByProdusen[produsen.id] !== undefined,
    );
  },

  // restockPlan(scanResult) — dari daftar hasil StockRekoWidget.scan() (tiap
  // item {product, restockQty, ...}, TIDAK dihitung ulang di sini — hitungan
  // asli tetap satu-satunya di StockRekoWidget.scan(), modules/shop/
  // cobek-pricing.js), susun ringkasan rencana beli: jumlah item yang perlu
  // direstock & total qty yang perlu dibeli. PERSIS agregasi yang dipakai
  // StockRekoWidget.renderApplyAllBtn() (`flagged.reduce((s,x)=>s+x.restockQty,0)`).
  restockPlan(scanResult) {
    const flagged = (scanResult || []).filter((x) => x && x.restockQty > 0);
    const totalQty = flagged.reduce((s, x) => s + (x.restockQty || 0), 0);
    return { items: flagged, itemCount: flagged.length, totalQty };
  },

  // estimatedCost(scanResult) — perkiraan total modal (Rp) yang dibutuhkan
  // untuk restock semua item terflag di restockPlan(), pakai hargaBeli
  // masing-masing produk (product.hargaBeli, field yang sudah ada di
  // D.products — bukan field baru). Item tanpa hargaBeli (0/undefined)
  // dianggap 0 (tidak error).
  estimatedCost(scanResult) {
    const plan = this.restockPlan(scanResult);
    const totalCost = plan.items.reduce((s, x) => {
      const beli = (x.product && x.product.hargaBeli) || 0;
      return s + beli * (x.restockQty || 0);
    }, 0);
    return Object.assign({}, plan, { totalCost });
  },
};

// trip-engine.js — Shop Business Engine, S198 (Business Engine untuk Shop).
//
// TripEngine = lapisan pengiriman/rit (ongkir, berat/volume/packing, muatan
// kendaraan, BBM). SAMA POLA dgn PurchaseEngine (file sebelah) &
// LogisticsEngine (modules/logistics/logistics-engine.js, Sesi 3): pure
// wrapper, TIDAK ADA rumus baru — semuanya delegasi ke fungsi Shop existing
// (weightCalculator/volumeCalculator/packingCalculator di cobek-etalase.js;
// calculateFuel/calculateVehicleCapacity di cobek-pricing.js;
// calculateSmartDelivery di cobek-order.js; OngkirCalc.leg/LogisticsEngine.route
// yang sudah ada) supaya satu sumber kebenaran tetap terjaga.
//
// TIDAK PERNAH menyentuh D sendiri, TIDAK PERNAH panggil save(). Beberapa
// method di bawah memanggil fungsi Shop yang MEMANG membaca D read-only
// (mis. calculateSmartDelivery baca D.products/D.produsen) — itu perilaku
// ASLI fungsi tsb, bukan sesuatu yang ditambahkan di sini.
//
// Belum digunakan UI. Belum dihubungkan ke Shop (tidak dipanggil dari
// cobek-*.js mana pun sesi ini).
const TripEngine = {

  // weight/volume/packing — delegasi murni ke fungsi global yang sudah ada
  // di cobek-etalase.js (Smart Delivery Engine Sesi 4). Guard
  // `typeof fn==='function'` supaya engine ini tetap aman dipanggil kalau
  // suatu saat dimuat sendirian (tanpa cobek-etalase.js), sama pola guard
  // yang dipakai LogisticsEngine.fuel()/calculateFuel().
  weight(params) {
    if (typeof weightCalculator !== 'function') {
      return { ok: false, reason: 'weightCalculator belum dimuat' };
    }
    return Object.assign({ ok: true }, weightCalculator(params));
  },

  volume(params) {
    if (typeof volumeCalculator !== 'function') {
      return { ok: false, reason: 'volumeCalculator belum dimuat' };
    }
    return Object.assign({ ok: true }, volumeCalculator(params));
  },

  packing(params) {
    if (typeof packingCalculator !== 'function') {
      return { ok: false, reason: 'packingCalculator belum dimuat' };
    }
    return Object.assign({ ok: true }, packingCalculator(params));
  },

  // route(params) — biaya angkut/pcs, delegasi PERSIS ke LogisticsEngine.route()
  // (yang sendiri sudah delegasi ke OngkirCalc.leg()) — lihat catatan "satu
  // sumber kebenaran" di logistics-engine.js.
  route(params) {
    if (typeof LogisticsEngine === 'undefined') {
      return { ok: false, reason: 'LogisticsEngine belum dimuat' };
    }
    return Object.assign({ ok: true }, LogisticsEngine.route(params));
  },

  // fuel(vehicleId) — delegasi ke calculateFuel() (cobek-pricing.js), yang
  // sendiri delegasi ke LogisticsEngine.fuel(). Dipertahankan sbg method
  // terpisah (bukan langsung LogisticsEngine.fuel()) supaya TripEngine tetap
  // konsisten ambil dari lapisan Shop, sama seperti calculateVehicleCapacity
  // memanggil calculateFuel() (bukan LogisticsEngine.fuel() langsung).
  fuel(vehicleId) {
    if (typeof calculateFuel !== 'function') {
      return { ok: false, reason: 'calculateFuel belum dimuat' };
    }
    return calculateFuel(vehicleId);
  },

  // vehicleCapacity(params) — delegasi PERSIS ke calculateVehicleCapacity()
  // (cobek-pricing.js): gabungan packing + info BBM + status AMAN/HAMPIR
  // OVERLOAD/OVERLOAD.
  vehicleCapacity(params) {
    if (typeof calculateVehicleCapacity !== 'function') {
      return { ok: false, reason: 'calculateVehicleCapacity belum dimuat' };
    }
    return calculateVehicleCapacity(params);
  },

  // plan(params) — rencana pengiriman produk tertentu, delegasi PERSIS ke
  // calculateSmartDelivery() (cobek-order.js): resolve produsen/jarak dari
  // D, hitung ongkir lewat LogisticsEngine.plan(), & profit lewat
  // calculateProfit(). Fungsi asli MEMBACA D.products/D.produsen (read-only)
  // — TripEngine tidak menambah pembacaan D baru, cuma membungkus.
  plan(params) {
    if (typeof calculateSmartDelivery !== 'function') {
      return { ok: false, reason: 'calculateSmartDelivery belum dimuat' };
    }
    return calculateSmartDelivery(params);
  },
};

// inventory-engine.js — Shop Business Engine, S198 (Business Engine untuk
// Shop).
//
// InventoryEngine = lapisan stok/katalog (nilai stok tertanam, status
// stok per produk, grup harga ukuran/gabungan, & rekomendasi restock).
// SAMA POLA dgn PurchaseEngine/TripEngine (file sebelah): pure wrapper,
// TIDAK ADA rumus baru — semuanya delegasi ke fungsi Shop existing (Etalase.*
// & StockRekoWidget.* di modules/shop/cobek-etalase.js & cobek-pricing.js).
//
// TIDAK PERNAH menyentuh D sendiri, TIDAK PERNAH panggil save(). Method di
// bawah memanggil Etalase/StockRekoWidget yang MEMANG membaca D.products
// read-only — perilaku ASLI fungsi tsb, bukan tambahan baru di sini.
//
// Belum digunakan UI. Belum dihubungkan ke Shop (tidak dipanggil dari
// cobek-*.js mana pun sesi ini).
const InventoryEngine = {

  // stockStatus(product) — label status stok per produk, PERSIS ambang di
  // Etalase.renderList() (cobek-etalase.js): `p.stock<=2` -> 'low'
  // ("Menipis"), `p.stock<=5` -> 'mid' ("Terbatas"), selain itu -> 'ok'
  // ("Aman"). Dibungkus jadi fungsi murni (parameter angka, bukan baca DOM)
  // supaya bisa dites/dipanggil tanpa render tab Etalase.
  stockStatus(product) {
    const stock = (product && parseFloat(product.stock)) || 0;
    const cls = stock <= 2 ? 'low' : (stock <= 5 ? 'mid' : 'ok');
    const label = stock <= 2 ? 'Menipis' : (stock <= 5 ? 'Terbatas' : 'Aman');
    return { stock, cls, label };
  },

  // totalModalStok(products) / totalNilaiJualStok(products) — delegasi
  // PERSIS ke Etalase.totalModalStok()/Etalase.totalNilaiJualStok(), dibuat
  // menerima `products` sbg parameter opsional supaya bisa dites tanpa objek
  // D global (fallback ke D.products lewat Etalase kalau tidak dikasih).
  //
  // S259 (Inventory Ownership Sync): jalur eksplisit (`products` dikasih)
  // dulu TIDAK melewati filter ownership (isProductOwnershipSelf), padahal
  // jalur fallback (tanpa parameter -> Etalase.totalModalStok()/
  // totalNilaiJualStok()) SELALU filter SELF-only sejak Product Ownership
  // Foundation. Akibatnya ShopBusinessEnginePresenter.summary() (yang
  // manggil dgn D.products penuh sbg parameter) menghasilkan angka beda
  // dgn kartu Etalase (cModalStok/cNilaiJualStok) untuk data yang punya
  // produk non-SELF (INVESTOR/CUSTOMER/THIRD_PARTY/FAMILY). Diperbaiki
  // dengan reuse isProductOwnershipSelf() (SSOT, didefinisikan di
  // cobek-etalase.js, dimuat sebelum file ini di build.js) di KEDUA
  // jalur, supaya SEMUA caller (dgn atau tanpa parameter) konsisten
  // dengan Etalase. Guard typeof isProductOwnershipSelf: kalau fungsi itu
  // belum dimuat, fallback anggap semua SELF (tidak exclude apa pun) —
  // pola guard yang sama dipakai fungsi lain di file ini.
  totalModalStok(products) {
    const selfFilter = (typeof isProductOwnershipSelf === 'function') ? isProductOwnershipSelf : (() => true);
    if (products) {
      return (products || []).filter(selfFilter).reduce((s, p) => s + ((p.stock || 0) * (p.hargaBeli || 0)), 0);
    }
    if (typeof Etalase === 'undefined') return 0;
    return Etalase.totalModalStok();
  },

  totalNilaiJualStok(products) {
    const selfFilter = (typeof isProductOwnershipSelf === 'function') ? isProductOwnershipSelf : (() => true);
    if (products) {
      return (products || []).filter(selfFilter).reduce((s, p) => s + ((p.stock || 0) * (p.hargaJual || 0)), 0);
    }
    if (typeof Etalase === 'undefined') return 0;
    return Etalase.totalNilaiJualStok();
  },

  // pairKey/bracketRange/linkedSiblings — delegasi PERSIS ke Etalase (size
  // pairing kw206 & manual merge kw209), supaya InventoryEngine bisa jadi
  // satu pintu baca "kelompok harga" produk tanpa duplikat regex/logic
  // parsing nama produk.
  pairKey(product) {
    if (typeof Etalase === 'undefined') return null;
    return Etalase.pairKey(product);
  },

  bracketRange(product) {
    if (typeof Etalase === 'undefined') return null;
    return Etalase.bracketRange(product);
  },

  linkedSiblings(product) {
    if (typeof Etalase === 'undefined') return [];
    return Etalase.linkedSiblings(product);
  },

  // restockScan() — delegasi PERSIS ke StockRekoWidget.scan() (cobek-pricing.js):
  // daftar produk/grup ukuran yang direkomendasikan direstock, berikut
  // status ada/tidaknya histori penjualan & estimasi hari stok tersisa.
  restockScan() {
    if (typeof StockRekoWidget === 'undefined') {
      return { ok: false, reason: 'StockRekoWidget belum dimuat', items: [] };
    }
    return { ok: true, items: StockRekoWidget.scan() };
  },
};

// profit-engine.js — Shop Business Engine, S198 (Business Engine untuk Shop).
//
// ProfitEngine = lapisan profit/margin (untung per transaksi, rekap omzet
// periode, & rekomendasi harga jual). SAMA POLA dgn PurchaseEngine/
// TripEngine/InventoryEngine (file sebelah): pure wrapper, TIDAK ADA rumus
// baru — semuanya delegasi ke fungsi Shop existing (calculateProfit di
// cobek-pricing.js; Laporan.getStats-style agregasi & PriceReko.roundNice di
// cobek-order.js/cobek-pricing.js).
//
// TIDAK PERNAH menyentuh D sendiri, TIDAK PERNAH panggil save(). Method di
// bawah memanggil fungsi Shop yang MEMANG membaca D read-only (mis.
// calculateProfit baca D.products) — perilaku ASLI fungsi tsb.
//
// Belum digunakan UI. Belum dihubungkan ke Shop (tidak dipanggil dari
// cobek-*.js mana pun sesi ini).
const ProfitEngine = {

  // profit(params) — delegasi PERSIS ke calculateProfit() (cobek-pricing.js):
  // revenue - modal - ongkir dari qty unit produk tertentu.
  profit(params) {
    if (typeof calculateProfit !== 'function') {
      return null;
    }
    return calculateProfit(params);
  },

  // margin(revenue, profitAmount) — persentase margin, PERSIS rumus yang
  // dipakai berulang di cobek-order.js (mis. `omzet>0?Math.round((untung/omzet)*100):0`
  // di Laporan.renderTab()/renderTabLap()) & calculateProfit()
  // (`revenue>0?(profit/revenue)*100:0`). Dibungkus jadi satu fungsi murni
  // supaya tidak perlu duplikat guard "revenue>0" di banyak tempat.
  margin(revenue, profitAmount) {
    const rev = parseFloat(revenue) || 0;
    const p = parseFloat(profitAmount) || 0;
    return rev > 0 ? (p / rev) * 100 : 0;
  },

  // summarize(transactions) — omzet/untung/margin dari daftar transaksi
  // Shop (D.cobek), PERSIS agregasi Laporan.renderTab() (cobek-order.js):
  // `omzet=inRangeSelf.reduce((s,t)=>s+(t.total||0),0)`,
  // `untung=inRangeSelf.reduce((s,t)=>s+(t.profit||0),0)`. Pemanggil yang
  // menentukan filter periode/kepemilikan (isCobekOwnershipSelf, dst) —
  // fungsi ini murni mengagregasi array yang sudah difilter, tidak
  // menduplikasi logic filter tsb.
  summarize(transactions) {
    const list = transactions || [];
    const omzet = list.reduce((s, t) => s + (t.total || 0), 0);
    const untung = list.reduce((s, t) => s + (t.profit || 0), 0);
    return {
      trip: list.length,
      omzet,
      untung,
      marginPct: this.margin(omzet, untung),
    };
  },

  // recommendPrice(params) — rekomendasi harga jual, delegasi PERSIS ke
  // PriceReko.roundNice() (pembulatan) dgn rumus yang sama persis
  // `(modal+transport)*(1+marginPct/100)` dari PriceReko.calc()
  // (cobek-pricing.js) — dibungkus jadi parameter murni (bukan baca
  // #pBeli/#prkTransport/#prkMargin dari DOM).
  recommendPrice({ modal, transport, marginPct } = {}) {
    const modalNum = parseFloat(modal) || 0;
    const transportNum = parseFloat(transport) || 0;
    const marginNum = parseFloat(marginPct) || 0;
    const base = modalNum + transportNum;
    const raw = base * (1 + marginNum / 100);
    const rounded = (typeof PriceReko !== 'undefined' && typeof PriceReko.roundNice === 'function')
      ? PriceReko.roundNice(raw)
      : Math.round(raw / 100) * 100;
    return { modal: modalNum, transport: transportNum, marginPct: marginNum, base, result: rounded };
  },
};

// modules/shop/delivery-plan-ui.js — Delivery Plan UI (Sesi 203, Continue).
//
// Menutup gap yang dicatat di trip-engine.js ("Belum digunakan UI. Belum
// dihubungkan ke Shop.") & shop-business-engine-presenter.js ("TripEngine
// tidak dipakai di sini ... dipakai langsung di form Order/Kasir sesuai
// desain aslinya"). File ini murni presenter: 100% REUSE TripEngine (S198,
// modules/shop/trip-engine.js) yang sendiri delegasi PERSIS ke
// calculateSmartDelivery()/weightCalculator()/volumeCalculator() (sudah ada
// sejak Sesi 3-6). TIDAK ADA rumus baru, TIDAK menulis ke D, TIDAK memanggil
// save() — murni baca D.products/D.produsen/D.vehicles (read-only, sama
// kontrak fungsi yang di-reuse) & render ke #deliveryPlanModal (modals.js).
//
// Dipanggil dari tombol "🚚 Rencana Pengiriman" di orderModal
// (modules/shared/modals.js) lewat data-action="DeliveryPlanUI.open".
const DeliveryPlanUI = {
  metode: 'antar',

  _money(n) {
    return (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
  },

  // open(prefill) — isi semua <select> dari D (produk/produsen/kendaraan),
  // reset form ke default, lalu buka modal & hitung sekali. `prefill`
  // opsional {productId,qty} (S206, Business Flow Purchase->Trip wiring)
  // — kalau dikasih & productId ada di daftar produk, dropdown produk &
  // qty langsung diisi dari situ (dipakai APA ADANYA, 0 recompute) —
  // TIDAK memanggil open() tanpa argumen, dipakai APA ADANYA, TIDAK ada
  // perubahan perilaku kalau dipanggil tanpa argumen (semua pemanggil
  // lama tetap sama persis).
  open(prefill) {
    const prodSel = document.getElementById('dpProduct');
    if (prodSel) {
      prodSel.innerHTML = (D.products || [])
        .map((p) => `<option value="${p.id}">${escapeHtml(p.name)}</option>`)
        .join('');
    }
    const produsenSel = document.getElementById('dpProdusen');
    if (produsenSel) {
      produsenSel.innerHTML = '<option value="">— Tanpa produsen —</option>'
        + (D.produsen || []).map((pr) => `<option value="${pr.id}">${escapeHtml(pr.name)}</option>`).join('');
    }
    const vehSel = document.getElementById('dpVehicle');
    if (vehSel) {
      vehSel.innerHTML = '<option value="">— Tanpa kendaraan —</option>'
        + (D.vehicles || []).map((v) => `<option value="${v.id}">${v.emoji || ''} ${escapeHtml(v.name)}</option>`).join('');
    }
    const qtyEl = document.getElementById('dpQty');
    if (qtyEl) qtyEl.value = 1;
    this.metode = 'antar';
    const aiBox = document.getElementById('dpAiBox');
    if (aiBox) { aiBox.classList.add('u-dnone'); aiBox.innerHTML = ''; }
    if (prefill && prefill.productId && prodSel) {
      const exists = (D.products || []).some((p) => p.id === prefill.productId);
      if (exists) {
        prodSel.value = prefill.productId;
        if (qtyEl && prefill.qty > 0) qtyEl.value = prefill.qty;
      }
    }
    this.onProductChange();
    openModal('deliveryPlanModal');
  },

  // onProductChange() — kalau produk pilihan punya produsenId bawaan
  // (D.products[].produsenId, sama field yg dipakai productModal), auto-
  // pilih produsen itu di dropdown supaya km/biaya bisa terisi dari
  // preferensi produsen (S6, OngkirCalc.prefillFromProdusen pola serupa).
  onProductChange() {
    const prodSel = document.getElementById('dpProduct');
    const produsenSel = document.getElementById('dpProdusen');
    if (prodSel && produsenSel) {
      const product = (D.products || []).find((p) => p.id === prodSel.value);
      if (product && product.produsenId) produsenSel.value = product.produsenId;
    }
    this.calc();
  },

  // setMetode(v, el) — toggle chip aktif + tampilkan/sembunyikan Etape 2
  // (Pekalongan -> Rumah Konsumen), pola SAMA PERSIS OngkirCalc.setMetode
  // (productModal, cobek-etalase.js/modals.js) supaya konsisten UX.
  setMetode(v, el) {
    this.metode = v;
    const wrap = document.getElementById('dpMetodeToggle');
    if (wrap) Array.from(wrap.children).forEach((b) => b.classList.remove('active'));
    if (el) el.classList.add('active');
    const etape2 = document.getElementById('dpEtape2Fields');
    if (etape2) etape2.style.display = (v === 'ambil') ? 'none' : '';
    this.calc();
  },

  // calc() — orkestrator murni presenter: kumpulkan input form, panggil
  // TripEngine.plan() (delegasi PERSIS calculateSmartDelivery(), S198) utk
  // ongkir+harga+profit, & TripEngine.weight()/volume() (delegasi PERSIS
  // weightCalculator()/volumeCalculator(), S198) utk info berat/volume
  // muatan kalau produk sudah punya data dimensi (S203, productModal).
  // TIDAK ADA hitungan baru di sini — cuma merangkai hasil 3 method
  // TripEngine yang sudah ada jadi satu ringkasan HTML.
  calc() {
    const box = document.getElementById('dpSummaryBox');
    if (!box) return;
    if (typeof TripEngine === 'undefined') {
      box.innerHTML = 'TripEngine belum dimuat.';
      return;
    }
    const productId = document.getElementById('dpProduct')?.value;
    const product = (D.products || []).find((p) => p.id === productId);
    if (!product) {
      box.innerHTML = 'Pilih produk untuk mulai.';
      return;
    }
    const qty = Math.max(0, parseFloat(document.getElementById('dpQty')?.value) || 0);
    const produsenId = document.getElementById('dpProdusen')?.value || null;
    const kmKonsumen = document.getElementById('dpKmKonsumen')?.value;
    const biayaPerKmKonsumen = document.getElementById('dpBiayaKmKonsumen')?.value;
    const vehicleId = document.getElementById('dpVehicle')?.value || null;
    const marginPct = document.getElementById('dpMarginPct')?.value;

    const plan = TripEngine.plan({
      productId, qty, produsenId,
      kmKonsumen: this.metode === 'antar' ? kmKonsumen : undefined,
      biayaPerKmKonsumen: this.metode === 'antar' ? biayaPerKmKonsumen : undefined,
      metode: this.metode, vehicleId,
      marginPct: marginPct !== '' ? marginPct : undefined,
    });

    let html = '';
    if (!plan.ok) {
      box.innerHTML = escapeHtml(plan.reason || 'Belum bisa dihitung.');
      return;
    }
    html += `<div><b>${escapeHtml(plan.productName)}</b> · ${qty} pcs</div>`;
    if (plan.plan && plan.plan.route && plan.plan.route.totalPerPcs !== undefined) {
      html += `<div>Ongkir: ${this._money(plan.plan.route.totalPerPcs)} / pcs</div>`;
    }
    if (plan.plan && plan.plan.price && plan.plan.price.hargaJual !== undefined) {
      html += `<div>Rekomendasi harga jual: ${this._money(plan.plan.price.hargaJual)}</div>`;
    }
    if (plan.plan && plan.plan.fuel && plan.plan.fuel.rpPerKm !== undefined) {
      html += `<div>Estimasi BBM: ${this._money(plan.plan.fuel.rpPerKm)} / km</div>`;
    }
    if (plan.profit && plan.profit.ok !== false && plan.profit.untung !== undefined) {
      html += `<div>Estimasi untung: ${this._money(plan.profit.untung)}</div>`;
    }

    // Berat/volume muatan — hanya ditampilkan kalau produk sudah punya
    // data berat/dimensi (S203, field baru productModal). Reuse
    // TripEngine.weight()/volume() (S198), tidak ada rumus baru.
    if (product.beratPerUnit > 0) {
      const w = TripEngine.weight({ beratPerUnit: product.beratPerUnit, qty });
      if (w.ok) html += `<div>Total berat: ${w.totalKg.toFixed(2)} kg</div>`;
    }
    if (product.panjang > 0 && product.lebar > 0 && product.tinggi > 0) {
      const vol = TripEngine.volume({
        panjang: product.panjang, lebar: product.lebar, tinggi: product.tinggi, qty,
      });
      if (vol.ok) html += `<div>Total volume: ${vol.totalM3.toFixed(3)} m³</div>`;
    }

    box.innerHTML = html || 'Isi data pengiriman untuk melihat ringkasan.';

    this._renderCapacityBox({ product, qty, vehicleId });
  },

  // _renderCapacityBox({product,qty,vehicleId}) — sambungkan
  // TripEngine.vehicleCapacity() (delegasi PERSIS calculateVehicleCapacity(),
  // cobek-pricing.js — sudah ada, cuma belum pernah dipanggil dari UI mana
  // pun, lihat audit #3) ke #dpCapacityBox. TIDAK ADA rumus baru di sini —
  // murni kumpulkan {vehicleId, items:[{...produk,qty}], capacityKg/M3,
  // kmPerTrip} dari form + D.vehicles, lalu render hasilnya. Kalau kendaraan
  // belum dipilih atau belum punya capacityKg/M3 -> tampilkan hint ramah +
  // pintas ke Kelola Kendaraan, box tetap ditampilkan (bukan disembunyikan)
  // supaya hint kelihatan.
  _renderCapacityBox({ product, qty, vehicleId }) {
    const box = document.getElementById('dpCapacityBox');
    if (!box) return;
    if (!vehicleId) { box.classList.add('u-dnone'); box.innerHTML = ''; return; }
    box.classList.remove('u-dnone');
    const vehicle = (D.vehicles || []).find((v) => v.id === vehicleId);
    if (!vehicle) { box.classList.add('u-dnone'); box.innerHTML = ''; return; }
    if (!vehicle.capacityKg && !vehicle.capacityM3) {
      box.innerHTML = '⚠️ Isi kapasitas angkut di Kelola Kendaraan dulu supaya cek muatan bisa jalan.'
        + ' <span style="color:var(--accent);cursor:pointer;font-weight:600" data-action="openVehicleModal">Buka Kelola Kendaraan →</span>';
      return;
    }
    if (typeof TripEngine === 'undefined' || typeof TripEngine.vehicleCapacity !== 'function') {
      box.innerHTML = '';
      return;
    }
    const kmPerTrip = this.metode === 'antar' ? document.getElementById('dpKmKonsumen')?.value : undefined;
    const items = [{
      beratPerUnit: product.beratPerUnit || 0,
      panjang: product.panjang || 0,
      lebar: product.lebar || 0,
      tinggi: product.tinggi || 0,
      qty,
    }];
    const cap = TripEngine.vehicleCapacity({
      vehicleId, items, capacityKg: vehicle.capacityKg, capacityM3: vehicle.capacityM3, kmPerTrip,
    });
    if (!cap.ok) { box.innerHTML = escapeHtml(cap.reason || 'Belum bisa dihitung kapasitas.'); return; }
    const statusColor = cap.status === 'OVERLOAD' ? 'var(--accent2)' : cap.status === 'HAMPIR OVERLOAD' ? 'var(--accent4)' : 'var(--accent3)';
    let html = `<div><b>Muatan:</b> ${cap.totalKg.toFixed(2)} kg`
      + (cap.totalM3 ? ` · ${cap.totalM3.toFixed(3)} m³` : '') + '</div>';
    if (cap.status) {
      html += `<div style="margin-top:4px"><b style="color:${statusColor}">${escapeHtml(cap.status)}</b>`
        + (cap.percentUsed !== null ? ` (${cap.percentUsed}% kapasitas)` : '') + '</div>';
    }
    if (cap.sisaKapasitasKg !== null) {
      html += `<div>Sisa kapasitas: ${cap.sisaKapasitasKg.toFixed(2)} kg`
        + (cap.sisaKapasitasM3 !== null ? ` · ${cap.sisaKapasitasM3.toFixed(3)} m³` : '') + '</div>';
    }
    if (cap.biayaBBMPerTrip !== null) {
      const totalBbm = cap.trips > 1 ? cap.biayaBBMPerTrip * cap.trips : cap.biayaBBMPerTrip;
      html += `<div>Estimasi BBM: ${this._money(cap.biayaBBMPerTrip)} / rit`
        + (cap.trips > 1 ? ` × ${cap.trips} rit = ${this._money(totalBbm)}` : '') + '</div>';
    }
    if (cap.trips > 1) {
      html += `<div style="margin-top:4px;color:${statusColor};font-weight:600">🚛 Muatan ini butuh ${cap.trips} rit (${escapeHtml(cap.limitingFactor || '')} yang jadi batas).</div>`;
    }
    box.innerHTML = html;
  },

  // askAI() — 100% reuse requestAIRecommendation() (cobek-order.js, S6),
  // TIDAK ada prompt/logic AI baru di sini — murni oper parameter form yang
  // sama dgn calc() lalu tampilkan aiText hasilnya.
  async askAI() {
    if (typeof requestAIRecommendation !== 'function') return;
    const box = document.getElementById('dpAiBox');
    if (!box) return;
    box.classList.remove('u-dnone');
    box.innerHTML = 'Meminta rekomendasi AI...';
    const productId = document.getElementById('dpProduct')?.value;
    const qty = document.getElementById('dpQty')?.value;
    const produsenId = document.getElementById('dpProdusen')?.value || null;
    const kmKonsumen = document.getElementById('dpKmKonsumen')?.value;
    const biayaPerKmKonsumen = document.getElementById('dpBiayaKmKonsumen')?.value;
    const vehicleId = document.getElementById('dpVehicle')?.value || null;
    const marginPct = document.getElementById('dpMarginPct')?.value;
    try {
      const result = await requestAIRecommendation({
        productId, qty, produsenId, kmKonsumen, biayaPerKmKonsumen,
        metode: this.metode, vehicleId, marginPct: marginPct !== '' ? marginPct : undefined,
      });
      if (result && result.aiText) {
        box.innerHTML = escapeHtml(result.aiText).replace(/\n/g, '<br>');
      } else if (result && result.prompt) {
        box.innerHTML = escapeHtml(result.aiReason || 'Belum ada API Key AI — isi dulu di Pengaturan.');
      } else {
        box.innerHTML = escapeHtml((result && result.reason) || 'Gagal mendapat rekomendasi.');
      }
    } catch (e) {
      box.innerHTML = 'Gagal meminta rekomendasi AI.';
    }
  },
};

if (typeof window !== 'undefined') {
  window.DeliveryPlanUI = DeliveryPlanUI;
}

// modules/shop/shop-business-engine-presenter.js — Shop Business Engine
// Presenter (Sesi 199, Finalisasi Integrasi Shop). Target sesi: audit
// menemukan PurchaseEngine/TripEngine/InventoryEngine/ProfitEngine (S198,
// modules/shop/*-engine.js) sudah lengkap + ada test, tapi TIDAK PERNAH
// dipanggil dari file render/presenter manapun — belum ada UI sama sekali
// (gap yang sama seperti PropertyManagementAPI di S102, ditutup di Sesi
// 132 lewat PropertyManagementPresenter). File ini menutup gap itu untuk
// Shop, pola SAMA PERSIS PropertyManagementPresenter.render()
// (modules/asset/property-management-presenter.js): UI hanya presenter,
// container findash-grid generik yang sama.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// InventoryEngine/PurchaseEngine/ProfitEngine (S198) — TIDAK ada rumus
// baru, TIDAK menghitung ulang margin/stok/restock apa pun, TIDAK
// membaca D langsung kecuali D.cobek/D.products (dioper sbg parameter ke
// engine, persis kontrak engine-nya). TripEngine (S198) tidak dipakai di
// sini — tidak ada ringkasan "pengiriman" yang relevan ditampilkan di
// Dashboard/Laporan (murni kalkulator per-transaksi, dipakai langsung di
// form Order/Kasir sesuai desain aslinya).
//
// Ownership Engine (S191, disinkronkan Sesi 194 ke Laporan/Statistik/
// Grafik/Dashboard/AI Insight Shop): agregat omzet/untung Shop di sini
// HANYA menghitung transaksi ownership SELF, reuse isCobekOwnershipSelf()
// (modules/shared/ownership-engine.js) — guard typeof supaya fallback
// aman (anggap SELF) kalau ownership-engine.js belum dimuat, PERSIS pola
// yang sama dipakai ShopInsight/Laporan (cobek-order.js) sejak S194. 0
// baris logic ownership yang diubah di sini.
//
// Dipanggil dari (semua tambahan murni, 0 baris lain diubah):
//   - DashboardHub.render() (dashboard-hub.js) -> render() -> mengisi
//     #shopBusinessEngineGrid (Dashboard Hub, index.html/
//     app_production.html), pola sama DanaKelolaanPresenter.render().
//   - renderDashboard() live-wiring (_safeRender, modules/shared/
//     modules-render.js) -> render() lagi, supaya kartu tetap live-update
//     kalau user simpan data dari halaman lain (pola sama
//     PropertyManagementPresenter di blok _safeRender yang sama).
//   - Laporan.renderTab() (modules/shop/cobek-order.js) -> renderTab() ->
//     mengisi #shopBizEngineBody (tab Laporan/Statistik Shop), pola sama
//     DanaKelolaanPresenter.renderStatistik() (dipanggil dari fungsi yang
//     sama, baris setelahnya).
//
// Navigasi silang: dipakai juga oleh ShopInsight (modules/ai/
// feature-insights.js, AI Insight) lewat summary() yang SAMA (satu sumber
// angka, bukan dihitung ulang di 2 tempat) — item insight barunya
// memakai action {page:'shop', navIdx:2} SAMA PERSIS pola action item
// ShopInsight lain (mis. 'shop-stok-menipis').
// SHOP_ENGINE_NAV_TARGETS (Sesi 251, Business Flow Navigation Consistency) —
// tujuan navigasi tiap kartu #shopBusinessEngineGrid. MURNI DATA (0 logic
// navigasi baru), format {page,tab,goTo} SAMA PERSIS format target
// FEATURE_REGISTRY (dashboard-hub-registry.js) & CARD_NAV_TARGETS di
// business-flow-presenter.js (container yang SAMA dipakai kartu Stock/
// Purchase/Sale di sana — TIDAK ADA container baru dibuat), dieksekusi
// lewat dashHubNavigateToFeature() yang SUDAH ADA (dashboard-hub.js).
const SHOP_ENGINE_NAV_TARGETS = Object.freeze({
  inventory: { page: 'shop', tab: 'etalase', goTo: 'productList' },
  purchase: { page: 'shop', tab: 'etalase', goTo: 'stockRekoWidgetList' },
  profit: { page: 'shop', tab: 'riwayat', goTo: 'shopList' },
});

const ShopBusinessEnginePresenter = {

  // _money(n) — helper format, fallback kalau fmt() belum dimuat (pola
  // sama _money-style helper di PropertyManagementPresenter).
  _money(n) {
    return (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
  },

  // _selfFilter() — reuse isCobekOwnershipSelf (S191/S194); fallback
  // fungsi yang selalu true (anggap SELF) kalau ownership-engine.js belum
  // dimuat, PERSIS pola guard yang sama dipakai ShopInsight.compute().
  _selfFilter() {
    return (typeof isCobekOwnershipSelf === 'function') ? isCobekOwnershipSelf : (() => true);
  },

  // summary() — ringkasan murni (TIDAK menyentuh DOM), 100% reuse
  // InventoryEngine/PurchaseEngine/ProfitEngine (S198). Dipisah dari
  // render()/renderTab() supaya bisa dites tanpa DOM & dipakai ulang oleh
  // AI Insight (ShopInsight) tanpa duplikasi hitungan.
  summary() {
    const products = (typeof D !== 'undefined' && D.products) || [];
    const cobek = (typeof D !== 'undefined' && D.cobek) || [];

    // Inventory: nilai stok tertanam (modal & estimasi jual), 100% reuse
    // InventoryEngine.totalModalStok()/totalNilaiJualStok() (S198, sendiri
    // delegasi PERSIS ke Etalase.totalModalStok()/totalNilaiJualStok()).
    let inventory = { ok: false };
    if (typeof InventoryEngine !== 'undefined') {
      inventory = {
        ok: true,
        totalModal: InventoryEngine.totalModalStok(products),
        totalNilaiJual: InventoryEngine.totalNilaiJualStok(products),
      };
    }

    // Purchase: rencana restock dari StockRekoWidget.scan() (via
    // InventoryEngine.restockScan()) + estimasi modal (via
    // PurchaseEngine.estimatedCost()) — 100% reuse S198, 0 rumus baru.
    let purchase = { ok: false };
    if (typeof InventoryEngine !== 'undefined' && typeof PurchaseEngine !== 'undefined') {
      const scan = InventoryEngine.restockScan();
      if (scan.ok) {
        const est = PurchaseEngine.estimatedCost(scan.items);
        purchase = { ok: true, itemCount: est.itemCount, totalQty: est.totalQty, totalCost: est.totalCost };
      }
    }

    // Profit: omzet/untung/margin bulan berjalan, HANYA transaksi
    // ownership SELF (pola Sesi 194) — 100% reuse ProfitEngine.summarize().
    let profit = { ok: false };
    if (typeof ProfitEngine !== 'undefined') {
      const now = new Date();
      const m = now.getMonth();
      const y = now.getFullYear();
      const selfFilter = this._selfFilter();
      const cobThis = cobek
        .filter((t) => { const d = new Date(t.date); return d.getMonth() === m && d.getFullYear() === y; })
        .filter(selfFilter);
      profit = Object.assign({ ok: true }, ProfitEngine.summarize(cobThis));
    }

    return { inventory, purchase, profit };
  },

  // render() — 3 kartu findash-card ke #shopBusinessEngineGrid (Dashboard
  // Hub), PERSIS struktur PropertyManagementPresenter.render().
  render() {
    const el = (typeof document !== 'undefined') ? document.getElementById('shopBusinessEngineGrid') : null;
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    const s = this.summary();
    const cards = [
      this._inventoryCard(s.inventory),
      this._purchaseCard(s.purchase),
      this._profitCard(s.profit),
    ];

    // S251 (Business Flow Navigation Consistency): kartu clickable lewat
    // field `onClick:{action,args}` per-kartu (ditempel di masing2
    // _xxxCard() di bawah) — SAMA PERSIS mekanisme FinanceDashboard.
    // render() (modules/finance/finance-dashboard.js) & BusinessFlow
    // Presenter.render() (business-flow-presenter.js, S251) — reuse
    // data-action + dashHubNavigateToFeature() yang SUDAH ADA, 0 pola
    // navigasi baru.
    el.innerHTML = cards.map((c) => `
      <div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // renderTab() — versi ringkas 2 baris teks ke #shopBizEngineBody (tab
  // Laporan/Statistik Shop, cobek-order.js), pola SAMA PERSIS
  // DanaKelolaanPresenter.renderStatistik() (baris #lapDanaKelolaan).
  renderTab() {
    const el = (typeof document !== 'undefined') ? document.getElementById('shopBizEngineBody') : null;
    if (!el) return;

    const s = this.summary();
    if (!s.purchase.ok && !s.inventory.ok) {
      el.innerHTML = '<div class="u-fs12 u-t2">Business Engine belum tersedia</div>';
      return;
    }

    const restockLine = s.purchase.ok
      ? `${s.purchase.itemCount} produk perlu direstock · estimasi modal ${this._money(s.purchase.totalCost)}`
      : 'Belum ada rekomendasi restock';
    const stokLine = s.inventory.ok
      ? `Nilai stok (modal) ${this._money(s.inventory.totalModal)} · estimasi nilai jual ${this._money(s.inventory.totalNilaiJual)}`
      : '';

    el.innerHTML = `<div class="u-fs12 u-lh15">${escapeHtml(restockLine)}</div>${stokLine ? `<div class="u-fs12 u-t2 u-lh15 u-mt4">${escapeHtml(stokLine)}</div>` : ''}`;
  },

  // _inventoryCard(inv) — inv = summary().inventory, dipakai APA ADANYA
  // (totalModal/totalNilaiJual — 0 recompute, dari InventoryEngine).
  // onClick (S251) reuse SHOP_ENGINE_NAV_TARGETS.inventory.
  _inventoryCard(inv) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [SHOP_ENGINE_NAV_TARGETS.inventory] };
    if (!inv.ok) return { icon: '📦', label: 'Nilai Stok Shop', value: '—', cls: '', sub: 'InventoryEngine belum dimuat', onClick };
    return {
      icon: '📦',
      label: 'Nilai Stok Shop',
      value: this._money(inv.totalModal),
      cls: '',
      sub: `Estimasi nilai jual ${this._money(inv.totalNilaiJual)}`,
      onClick,
    };
  },

  // _purchaseCard(p) — p = summary().purchase, dipakai APA ADANYA
  // (itemCount/totalQty/totalCost — 0 recompute, dari
  // InventoryEngine.restockScan() + PurchaseEngine.estimatedCost()).
  // onClick (S251) reuse SHOP_ENGINE_NAV_TARGETS.purchase.
  _purchaseCard(p) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [SHOP_ENGINE_NAV_TARGETS.purchase] };
    if (!p.ok) return { icon: '🧾', label: 'Rencana Restock', value: 'Belum ada rekomendasi', cls: '', sub: '', onClick };
    if (p.itemCount === 0) return { icon: '🧾', label: 'Rencana Restock', value: 'Stok semua produk aman', cls: '', sub: '', onClick };
    return {
      icon: '🧾',
      label: 'Rencana Restock',
      value: `${p.itemCount} produk`,
      cls: 'red',
      sub: `Estimasi modal ${this._money(p.totalCost)} (${p.totalQty} pcs)`,
      onClick,
    };
  },

  // _profitCard(pr) — pr = summary().profit, dipakai APA ADANYA
  // (trip/omzet/untung/marginPct — 0 recompute, dari
  // ProfitEngine.summarize() atas transaksi ownership SELF bulan ini).
  // onClick (S251) reuse SHOP_ENGINE_NAV_TARGETS.profit.
  _profitCard(pr) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [SHOP_ENGINE_NAV_TARGETS.profit] };
    if (!pr.ok) return { icon: '📈', label: 'Margin Shop Bulan Ini', value: '—', cls: '', sub: 'ProfitEngine belum dimuat', onClick };
    if (pr.trip === 0) return { icon: '📈', label: 'Margin Shop Bulan Ini', value: 'Belum ada transaksi', cls: '', sub: '', onClick };
    return {
      icon: '📈',
      label: 'Margin Shop Bulan Ini',
      value: Math.round(pr.marginPct) + '%',
      cls: '',
      sub: `Omzet ${this._money(pr.omzet)} · Untung ${this._money(pr.untung)} · ${pr.trip} transaksi (SELF)`,
      onClick,
    };
  },

};

// modules/shop/trip-presenter.js — Trip Presenter (Sesi 204-A). Menutup
// gap yang dicatat eksplisit di shop-business-engine-presenter.js:
// "TripEngine (S198) tidak dipakai di sini — tidak ada ringkasan
// 'pengiriman' yang relevan ditampilkan di Dashboard/Laporan". Sesi 203
// sudah menghubungkan TripEngine ke UI per-transaksi (DeliveryPlanUI),
// file ini menutup sisi AGREGAT-nya: Dashboard, Laporan, & AI hook.
//
// PRINSIP: UI HANYA presenter, 100% REUSE field yang SUDAH tersimpan di
// D.cobek (ongkir/delivered/marginPct — field ini sudah ada sejak
// Sesi 6/9, TIDAK ada field D baru sesi ini) & reuse
// getAIDeliveryThinMarginThreshold() (cobek-pricing.js, Sesi 9). TIDAK
// ada rumus baru — cuma agregasi bulan berjalan atas data yang sudah
// tersimpan, pola SAMA PERSIS ShopBusinessEnginePresenter.summary().
//
// Dipanggil dari (semua tambahan murni, 0 baris lain diubah):
//   - DashboardHub.render() (dashboard-hub.js) -> render() -> mengisi
//     #tripPresenterGrid, persis setelah ShopBusinessEnginePresenter.render().
//   - renderDashboard() live-wiring (_safeRender, modules/shared/
//     modules-render.js) -> render() lagi, pola sama.
//   - Laporan.renderTab() (modules/shop/cobek-order.js) -> renderTab() ->
//     mengisi #tripPresenterBody, persis setelah
//     ShopBusinessEnginePresenter.renderTab().
//   - ShopInsight.compute() (modules/ai/feature-insights.js) -> AI hook
//     baru 'shop-trip-thin-margin', 100% reuse summary() (satu sumber
//     angka, bukan dihitung ulang di 2 tempat).
// CARD_NAV_TARGET (Sesi 251, Business Flow Navigation Consistency) —
// tujuan navigasi kartu #tripPresenterGrid. MURNI DATA (0 logic navigasi
// baru), format {page,tab,goTo} SAMA PERSIS target yang dipakai
// BusinessFlowPresenter.openTripPage() (business-flow-presenter.js, S249)
// ke container yang SAMA (#tripPresenterBody, TIDAK ADA container baru),
// dieksekusi lewat dashHubNavigateToFeature() yang SUDAH ADA
// (dashboard-hub.js).
//
// BUGFIX (Sesi 264, audit navigasi shop — sama pola dgn kasus Finance
// Dashboard Sesi 263): SEBELUMNYA tab:'riwayat' — padahal
// #tripPresenterBody hidup di #shopTab-laporan (grep manual index.html),
// bukan #shopTab-riwayat. Efeknya klik kartu Trip melempar ke tab Riwayat
// yang tidak berisi ringkasan Trip-nya.
const CARD_NAV_TARGET = Object.freeze({ page: 'shop', tab: 'laporan', goTo: 'tripPresenterBody' });

const TripPresenter = {

  _money(n) {
    return (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
  },

  // _selfFilter() — reuse isCobekOwnershipSelf (S191/S194), pola SAMA
  // PERSIS ShopBusinessEnginePresenter._selfFilter().
  _selfFilter() {
    return (typeof isCobekOwnershipSelf === 'function') ? isCobekOwnershipSelf : (() => true);
  },

  // summary() — ringkasan pengiriman bulan berjalan (TIDAK menyentuh
  // DOM), murni membaca ulang field yang SUDAH tersimpan di D.cobek
  // (delivered/ongkir/marginPct) — 0 rumus baru. Dipisah dari
  // render()/renderTab() supaya bisa dites tanpa DOM & dipakai ulang
  // oleh AI hook tanpa duplikasi hitungan.
  summary() {
    const cobek = (typeof D !== 'undefined' && D.cobek) || [];
    if (!cobek.length) return { ok: false };

    const now = new Date();
    const m = now.getMonth();
    const y = now.getFullYear();
    const selfFilter = this._selfFilter();
    const thinThreshold = (typeof getAIDeliveryThinMarginThreshold === 'function')
      ? getAIDeliveryThinMarginThreshold() : 10;

    const deliveredThis = cobek
      .filter((t) => t && t.delivered)
      .filter((t) => { const d = new Date(t.date); return d.getMonth() === m && d.getFullYear() === y; })
      .filter(selfFilter);

    if (!deliveredThis.length) {
      return { ok: true, trips: 0, totalOngkir: 0, avgMarginPct: null, thinMarginCount: 0, thinThreshold };
    }

    const totalOngkir = deliveredThis.reduce((s, t) => s + (t.ongkir || 0), 0);
    const withMargin = deliveredThis.filter((t) => typeof t.marginPct === 'number');
    const avgMarginPct = withMargin.length
      ? withMargin.reduce((s, t) => s + t.marginPct, 0) / withMargin.length
      : null;
    const thinMarginCount = withMargin.filter((t) => t.marginPct < thinThreshold).length;

    return {
      ok: true,
      trips: deliveredThis.length,
      totalOngkir,
      avgMarginPct,
      thinMarginCount,
      thinThreshold,
    };
  },

  // getAIHook() — wrapper tipis ke summary(), pola sama
  // VehicleDashboard.getAIHook()/FinanceDashboard.getAIHook() (Sesi
  // 75/77): satu titik akses generik kalau suatu saat dibutuhkan
  // Daily Briefing/ai-chat.js (belum diwiring ke sana sesi ini — di
  // luar scope S204-A, sama seperti kandidat lama VehicleAIHook).
  getAIHook() {
    return this.summary();
  },

  // render() — 1 kartu findash-card ke #tripPresenterGrid (Dashboard
  // Hub), pola SAMA PERSIS ShopBusinessEnginePresenter.render().
  render() {
    const el = (typeof document !== 'undefined') ? document.getElementById('tripPresenterGrid') : null;
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    const s = this.summary();
    const card = this._tripCard(s);
    // S251 (Business Flow Navigation Consistency): reuse `onClick:
    // {action,args}` per-kartu, SAMA PERSIS FinanceDashboard.render()/
    // BusinessFlowPresenter.render()/ShopBusinessEnginePresenter.render().
    el.innerHTML = `
      <div class="findash-card${card.onClick ? ' u-pointer' : ''}"${card.onClick ? ` data-action="${escapeHtml(card.onClick.action)}" data-args="${escapeHtml(JSON.stringify(card.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${card.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(card.label)}</div>
          <div class="findash-card-val${card.cls ? ' ' + card.cls : ''}">${escapeHtml(card.value)}</div>
          ${card.sub ? `<div class="findash-card-sub">${escapeHtml(card.sub)}</div>` : ''}
        </div>
      </div>
    `;
  },

  // renderTab() — versi ringkas 1 baris teks ke #tripPresenterBody (tab
  // Laporan/Statistik Shop), pola SAMA PERSIS
  // ShopBusinessEnginePresenter.renderTab().
  renderTab() {
    const el = (typeof document !== 'undefined') ? document.getElementById('tripPresenterBody') : null;
    if (!el) return;

    const s = this.summary();
    if (!s.ok || s.trips === 0) {
      el.innerHTML = '<div class="u-fs12 u-t2">Belum ada pengiriman tercatat bulan ini</div>';
      return;
    }

    const marginLine = s.avgMarginPct !== null
      ? ` · rata-rata margin ${Math.round(s.avgMarginPct)}%${s.thinMarginCount > 0 ? ` (${s.thinMarginCount} margin tipis)` : ''}`
      : '';
    el.innerHTML = `<div class="u-fs12 u-lh15">${escapeHtml(`${s.trips} pengiriman · total ongkir ${this._money(s.totalOngkir)}${marginLine}`)}</div>`;
  },

  // _tripCard(s) — s = summary(), dipakai APA ADANYA (0 recompute).
  // onClick (S251) reuse CARD_NAV_TARGET (SAMA container dipakai
  // BusinessFlowPresenter.openTripPage()).
  _tripCard(s) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [CARD_NAV_TARGET] };
    if (!s.ok || s.trips === 0) {
      return { icon: '🚚', label: 'Pengiriman Bulan Ini', value: 'Belum ada pengiriman', cls: '', sub: '', onClick };
    }
    return {
      icon: '🚚',
      label: 'Pengiriman Bulan Ini',
      value: `${s.trips} trip`,
      cls: s.thinMarginCount > 0 ? 'red' : '',
      sub: `Total ongkir ${this._money(s.totalOngkir)}`
        + (s.avgMarginPct !== null ? ` · rata-rata margin ${Math.round(s.avgMarginPct)}%` : ''),
      onClick,
    };
  },

};

